import React from 'react'
import { Box, CircularProgress, Typography, Button, Alert, Snackbar } from '@mui/material'
import { styled } from '@mui/material/styles'

// 样式化的组件
const LoadingContainer = styled(Box)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  padding: theme.spacing(8, 2),
  minHeight: '300px',
}))

const EmptyStateContainer = styled(Box)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  padding: theme.spacing(8, 2),
  minHeight: '300px',
  textAlign: 'center',
}))

const ErrorStateContainer = styled(Box)(({ theme }) => ({
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  justifyContent: 'center',
  padding: theme.spacing(8, 2),
  minHeight: '300px',
  textAlign: 'center',
}))

// 加载状态组件
interface LoadingStateProps {
  message?: string
  size?: number
}

export const LoadingState: React.FC<LoadingStateProps> = ({ 
  message = '正在加载数据...', 
  size = 60 
}) => {
  return (
    <LoadingContainer>
      <CircularProgress size={size} />
      <Typography variant="h6" sx={{ mt: 2 }}>
        {message}
      </Typography>
    </LoadingContainer>
  )
}

// 空数据状态组件
interface EmptyStateProps {
  icon: React.ReactNode
  title: string
  description?: string
  action?: {
    label: string
    onClick: () => void
  }
}

export const EmptyState: React.FC<EmptyStateProps> = ({ 
  icon, 
  title, 
  description,
  action 
}) => {
  return (
    <EmptyStateContainer>
      <Box sx={{ fontSize: 80, color: 'text.secondary', mb: 2 }}>
        {icon}
      </Box>
      <Typography variant="h5" color="text.secondary" gutterBottom>
        {title}
      </Typography>
      {description && (
        <Typography variant="body1" color="text.secondary" paragraph>
          {description}
        </Typography>
      )}
      {action && (
        <Button variant="contained" onClick={action.onClick}>
          {action.label}
        </Button>
      )}
    </EmptyStateContainer>
  )
}

// 错误状态组件
interface ErrorStateProps {
  title?: string
  message: string
  retryAction?: {
    label: string
    onClick: () => void
  }
  showIcon?: boolean
}

export const ErrorState: React.FC<ErrorStateProps> = ({ 
  title = '发生错误',
  message,
  retryAction,
  showIcon = true
}) => {
  return (
    <ErrorStateContainer>
      {showIcon && (
        <Box sx={{ fontSize: 80, color: 'error.main', mb: 2 }}>
          ⚠️
        </Box>
      )}
      <Typography variant="h5" color="error.main" gutterBottom>
        {title}
      </Typography>
      <Typography variant="body1" color="text.secondary" paragraph>
        {message}
      </Typography>
      {retryAction && (
        <Button 
          variant="contained" 
          color="primary" 
          onClick={retryAction.onClick}
          sx={{ mt: 2 }}
        >
          {retryAction.label}
        </Button>
      )}
    </ErrorStateContainer>
  )
}

// 状态包装器组件
interface StateWrapperProps {
  loading: boolean
  error: string | null
  empty: boolean
  children: React.ReactNode
  loadingMessage?: string
  emptyIcon: React.ReactNode
  emptyTitle: string
  emptyDescription?: string
  emptyAction?: {
    label: string
    onClick: () => void
  }
  errorTitle?: string
  retryAction?: {
    label: string
    onClick: () => void
  }
}

export const StateWrapper: React.FC<StateWrapperProps> = ({
  loading,
  error,
  empty,
  children,
  loadingMessage,
  emptyIcon,
  emptyTitle,
  emptyDescription,
  emptyAction,
  errorTitle,
  retryAction
}) => {
  if (loading) {
    return <LoadingState message={loadingMessage} />
  }

  if (error) {
    return (
      <ErrorState
        title={errorTitle}
        message={error}
        retryAction={retryAction}
      />
    )
  }

  if (empty) {
    return (
      <EmptyState
        icon={emptyIcon}
        title={emptyTitle}
        description={emptyDescription}
        action={emptyAction}
      />
    )
  }

  return <>{children}</>
}

// 通知组件
interface NotificationProps {
  open: boolean
  message: string
  severity?: 'success' | 'error' | 'warning' | 'info'
  onClose?: () => void
  autoHideDuration?: number
}

export const Notification: React.FC<NotificationProps> = ({
  open,
  message,
  severity = 'info',
  onClose,
  autoHideDuration = 6000
}) => {
  return (
    <Snackbar
      open={open}
      autoHideDuration={autoHideDuration}
      onClose={onClose}
    >
      <Alert onClose={onClose} severity={severity} sx={{ width: '100%' }}>
        {message}
      </Alert>
    </Snackbar>
  )
}