/**
 * 统一API接口层
 * 提供统一的API接口，封装数据加载和缓存逻辑
 */

import { blogDataService } from './blogDataLoader';
import { entertainmentDataService } from './entertainmentDataLoader';
import { cacheUpdateManager } from './cacheUpdateStrategy';
import { dataService } from './dataCache';
import { useState, useEffect } from 'react';
import { MediaFileWithId, MediaQueryParams } from './api';
import { BlogPostWithId } from '../types/blog';

// 博客相关API接口
export interface BlogAPI {
  // 获取博客文章列表
  getBlogPosts: (params?: any) => Promise<any>;
  
  // 获取单个博客文章
  getBlogPost: (slug: string) => Promise<any>;
  
  // 获取博客统计信息
  getBlogStats: () => Promise<any>;
  
  // 搜索博客文章
  searchBlogPosts: (searchTerm: string, params?: any) => Promise<any>;
  
  // 按分类获取博客文章
  getBlogPostsByCategory: (category: string, params?: any) => Promise<any>;
  
  // 按标签获取博客文章
  getBlogPostsByTag: (tag: string, params?: any) => Promise<any>;
  
  // 获取相邻文章（上一篇和下一篇）
  getAdjacentPosts: (slug: string) => Promise<{ previous: BlogPostWithId | null; next: BlogPostWithId | null }>;
  
  // 刷新博客文章缓存
  refreshBlogPosts: (params?: any) => Promise<any>;
  
  // 刷新单个博客文章缓存
  refreshBlogPost: (slug: string) => Promise<any>;
  
  // 刷新博客统计信息缓存
  refreshBlogStats: () => Promise<any>;
  
  // 预加载博客数据
  preloadBlogData: () => Promise<void>;
}

// 娱乐相关API接口
export interface EntertainmentAPI {
  // 获取媒体文件列表
  getMediaFiles: (params?: any) => Promise<any>;
  
  // 获取单个媒体文件
  getMediaFile: (id: string) => Promise<any>;
  
  // 获取媒体统计信息
  getMediaStats: () => Promise<any>;
  
  // 搜索媒体文件
  searchMediaFiles: (searchTerm: string, params?: any) => Promise<any>;
  
  // 按类型获取媒体文件
  getMediaFilesByType: (type: 'image' | 'video' | 'audio' | 'other', params?: any) => Promise<any>;
  
  // 按分类获取媒体文件
  getMediaFilesByCategory: (category: string, params?: any) => Promise<any>;
  
  // 获取音频文件
  getAudioFiles: (params?: any) => Promise<any>;
  
  // 获取图片文件
  getImageFiles: (params?: any) => Promise<any>;
  
  // 获取视频文件
  getVideoFiles: (params?: any) => Promise<any>;
  
  // 刷新媒体文件缓存
  refreshMediaFiles: (params?: any) => Promise<any>;
  
  // 刷新单个媒体文件缓存
  refreshMediaFile: (id: string) => Promise<any>;
  
  // 刷新媒体统计信息缓存
  refreshMediaStats: () => Promise<any>;
  
  // 预加载媒体数据
  preloadMediaData: () => Promise<void>;
  
  // 预加载特定类型的媒体数据
  preloadMediaDataByType: (type: 'image' | 'video' | 'audio' | 'other') => Promise<void>;
  
  // 清空媒体缓存
  clearMediaCache: () => void;
}

// 缓存管理API接口
export interface CacheAPI {
  // 获取缓存统计信息
  getCacheStats: () => any;
  
  // 清空所有缓存
  clearAllCache: () => void;
  
  // 清空特定缓存
  clearCache: (key: string) => void;
  
  // 预加载数据
  preloadData: (keys: string[]) => Promise<void>;
  
  // 手动更新缓存
  updateCache: (dataType: string) => Promise<void>;
  
  // 更新所有缓存
  updateAllCaches: () => Promise<void>;
  
  // 添加缓存更新监听器
  addCacheUpdateListener: (listener: (event: any) => void) => void;
  
  // 移除缓存更新监听器
  removeCacheUpdateListener: (listener: (event: any) => void) => void;
}

// 统一API接口
export interface UnifiedAPI {
  blog: BlogAPI;
  entertainment: EntertainmentAPI;
  cache: CacheAPI;
}

/**
 * 实现博客API接口
 */
const blogAPI: BlogAPI = {
  getBlogPosts: (params) => blogDataService.getBlogPosts(params),
  getBlogPost: (slug) => blogDataService.getBlogPost(slug),
  getBlogStats: () => blogDataService.getBlogStats(),
  searchBlogPosts: (searchTerm, params) => blogDataService.searchBlogPosts(searchTerm, params),
  getBlogPostsByCategory: (category, params) => blogDataService.getBlogPosts({ ...params, category }),
  getBlogPostsByTag: (tag, params) => blogDataService.getBlogPosts({ ...params, tag }),
  getAdjacentPosts: async (slug) => {
    try {
      // 获取所有文章，按日期排序
      const result = await blogDataService.getBlogPosts({ limit: 1000 });
      const allPosts = result.posts || [];
      
      // 按日期降序排序（最新的在前）
      const sortedPosts = [...allPosts].sort((a, b) => {
        const dateA = new Date(a.date || a.createdAt || 0).getTime();
        const dateB = new Date(b.date || b.createdAt || 0).getTime();
        return dateB - dateA;
      });
      
      // 找到当前文章的索引
      const currentIndex = sortedPosts.findIndex(post => post.slug === slug);
      
      if (currentIndex === -1) {
        return { previous: null, next: null };
      }
      
      // 获取上一篇和下一篇文章
      const previous = currentIndex > 0 ? sortedPosts[currentIndex - 1] : null;
      const next = currentIndex < sortedPosts.length - 1 ? sortedPosts[currentIndex + 1] : null;
      
      return { previous, next };
    } catch (error) {
      console.error('获取相邻文章失败:', error);
      return { previous: null, next: null };
    }
  },
  refreshBlogPosts: async (params) => {
    blogDataService.clearBlogCache();
    return blogDataService.getBlogPosts(params);
  },
  refreshBlogPost: async (slug) => {
    blogDataService.clearBlogCache();
    return blogDataService.getBlogPost(slug);
  },
  refreshBlogStats: async () => {
    blogDataService.clearBlogCache();
    return blogDataService.getBlogStats();
  },
  preloadBlogData: () => blogDataService.preloadBlogData()
};

/**
 * 实现娱乐API接口
 */
const entertainmentAPI: EntertainmentAPI = {
  getMediaFiles: (params) => entertainmentDataService.getMediaFiles(params),
  getMediaFile: (id) => entertainmentDataService.getMediaFile(id),
  getMediaStats: () => entertainmentDataService.getMediaStats(),
  searchMediaFiles: (searchTerm, params) => entertainmentDataService.searchMediaFiles(searchTerm, params),
  getMediaFilesByType: (type, params) => entertainmentDataService.getMediaFilesByType(type, params),
  getMediaFilesByCategory: (category, params) => entertainmentDataService.getMediaFilesByCategory(category, params),
  getAudioFiles: (params) => entertainmentDataService.getAudioFiles(params),
  getImageFiles: (params) => entertainmentDataService.getImageFiles(params),
  getVideoFiles: (params) => entertainmentDataService.getVideoFiles(params),
  refreshMediaFiles: async (params) => {
    entertainmentDataService.clearMediaCache();
    return entertainmentDataService.getMediaFiles(params);
  },
  refreshMediaFile: async (id) => {
    entertainmentDataService.clearMediaCache();
    return entertainmentDataService.getMediaFile(id);
  },
  refreshMediaStats: async () => {
    entertainmentDataService.clearMediaCache();
    return entertainmentDataService.getMediaStats();
  },
  preloadMediaData: () => entertainmentDataService.preloadMediaData(),
  preloadMediaDataByType: (type) => entertainmentDataService.preloadMediaDataByType(type),
  clearMediaCache: () => entertainmentDataService.clearMediaCache()
};

/**
 * 实现缓存API接口
 */
const cacheAPI: CacheAPI = {
  getCacheStats: () => dataService.getCacheStats(),
  clearAllCache: () => dataService.clearAllCache(),
  clearCache: (key) => {
    // 由于dataService没有clearCache方法，我们使用refreshData来清除特定缓存
    try {
      dataService.refreshData(key);
    } catch (error) {
      console.error(`清除缓存失败，key: ${key}`, error);
      // 如果refreshData失败，则清除所有缓存
      dataService.clearAllCache();
    }
  },
  preloadData: (keys) => dataService.preloadData(keys),
  updateCache: (dataType) => cacheUpdateManager.manualUpdate(dataType),
  updateAllCaches: () => cacheUpdateManager.updateAllCaches(),
  addCacheUpdateListener: (listener) => cacheUpdateManager.addListener(listener),
  removeCacheUpdateListener: (listener) => cacheUpdateManager.removeListener(listener)
};

/**
 * 统一API实例
 */
export const api: UnifiedAPI = {
  blog: blogAPI,
  entertainment: entertainmentAPI,
  cache: cacheAPI
};

/**
 * 初始化API
 */
export async function initializeAPI(): Promise<void> {
  console.log('初始化API');
  
  // 初始化缓存更新管理器
  await cacheUpdateManager.initialize();
  
  // 预加载关键数据
  try {
    await Promise.all([
      api.blog.preloadBlogData(),
      api.entertainment.preloadMediaData()
    ]);
  } catch (error) {
    console.error('预加载数据失败:', error);
    // 预加载失败不应该阻止应用启动
  }
  
  console.log('API初始化完成');
}

/**
 * 销毁API
 */
export async function destroyAPI(): Promise<void> {
  console.log('销毁API');
  
  // 销毁缓存更新管理器
  await cacheUpdateManager.destroy();
  
  console.log('API已销毁');
}

// 导出API实例和初始化函数
export default api;

// React Hook for using media files
export const useMediaFiles = (params?: MediaQueryParams) => {
  const [files, setFiles] = useState<MediaFileWithId[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadFiles = async () => {
      try {
        setLoading(true);
        setError(null);
        const result = await api.entertainment.getMediaFiles(params || {});
        setFiles(result.files || result);
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : '未知错误';
        setError(errorMessage);
        console.error('加载媒体文件失败:', err);
      } finally {
        setLoading(false);
      }
    };

    loadFiles();
  }, [JSON.stringify(params)]);

  return { files, loading, error };
};

// React Hook for using adjacent blog posts
export const useAdjacentPosts = (slug: string) => {
  const [adjacentPosts, setAdjacentPosts] = useState<{ previous: BlogPostWithId | null; next: BlogPostWithId | null }>({ previous: null, next: null });
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadAdjacentPosts = async () => {
      try {
        setLoading(true);
        setError(null);
        const result = await api.blog.getAdjacentPosts(slug);
        setAdjacentPosts(result);
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : '未知错误';
        setError(errorMessage);
        console.error('加载相邻文章失败:', err);
      } finally {
        setLoading(false);
      }
    };

    if (slug) {
      loadAdjacentPosts();
    }
  }, [slug]);

  return { adjacentPosts, loading, error };
};