const categories = ['全部', '户外活动', '美食', '音乐', '旅行', '阅读', '摄影']
const sortOptions = ['最新发布', '最多浏览', '最多点赞']

const Life = () => {
  const [posts, setPosts] = useState(mockLifePosts)
  const [loading, setLoading] = useState(false)
  const [page, setPage] = useState(1)
  const [category, setCategory] = useState('全部')
  const [sortBy, setSortBy] = useState('最新发布')
  const [selectedPost, setSelectedPost] = useState<any>(null)
  const [dialogOpen, setDialogOpen] = useState(false)
  const [error] = useState('')
  
  const postsPerPage = 6
  const { isAuthenticated } = useSelector((state: RootState) => state.auth)

  useEffect(() => {
    // 模拟数据获取
    setLoading(true)
    setTimeout(() => {
      // 这里可以根据分类和排序选项过滤和排序数据
      let filteredPosts = [...mockLifePosts]
      
      if (category !== '全部') {
        filteredPosts = filteredPosts.filter(post => post.category === category)
      }
      
      if (sortBy === '最多浏览') {
        filteredPosts.sort((a, b) => b.viewCount - a.viewCount)
      } else if (sortBy === '最多点赞') {
        filteredPosts.sort((a, b) => b.likeCount - a.likeCount)
      }
      
      setPosts(filteredPosts)
      setLoading(false)
    }, 500)
  }, [category, sortBy])

  const handlePageChange = (_event: React.ChangeEvent<unknown>, value: number) => {
    setPage(value)
  }

  const handleCategoryChange = (event: any) => {
    setCategory(event.target.value)
    setPage(1)
  }

  const handleSortChange = (event: any) => {
    setSortBy(event.target.value)
    setPage(1)
  }

  const handlePostClick = (post: any) => {
    setSelectedPost(post)
    setDialogOpen(true)
  }

  const handleDialogClose = () => {
    setDialogOpen(false)
    setSelectedPost(null)
  }

  const getTypeIcon = (type: string) => {
    switch (type) {
      case 'image':
        return <Image />
      case 'video':
        return <VideoFile />
      case 'music':
        return <MusicNote />
      case 'article':
        return <Article />
      default:
        return <Article />
    }
  }

  const indexOfLastPost = page * postsPerPage
  const indexOfFirstPost = indexOfLastPost - postsPerPage
  const currentPosts = posts.slice(indexOfFirstPost, indexOfLastPost)
  const totalPages = Math.ceil(posts.length / postsPerPage)

  return (
    <Container maxWidth="lg" sx={{ py: 4 }}>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h3" component="h1" gutterBottom>
          休闲娱乐
        </Typography>
        <Typography variant="h6" color="text.secondary">
          分享生活点滴，记录美好时光
        </Typography>
      </Box>

      {isAuthenticated && (
        <Box sx={{ mb: 3, display: 'flex', justifyContent: 'flex-end' }}>
          <Button variant="contained" href="/life/create">
            分享生活
          </Button>
        </Box>
      )}

      <Paper sx={{ p: 2, mb: 3 }}>
        <Grid container spacing={2} alignItems="center">
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
            <FormControl fullWidth variant="outlined" size="small">
              <InputLabel>分类</InputLabel>
              <Select
                value={category}
                onChange={handleCategoryChange}
                label="分类"
              >
                {categories.map((cat) => (
                  <MenuItem key={cat} value={cat}>
                    {cat}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
          <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <FormControl fullWidth variant="outlined" size="small">
            <InputLabel>排序</InputLabel>
            <Select
              value={sortBy}
              onChange={handleSortChange}
              label="排序"
            >
              {sortOptions.map((option) => (
                <MenuItem key={option} value={option}>
                  {option}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>
        </Grid>
      </Paper>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 4 }}>
          <CircularProgress />
        </Box>
      ) : error ? (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      ) : (
        <>
          <Grid container spacing={3}>
            {currentPosts.map((post) => (
              <Grid size={{ xs: 12, sm: 6, md: 4 }} key={post.id}>
                <Card 
                  sx={{ height: '100%', display: 'flex', flexDirection: 'column', cursor: 'pointer' }}
                  onClick={() => handlePostClick(post)}
                >
                  <CardMedia
                    component="div"
                    sx={{
                      height: 200,
                      backgroundImage: `url(${post.mediaUrl})`,
                      backgroundSize: 'cover',
                      backgroundPosition: 'center',
                      position: 'relative',
                    }}
                  >
                    <Box
                      sx={{
                        position: 'absolute',
                        top: 8,
                        right: 8,
                        backgroundColor: 'rgba(0, 0, 0, 0.6)',
                        borderRadius: '50%',
                        width: 36,
                        height: 36,
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        color: 'white',
                      }}
                    >
                      {getTypeIcon(post.type)}
                    </Box>
                    {post.type === 'video' && (
                      <Box
                        sx={{
                          position: 'absolute',
                          top: '50%',
                          left: '50%',
                          transform: 'translate(-50%, -50%)',
                          backgroundColor: 'rgba(0, 0, 0, 0.6)',
                          borderRadius: '50%',
                          width: 48,
                          height: 48,
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          color: 'white',
                        }}
                      >
                        <PlayArrow />
                      </Box>
                    )}
                  </CardMedia>
                  <CardContent sx={{ flexGrow: 1 }}>
                    <Typography variant="h6" component="h2" gutterBottom>
                      {post.title}
                    </Typography>
                    <Typography variant="body2" color="text.secondary" paragraph>
                      {post.summary}
                    </Typography>
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 2 }}>
                      {post.tags.map((tag) => (
                        <Chip key={tag} label={tag} size="small" variant="outlined" />
                      ))}
                    </Box>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                      <Box sx={{ display: 'flex', alignItems: 'center' }}>
                        <Avatar sx={{ width: 24, height: 24, mr: 1 }}>
                          {post.author.name.charAt(0)}
                        </Avatar>
                        <Typography variant="body2">
                          {post.author.name}
                        </Typography>
                      </Box>
                      <Box sx={{ display: 'flex', alignItems: 'center', color: 'text.secondary' }}>
                        <CalendarToday sx={{ fontSize: 16, mr: 0.5 }} />
                        <Typography variant="body2">
                          {post.createdAt}
                        </Typography>
                      </Box>
                    </Box>
                    <Divider sx={{ my: 1.5 }} />
                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                      <Box sx={{ display: 'flex', gap: 2 }}>
                        {/* 观看数显示已禁用
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <Visibility sx={{ fontSize: 16, mr: 0.5 }} />
                          <Typography variant="body2">{post.viewCount}</Typography>
                        </Box>
                        */}
                        {/* 点赞数显示已禁用
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <ThumbUp sx={{ fontSize: 16, mr: 0.5 }} />
                          <Typography variant="body2">{post.likeCount}</Typography>
                        </Box>
                        */}
                        {/* 评论数显示已禁用
                        <Box sx={{ display: 'flex', alignItems: 'center' }}>
                          <Comment sx={{ fontSize: 16, mr: 0.5 }} />
                          <Typography variant="body2">{post.commentCount}</Typography>
                        </Box>
                        */}
                      </Box>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>

          {totalPages > 1 && (
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
              <Pagination
                count={totalPages}
                page={page}
                onChange={handlePageChange}
                color="primary"
              />
            </Box>
          )}
        </>
      )}

      {/* 媒体预览对话框 */}
      <Dialog open={dialogOpen} onClose={handleDialogClose} maxWidth="md" fullWidth>
        {selectedPost && (
          <>
            <DialogTitle>
              <Box sx={{ display: 'flex', alignItems: 'center' }}>
                {getTypeIcon(selectedPost.type)}
                <Typography variant="h6" sx={{ ml: 1 }}>
                  {selectedPost.title}
                </Typography>
              </Box>
            </DialogTitle>
            <DialogContent>
              {selectedPost.type === 'image' && (
                <Box
                  component="img"
                  src={selectedPost.mediaUrl}
                  alt={selectedPost.title}
                  sx={{ width: '100%', maxHeight: 400, objectFit: 'contain' }}
                />
              )}
              {selectedPost.type === 'video' && (
                <Box sx={{ position: 'relative', paddingTop: '56.25%' }}>
                  <Box
                    component="img"
                    src={selectedPost.mediaUrl}
                    alt={selectedPost.title}
                    sx={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      width: '100%',
                      height: '100%',
                      objectFit: 'cover',
                    }}
                  />
                  <Box
                    sx={{
                      position: 'absolute',
                      top: '50%',
                      left: '50%',
                      transform: 'translate(-50%, -50%)',
                    }}
                  >
                    <Button
                      variant="contained"
                      startIcon={<PlayArrow />}
                      sx={{ borderRadius: '50%', width: 64, height: 64 }}
                    >
                      播放
                    </Button>
                  </Box>
                </Box>
              )}
              {selectedPost.type === 'music' && (
                <Box sx={{ textAlign: 'center', py: 4 }}>
                  <Box
                    component="img"
                    src={selectedPost.mediaUrl}
                    alt={selectedPost.title}
                    sx={{ width: 200, height: 200, borderRadius: '50%', mb: 2 }}
                  />
                  <Button variant="contained" startIcon={<PlayArrow />}>
                    播放音乐
                  </Button>
                </Box>
              )}
              {selectedPost.type === 'article' && (
                <Box sx={{ py: 2 }}>
                  <Typography variant="body1" paragraph>
                    {selectedPost.content}
                  </Typography>
                </Box>
              )}
              <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
                {selectedPost.summary}
              </Typography>
              <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mt: 2 }}>
                {selectedPost.tags.map((tag: string) => (
                  <Chip key={tag} label={tag} size="small" variant="outlined" />
                ))}
              </Box>
            </DialogContent>
            <DialogActions>
              <Button onClick={handleDialogClose}>关闭</Button>
              <Button variant="contained" href={`/life/${selectedPost.id}`}>
                查看详情
              </Button>
            </DialogActions>
          </>
        )}
      </Dialog>
    </Container>
  )
}

export default Life