/**
 * 娱乐模块数据加载器
 * 集成统一数据缓存服务，提供高效的媒体文件数据加载
 */

import { DataLoader, DataType, CacheKeyStrategy, dataService } from './dataCache';
import { MediaFileWithId, MediaQueryParams, MediaQueryResult, MediaStats } from './api';

// 媒体文件列表加载器
class MediaFilesLoader implements DataLoader<MediaQueryResult> {
  identifier = DataType.MEDIA_FILES;
  private params: MediaQueryParams;

  constructor(params: MediaQueryParams = {}) {
    this.params = params;
  }

  async load(): Promise<MediaQueryResult> {
    console.log(`加载媒体文件列表，参数:`, this.params);
    
    try {
      // 使用新的API获取媒体文件
      const { api } = await import('./api');
      const result = await api.entertainment.getMediaFiles(this.params);
      
      console.log(`成功加载 ${result.files.length} 个媒体文件，共 ${result.total} 个`);
      return result;
    } catch (error) {
      console.error('加载媒体文件列表失败:', error);
      throw error;
    }
  }
}

// 单个媒体文件加载器
class MediaFileLoader implements DataLoader<MediaFileWithId | null> {
  identifier = DataType.MEDIA_FILE;
  private id: string;

  constructor(id: string) {
    this.id = id;
  }

  async load(): Promise<MediaFileWithId | null> {
    console.log(`加载媒体文件，ID: ${this.id}`);
    
    try {
      // 使用新的API获取单个媒体文件
      const { api } = await import('./api');
      const file = await api.entertainment.getMediaFile(this.id);
      
      if (file) {
        console.log(`成功加载媒体文件: ${file.name}`);
        return file;
      } else {
        console.warn(`未找到媒体文件，ID: ${this.id}`);
        return null;
      }
    } catch (error) {
      console.error(`加载媒体文件失败，ID: ${this.id}`, error);
      throw error;
    }
  }
}

// 媒体统计信息加载器
class MediaStatsLoader implements DataLoader<MediaStats> {
  identifier = DataType.MEDIA_STATS;
  dependencies = [DataType.MEDIA_FILES];

  async load(): Promise<MediaStats> {
    console.log('加载媒体统计信息');
    
    try {
      // 使用新的API获取媒体统计信息
      const { api } = await import('./api');
      const stats = await api.entertainment.getMediaStats();
      
      console.log('成功加载媒体统计信息:', stats);
      return stats;
    } catch (error) {
      console.error('加载媒体统计信息失败:', error);
      throw error;
    }
  }
}

// 按类型加载媒体文件的加载器
class MediaFilesByTypeLoader implements DataLoader<MediaQueryResult> {
  identifier = 'media_files_by_type';
  private type: 'image' | 'video' | 'audio' | 'other';
  private params: MediaQueryParams;

  constructor(type: 'image' | 'video' | 'audio' | 'other', params: MediaQueryParams = {}) {
    this.type = type;
    this.params = params;
  }

  async load(): Promise<MediaQueryResult> {
    console.log(`按类型加载媒体文件，类型: ${this.type}，参数:`, this.params);
    
    try {
      // 使用新的API按类型获取媒体文件
      const { api } = await import('./api');
      const result = await api.entertainment.getMediaFilesByType(this.type, this.params);
      
      console.log(`成功加载 ${result.files.length} 个${this.type}类型媒体文件，共 ${result.total} 个`);
      return result;
    } catch (error) {
      console.error(`按类型加载媒体文件失败，类型: ${this.type}`, error);
      throw error;
    }
  }
}

// 按分类加载媒体文件的加载器
class MediaFilesByCategoryLoader implements DataLoader<MediaQueryResult> {
  identifier = 'media_files_by_category';
  private category: string;
  private params: MediaQueryParams;

  constructor(category: string, params: MediaQueryParams = {}) {
    this.category = category;
    this.params = params;
  }

  async load(): Promise<MediaQueryResult> {
    console.log(`按分类加载媒体文件，分类: ${this.category}，参数:`, this.params);
    
    try {
      // 使用新的API按分类获取媒体文件
      const { api } = await import('./api');
      const result = await api.entertainment.getMediaFilesByCategory(this.category, this.params);
      
      console.log(`成功加载 ${result.files.length} 个${this.category}分类媒体文件，共 ${result.total} 个`);
      return result;
    } catch (error) {
      console.error(`按分类加载媒体文件失败，分类: ${this.category}`, error);
      throw error;
    }
  }
}

// 娱乐数据服务
export class EntertainmentDataService {
  private static instance: EntertainmentDataService;
  
  private constructor() {
    // 注册媒体数据加载器
    dataService.registerDataLoader(new MediaFilesLoader());
    dataService.registerDataLoader(new MediaStatsLoader());
  }
  
  static getInstance(): EntertainmentDataService {
    if (!EntertainmentDataService.instance) {
      EntertainmentDataService.instance = new EntertainmentDataService();
    }
    return EntertainmentDataService.instance;
  }
  
  /**
   * 获取媒体文件列表（带缓存）
   */
  async getMediaFiles(params: MediaQueryParams = {}): Promise<MediaQueryResult> {
    const key = CacheKeyStrategy.generateKey(DataType.MEDIA_FILES, params);
    const loader = new MediaFilesLoader(params);
    
    return dataService.getData(key, loader);
  }
  
  /**
   * 获取单个媒体文件（带缓存）
   */
  async getMediaFile(id: string): Promise<MediaFileWithId | null> {
    const key = CacheKeyStrategy.generateKey(DataType.MEDIA_FILE, { id });
    const loader = new MediaFileLoader(id);
    
    return dataService.getData(key, loader);
  }
  
  /**
   * 获取媒体统计信息（带缓存）
   */
  async getMediaStats(): Promise<MediaStats> {
    const key = CacheKeyStrategy.generateKey(DataType.MEDIA_STATS);
    const loader = new MediaStatsLoader();
    
    return dataService.getData(key, loader);
  }
  
  /**
   * 按类型获取媒体文件（带缓存）
   */
  async getMediaFilesByType(
    type: 'image' | 'video' | 'audio' | 'other', 
    params: MediaQueryParams = {}
  ): Promise<MediaQueryResult> {
    const key = CacheKeyStrategy.generateKey('media_files_by_type' as DataType, { type, ...params });
    const loader = new MediaFilesByTypeLoader(type, params);
    
    return dataService.getData(key, loader);
  }
  
  /**
   * 按分类获取媒体文件（带缓存）
   */
  async getMediaFilesByCategory(
    category: string, 
    params: MediaQueryParams = {}
  ): Promise<MediaQueryResult> {
    const key = CacheKeyStrategy.generateKey('media_files_by_category' as DataType, { category, ...params });
    const loader = new MediaFilesByCategoryLoader(category, params);
    
    return dataService.getData(key, loader);
  }
  
  /**
   * 搜索媒体文件（带缓存）
   */
  async searchMediaFiles(
    searchTerm: string, 
    params: MediaQueryParams = {}
  ): Promise<MediaQueryResult> {
    const searchParams = { ...params, search: searchTerm };
    const key = CacheKeyStrategy.generateKey(DataType.MEDIA_FILES, searchParams);
    const loader = new MediaFilesLoader(searchParams);
    
    return dataService.getData(key, loader);
  }
  
  /**
   * 获取音频文件（带缓存）
   */
  async getAudioFiles(params: MediaQueryParams = {}): Promise<MediaQueryResult> {
    return this.getMediaFilesByType('audio', params);
  }
  
  /**
   * 获取图片文件（带缓存）
   */
  async getImageFiles(params: MediaQueryParams = {}): Promise<MediaQueryResult> {
    return this.getMediaFilesByType('image', params);
  }
  
  /**
   * 获取视频文件（带缓存）
   */
  async getVideoFiles(params: MediaQueryParams = {}): Promise<MediaQueryResult> {
    return this.getMediaFilesByType('video', params);
  }
  
  /**
   * 刷新媒体文件列表缓存
   */
  async refreshMediaFiles(params: MediaQueryParams = {}): Promise<MediaQueryResult> {
    const key = CacheKeyStrategy.generateKey(DataType.MEDIA_FILES, params);
    return dataService.refreshData(key);
  }
  
  /**
   * 刷新单个媒体文件缓存
   */
  async refreshMediaFile(id: string): Promise<MediaFileWithId | null> {
    const key = CacheKeyStrategy.generateKey(DataType.MEDIA_FILE, { id });
    return dataService.refreshData(key);
  }
  
  /**
   * 刷新媒体统计信息缓存
   */
  async refreshMediaStats(): Promise<MediaStats> {
    const key = CacheKeyStrategy.generateKey(DataType.MEDIA_STATS);
    return dataService.refreshData(key);
  }
  
  /**
   * 刷新按类型的媒体文件缓存
   */
  async refreshMediaFilesByType(
    type: 'image' | 'video' | 'audio' | 'other', 
    params: MediaQueryParams = {}
  ): Promise<MediaQueryResult> {
    const key = CacheKeyStrategy.generateKey('media_files_by_type' as DataType, { type, ...params });
    return dataService.refreshData(key);
  }
  
  /**
   * 刷新按分类的媒体文件缓存
   */
  async refreshMediaFilesByCategory(
    category: string, 
    params: MediaQueryParams = {}
  ): Promise<MediaQueryResult> {
    const key = CacheKeyStrategy.generateKey('media_files_by_category' as DataType, { category, ...params });
    return dataService.refreshData(key);
  }
  
  /**
   * 预加载媒体数据
   */
  async preloadMediaData(): Promise<void> {
    const keys = [
      DataType.MEDIA_FILES,
      DataType.MEDIA_STATS,
      'media_files_by_type' as DataType,
      'media_files_by_category' as DataType
    ];
    
    await dataService.preloadData(keys);
  }
  
  /**
   * 预加载特定类型的媒体数据
   */
  async preloadMediaDataByType(type: 'image' | 'video' | 'audio' | 'other'): Promise<void> {
    const key = CacheKeyStrategy.generateKey('media_files_by_type' as DataType, { type });
    const loader = new MediaFilesByTypeLoader(type);
    
    await dataService.getData(key, loader);
  }
  
  /**
   * 清空所有媒体缓存
   */
  clearMediaCache(): void {
    // 使用新的API清空媒体缓存
    import('./api').then(({ api }) => {
      api.entertainment.clearMediaCache();
    }).catch(error => {
      console.error('清空媒体缓存失败:', error);
    });
  }
}

// 导出单例实例
export const entertainmentDataService = EntertainmentDataService.getInstance();