import { store } from '../store'
import { scanAllMediaDirectories, scanMediaDirectory, fetchMediaCategories, fetchMediaTags } from '../store/slices/mediaFilesSlice'
import { setPreloadingState, updatePreloadProgress, setPreloadError, setPreloadComplete, resetPreloadState } from '../store/slices/mediaLoadingSlice'
import { ErrorHandlerUtils, ErrorType } from '../utils/errorHandler'

/**
 * 娱乐数据预加载服务
 * 负责在首页加载时预先获取所有娱乐模块所需的数据
 */
class EntertainmentPreloadService {
  private static instance: EntertainmentPreloadService
  private isPreloaded = false
  private preloadPromise: Promise<void> | null = null

  private constructor() {}

  static getInstance(): EntertainmentPreloadService {
    if (!EntertainmentPreloadService.instance) {
      EntertainmentPreloadService.instance = new EntertainmentPreloadService()
    }
    return EntertainmentPreloadService.instance
  }

  /**
   * 预加载所有娱乐模块数据
   * @returns Promise<void>
   */
  async preloadAllEntertainmentData(): Promise<void> {
    // 重置预加载状态
    store.dispatch(setPreloadingState(true))
    
    // 如果已经预加载或正在预加载，返回现有的Promise
    if (this.isPreloaded || this.preloadPromise) {
      return this.preloadPromise || Promise.resolve()
    }

    this.preloadPromise = this._performPreload()
    return this.preloadPromise
  }

  /**
   * 执行实际的数据预加载
   */
  private async _performPreload(): Promise<void> {
    // 更新预加载状态为开始
    store.dispatch(setPreloadingState(true))
    store.dispatch(updatePreloadProgress({ 
      progress: 5, 
      message: '开始预加载娱乐模块数据...' 
    }))
    
    try {
      console.log('开始预加载娱乐模块数据...')
      
      // 使用分阶段加载策略，优先加载关键数据
      // 第一阶段：加载所有媒体文件（最重要的数据）
      const criticalTasks = [
        // 预加载所有媒体文件
        ErrorHandlerUtils.executeWithRetry(
          () => store.dispatch(scanAllMediaDirectories()).unwrap(),
          { maxAttempts: 3, delayMs: 1000 },
          { operation: 'scanAllMediaDirectories' }
        )
      ]
      
      // 第二阶段：加载分类和标签数据
      const secondaryTasks = [
        // 预加载媒体类别
        ErrorHandlerUtils.executeWithRetry(
          () => store.dispatch(fetchMediaCategories()).unwrap(),
          { maxAttempts: 3, delayMs: 1000 },
          { operation: 'fetchMediaCategories' }
        ),
        
        // 预加载媒体标签
        ErrorHandlerUtils.executeWithRetry(
          () => store.dispatch(fetchMediaTags()).unwrap(),
          { maxAttempts: 3, delayMs: 1000 },
          { operation: 'fetchMediaTags' }
        )
      ]
      
      // 第三阶段：按类型加载媒体文件（可选优化）
      const optionalTasks = [
        // 预加载音乐文件
        ErrorHandlerUtils.safeExecute(
          () => store.dispatch(scanMediaDirectory('audio')).unwrap(),
          undefined,
          { operation: 'scanMediaDirectory', type: 'audio' }
        ),
        
        // 预加载图片文件
        ErrorHandlerUtils.safeExecute(
          () => store.dispatch(scanMediaDirectory('image')).unwrap(),
          undefined,
          { operation: 'scanMediaDirectory', type: 'image' }
        ),
        
        // 预加载视频文件
        ErrorHandlerUtils.safeExecute(
          () => store.dispatch(scanMediaDirectory('video')).unwrap(),
          undefined,
          { operation: 'scanMediaDirectory', type: 'video' }
        ),
        
        // 预加载音乐播放列表 - 使用新的API
        ErrorHandlerUtils.safeExecute(
          async () => {
            const { api } = await import('../services/api');
            return api.entertainment.getAudioFiles();
          },
          [],
          { operation: 'getAudioFiles', type: 'audio' }
        )
      ]

      // 分阶段执行加载任务
      console.log('第一阶段：加载关键媒体文件数据...')
      store.dispatch(updatePreloadProgress({ 
        progress: 20, 
        message: '第一阶段：加载关键媒体文件数据...' 
      }))
      const criticalResults = await Promise.allSettled(criticalTasks)
      
      console.log('第二阶段：加载分类和标签数据...')
      store.dispatch(updatePreloadProgress({ 
        progress: 50, 
        message: '第二阶段：加载分类和标签数据...' 
      }))
      const secondaryResults = await Promise.allSettled(secondaryTasks)
      
      console.log('第三阶段：加载可选优化数据...')
      store.dispatch(updatePreloadProgress({ 
        progress: 75, 
        message: '第三阶段：加载可选优化数据...' 
      }))
      const optionalResults = await Promise.allSettled(optionalTasks)
      
      // 合并所有结果
      const results = [...criticalResults, ...secondaryResults, ...optionalResults]
      
      // 分析结果并处理失败的任务
      const successfulTasks = results.filter(result => result.status === 'fulfilled')
      const failedTasks = results.filter(result => result.status === 'rejected')
      
      console.log(`预加载任务完成: ${successfulTasks.length}个成功, ${failedTasks.length}个失败`)
      
      // 记录失败的任务
      if (failedTasks.length > 0) {
        for (let i = 0; i < failedTasks.length; i++) {
          const task = failedTasks[i]
          console.error(`预加载任务失败:`, task.reason)
          
          // 使用错误处理工具处理错误
          await ErrorHandlerUtils.handleError(
            task.reason instanceof Error ? task.reason : new Error(String(task.reason)),
            { 
              taskIndex: i, 
              totalTasks: results.length,
              phase: 'preloading'
            }
          )
        }
      }
      
      // 验证关键数据是否加载成功
      await this.validateCriticalData()
      
      this.isPreloaded = true
      console.log('娱乐模块数据预加载完成')
      
      // 设置预加载完成状态
      store.dispatch(updatePreloadProgress({ 
        progress: 100, 
        message: '预加载完成！' 
      }))
      store.dispatch(setPreloadComplete())
      
      // 将预加载状态保存到localStorage
      localStorage.setItem('entertainment_preloaded', 'true')
      localStorage.setItem('entertainment_preload_time', new Date().toISOString())
      
    } catch (error) {
      console.error('娱乐模块数据预加载失败:', error)
      
      // 设置预加载错误状态
      store.dispatch(setPreloadError(`预加载失败: ${error instanceof Error ? error.message : '未知错误'}`))
      
      // 使用错误处理工具处理错误
      await ErrorHandlerUtils.handleError(
        error instanceof Error ? error : new Error(String(error)),
        { phase: 'preloading' }
      )
      
      throw error
    }
  }

  /**
   * 验证关键数据是否加载成功
   */
  private async validateCriticalData(): Promise<void> {
    try {
      // 检查媒体文件是否已加载到Redux store中
      const currentState = store.getState()
      const mediaFiles = currentState.mediaFiles.files
      
      if (mediaFiles.length === 0) {
        console.warn('预加载完成后，媒体文件列表仍为空，尝试重新加载')
        
        // 尝试从新的API加载媒体文件
        await ErrorHandlerUtils.executeWithRetry(
          async () => {
            const { api } = await import('../services/api');
            const result = await api.entertainment.getMediaFiles();
            const allFiles = result.files;
            
            // 验证数据不为空
            ErrorHandlerUtils.validateDataNotEmpty(
              allFiles,
              '从新API获取的媒体文件列表为空',
              { source: 'newAPI' }
            )
            
            store.dispatch({ type: 'mediaFiles/setFiles', payload: allFiles })
            console.log(`从新API加载了 ${allFiles.length} 个媒体文件`)
            
            return allFiles
          },
          { maxAttempts: 3, delayMs: 2000 },
          { operation: 'loadMediaFilesFromNewAPI' }
        )
      } else {
        console.log(`成功预加载了 ${mediaFiles.length} 个媒体文件`)
        
        // 验证是否有音频文件
        const audioFiles = mediaFiles.filter(file => file.type === 'audio')
        if (audioFiles.length === 0) {
          console.warn('预加载的媒体文件中没有音频文件')
          
          // 尝试单独加载音频文件 - 使用新的API
          await ErrorHandlerUtils.safeExecute(
            async () => {
              const { api } = await import('../services/api');
              const result = await api.entertainment.getAudioFiles();
              const audioFiles = result.files;
              if (audioFiles.length > 0) {
                console.log(`单独加载了 ${audioFiles.length} 个音频文件`)
              }
            },
            undefined,
            { operation: 'loadAudioFilesOnly' }
          )
        }
      }
      
      // 检查媒体类别是否加载成功
      const categories = currentState.mediaFiles.categories
      if (!categories || categories.length === 0) {
        console.warn('媒体类别未加载成功，尝试重新加载')
        
        await ErrorHandlerUtils.safeExecute(
          () => store.dispatch(fetchMediaCategories()).unwrap(),
          undefined,
          { operation: 'fetchCategoriesRetry' }
        )
      }
      
      // 检查媒体标签是否加载成功
      const tags = currentState.mediaFiles.tags
      if (!tags || tags.length === 0) {
        console.warn('媒体标签未加载成功，尝试重新加载')
        
        await ErrorHandlerUtils.safeExecute(
          () => store.dispatch(fetchMediaTags()).unwrap(),
          undefined,
          { operation: 'fetchTagsRetry' }
        )
      }
      
    } catch (error) {
      console.error('验证关键数据失败:', error)
      
      // 使用错误处理工具处理错误
      await ErrorHandlerUtils.handleError(
        error instanceof Error ? error : new Error(String(error)),
        { phase: 'validation' }
      )
      
      // 验证失败不应该阻止预加载完成，但应该记录
      console.warn('关键数据验证失败，但预加载仍标记为完成')
    }
  }

  /**
   * 检查是否已预加载
   * @returns boolean
   */
  hasPreloaded(): boolean {
    // 检查内存中的状态
    if (this.isPreloaded) {
      return true
    }
    
    // 检查localStorage中的状态
    const preloaded = localStorage.getItem('entertainment_preloaded') === 'true'
    if (preloaded) {
      const preloadTime = localStorage.getItem('entertainment_preload_time')
      if (preloadTime) {
        const preloadDate = new Date(preloadTime)
        // 如果预加载时间在30分钟内，认为仍然有效
        const now = new Date()
        const diffInMinutes = (now.getTime() - preloadDate.getTime()) / (1000 * 60)
        if (diffInMinutes < 30) {
          this.isPreloaded = true
          return true
        }
      }
    }
    
    return false
  }

  /**
   * 清除预加载状态
   */
  clearPreloadStatus(): void {
    this.isPreloaded = false
    this.preloadPromise = null
    localStorage.removeItem('entertainment_preloaded')
    localStorage.removeItem('entertainment_preload_time')
  }

  /**
   * 强制重新预加载
   */
  async forcePreload(): Promise<void> {
    this.clearPreloadStatus()
    return this.preloadAllEntertainmentData()
  }

  /**
   * 获取预加载状态信息
   */
  getPreloadInfo(): {
    isPreloaded: boolean
    preloadTime?: string
    isExpired: boolean
  } {
    const isPreloaded = this.hasPreloaded()
    const preloadTime = localStorage.getItem('entertainment_preload_time') || undefined
    
    let isExpired = false
    if (preloadTime) {
      const preloadDate = new Date(preloadTime)
      const now = new Date()
      const diffInMinutes = (now.getTime() - preloadDate.getTime()) / (1000 * 60)
      isExpired = diffInMinutes >= 30
    } else {
      isExpired = true
    }
    
    return {
      isPreloaded,
      preloadTime,
      isExpired
    }
  }
}

export default EntertainmentPreloadService.getInstance()