import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react'
import type { RootState } from '../index'
import { BlogPostsResponse, BlogPostResponse, BlogPostWithId, CreateBlogPostRequest } from '../../types'
import { Buffer } from 'buffer'
import { default as matter } from 'gray-matter'

// 确保Buffer在全局可用
if (typeof window !== 'undefined') {
  (window as any).Buffer = Buffer;
}

// 动态导入所有Markdown文件
const posts: Record<string, string> = {};

// 加载Markdown文件
try {
  const postModules = import.meta.glob('../../../_posts/*.md', { query: '?raw', import: 'default' }) as Record<string, () => Promise<string>>;
  
  Object.keys(postModules).forEach(async (key) => {
    try {
      const content = await postModules[key]();
      posts[key] = content as string;
    } catch (error) {
      console.error(`加载文章 ${key} 时出错:`, error);
    }
  });
} catch (error) {
  console.error('加载Markdown文章时出错:', error);
}

// 处理Markdown文件的frontmatter
const processMarkdownPost = (path: string, module: string): BlogPostWithId => {
  const slug = path.replace(/^.*\/_posts\//, '').replace(/\.md$/, '');
  const fileContents = module as string;
  
  // 使用 gray-matter 解析 MD 文件的 frontmatter
  const { data, content } = matter(fileContents);
  
  // 添加调试日志
  console.log(`Processing post: ${slug}`, { data, contentLength: content.length });
  
  return {
    _id: slug,
    slug,
    title: data.title || 'Untitled Post',
    date: data.date || new Date().toISOString(),
    coverImage: data.coverImage || '/assets/blog/placeholder.svg',
    author: {
      id: data.author?.name?.toLowerCase().replace(/\s+/g, '-') || 'anonymous',
      name: data.author?.name || 'Anonymous',
      picture: data.author?.picture || '/assets/blog/authors/default.jpg'
    },
    excerpt: data.excerpt || '',
    content,
    ogImage: { url: data.coverImage || '' },
    tags: data.tags || [],
    category: data.category || '未分类',
    viewCount: 0,
    likeCount: 0,
    commentCount: 0,
  };
};

// 获取所有本地Markdown文章
export const getAllLocalPosts = async (): Promise<BlogPostWithId[]> => {
  try {
    console.log('Starting to load local posts...');
    const postModules = import.meta.glob('../../../_posts/*.md', { query: '?raw', import: 'default' }) as Record<string, () => Promise<string>>;
    const posts: BlogPostWithId[] = [];
    
    console.log('Found post modules:', Object.keys(postModules));
    
    for (const path in postModules) {
      try {
        console.log(`Loading post from path: ${path}`);
        const content = await postModules[path]();
        const post = processMarkdownPost(path, content as string);
        posts.push(post);
        console.log(`Successfully loaded post: ${post.slug}`);
      } catch (error) {
        console.error(`加载文章 ${path} 时出错:`, error);
      }
    }
    
    console.log(`Loaded ${posts.length} posts in total`);
    
    // 按日期降序排序（最新的在前）
    return posts.sort((post1, post2) => {
      const date1 = new Date(post1.date || '');
      const date2 = new Date(post2.date || '');
      return date2.getTime() - date1.getTime();
    });
  } catch (error) {
    console.error('加载Markdown文章时出错:', error);
    return [];
  }
};

// 根据slug获取单个本地文章
export const getLocalPostBySlug = async (slug: string): Promise<BlogPostWithId | undefined> => {
  try {
    const allPosts = await getAllLocalPosts();
    return allPosts.find(post => post.slug === slug);
  } catch (error) {
    console.error('获取本地文章时出错:', error);
    return undefined;
  }
};

export const unifiedBlogApi = createApi({
  reducerPath: 'blogApi',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api/v1/blogs',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token
      if (token) {
        headers.set('authorization', `Bearer ${token}`)
      }
      return headers
    },
  }),
  tagTypes: ['BlogPost'],
  endpoints: (builder) => ({
    // 获取博客文章列表（结合本地Markdown和远程API）
    getBlogPosts: builder.query<BlogPostsResponse, { 
      page?: number; 
      limit?: number; 
      category?: string; 
      tag?: string;
      source?: 'local' | 'remote' | 'all'; // 数据源选择
    }>({
      queryFn: async ({ page = 1, limit = 10, category, tag, source = 'all' }) => {
        if (source === 'local' || source === 'all') {
          try {
            const localPosts = await getAllLocalPosts();
            
            let filteredPosts = [...localPosts];
            if (category && category !== '全部') {
              filteredPosts = filteredPosts.filter(post => post.category === category);
            }
            if (tag) {
              filteredPosts = filteredPosts.filter(post => 
                post.tags && post.tags.includes(tag)
              );
            }
            
            const total = filteredPosts.length;
            const totalPages = Math.ceil(total / limit);
            const startIndex = (page - 1) * limit;
            const paginatedPosts = filteredPosts.slice(startIndex, startIndex + limit);
            
            return {
              data: {
                success: true,
                data: paginatedPosts,
                pagination: {
                  page,
                  limit,
                  total,
                  totalPages
                }
              }
            };
          } catch (error) {
            console.error('获取本地文章时出错:', error);
            return {
              data: {
                success: false,
                data: [],
                pagination: { page, limit, total: 0, totalPages: 0 }
              }
            };
          }
        }
        
        return { data: { success: false, data: [], pagination: { page, limit, total: 0, totalPages: 0 } } };
      },
      providesTags: ['BlogPost']
    }),
    
    // 获取单个博客文章
    getBlogPost: builder.query<BlogPostResponse, { 
      id?: string; 
      slug?: string; 
      source?: 'local' | 'remote' | 'all';
    }>({
      queryFn: async ({ slug, source = 'all' }) => {
        if (source === 'local' || source === 'all') {
          if (slug) {
            try {
              const localPost = await getLocalPostBySlug(slug);
              if (localPost) {
                return {
                  data: {
                    success: true,
                    data: localPost
                  }
                };
              }
            } catch (error) {
              console.error('获取本地文章时出错:', error);
            }
          }
        }
        
        return {
          error: {
            status: 404,
            statusText: 'Post not found',
            data: { message: '文章未找到' }
          }
        };
      },
      providesTags: (_result, _error, { id, slug }) => 
        id ? [{ type: 'BlogPost', id }] : slug ? [{ type: 'BlogPost', id: slug }] : ['BlogPost'],
    }),
    
    // 创建博客文章
    createBlogPost: builder.mutation<BlogPostResponse, CreateBlogPostRequest>({
      query: (blogPost) => ({
        url: '',
        method: 'POST',
        body: blogPost,
      }),
      invalidatesTags: ['BlogPost'],
    }),
    
    // 更新博客文章
    updateBlogPost: builder.mutation<BlogPostResponse, { id: string; data: Partial<CreateBlogPostRequest> }>({
      query: ({ id, data }) => ({
        url: `/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'BlogPost', id }],
    }),
    
    // 删除博客文章
    deleteBlogPost: builder.mutation<void, string>({
      query: (id) => ({
        url: `/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['BlogPost'],
    }),
    
    // 搜索博客文章
    searchBlogPosts: builder.query<BlogPostsResponse, { 
      query: string; 
      page?: number; 
      limit?: number;
      source?: 'local' | 'remote' | 'all';
    }>({
      queryFn: async ({ query, page = 1, limit = 10, source = 'all' }) => {
        if (source === 'local' || source === 'all') {
          try {
            const localPosts = await getAllLocalPosts();
            
            const searchResults = localPosts.filter(post => 
              post.title.toLowerCase().includes(query.toLowerCase()) ||
              post.excerpt.toLowerCase().includes(query.toLowerCase()) ||
              post.content.toLowerCase().includes(query.toLowerCase())
            );
          
          const total = searchResults.length;
          const totalPages = Math.ceil(total / limit);
          const startIndex = (page - 1) * limit;
          const paginatedPosts = searchResults.slice(startIndex, startIndex + limit);
          
            return {
              data: {
                success: true,
                data: paginatedPosts,
                pagination: {
                  page,
                  limit,
                  total,
                  totalPages
                }
              }
            };
          } catch (error) {
            console.error('搜索本地文章时出错:', error);
            return {
              data: {
                success: false,
                data: [],
                pagination: { page, limit, total: 0, totalPages: 0 }
              }
            };
          }
        }
        
        return { data: { success: false, data: [], pagination: { page, limit, total: 0, totalPages: 0 } } };
      },
      providesTags: ['BlogPost']
    }),
    
    // 点赞博客文章
    likeBlogPost: builder.mutation<BlogPostResponse, string>({
      query: (id) => ({
        url: `/${id}/like`,
        method: 'POST',
      }),
      invalidatesTags: (_result, _error, id) => [{ type: 'BlogPost', id }],
    }),
  }),
})

export const {
  useGetBlogPostsQuery,
  useGetBlogPostQuery,
  useCreateBlogPostMutation,
  useUpdateBlogPostMutation,
  useDeleteBlogPostMutation,
  useSearchBlogPostsQuery,
  useLikeBlogPostMutation,
} = unifiedBlogApi