import { 
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Box,
  Typography,
  Slider,
  Button,
  List,
  ListItem,
  ListItemText,
  ListItemIcon,
  ListItemSecondaryAction,
  Chip,
  Avatar,
  styled,
  Tooltip,
  Menu,
  MenuItem as MuiMenuItem,
  Divider
} from '@mui/material'
import { 
  PlayArrow,
  Pause,
  SkipNext,
  SkipPrevious,
  VolumeUp,
  VolumeOff,
  Repeat,
  RepeatOne,
  Shuffle,
  Close,
  QueueMusic,
  Favorite,
  FavoriteBorder,
  MoreVert,
  MusicNote as MusicNoteIcon
} from '@mui/icons-material'
import { globalMusicService, MusicPlayMode } from '../../services/globalMusicService'
import { MediaFile } from '../../types/media'

// 获取播放模式文本
const getPlayModeText = (mode: MusicPlayMode) => {
  console.log('mode', mode)
  switch (mode) {
    case 'single':
      return '单曲循环'
    case 'shuffle':
      return '随机播放'
    case 'list':
    default:
      return '列表循环'
  }
}

