interface MusicPlayerDialogProps {
  open: boolean
  onClose: () => void
}

const MusicPlayerDialog: React.FC<MusicPlayerDialogProps> = ({ open, onClose }) => {
  const [playbackState, setPlaybackState] = useState(globalMusicService.getState())
  const [volume, setVolume] = useState(playbackState.volume)
  const [currentTime, setCurrentTime] = useState(0)
  const [duration, setDuration] = useState(0)
  const [playlist, setPlaylist] = useState(playbackState.playlist)
  const [showPlaylist, setShowPlaylist] = useState(false)
  const [menuAnchor, setMenuAnchor] = useState<null | HTMLElement>(null)
  const [forceUpdate, setForceUpdate] = useState(0) // 添加强制更新状态
  const [currentPlayMode, setCurrentPlayMode] = useState<MusicPlayMode>(playbackState.mode) // 本地播放模式状态
  const intervalRef = useRef<NodeJS.Timeout | null>(null)

  // 监听播放状态变化
  useEffect(() => {
    const unsubscribe = globalMusicService.subscribe((state) => {
      console.log('MusicPlayerDialog 收到状态更新:', state)
      console.log('当前播放模式:', state.mode)
      setPlaybackState(state)
      setVolume(state.volume)
      setPlaylist(state.playlist)
      // 强制更新组件
      setForceUpdate(prev => prev + 1)
    })

    return () => {
      unsubscribe()
    }
  }, [])

  // 更新播放进度
  useEffect(() => {
    if (playbackState.isPlaying) {
      intervalRef.current = setInterval(() => {
        setCurrentTime(prev => {
          const newTime = prev + 1
          if (newTime >= duration) {
            return 0
          }
          return newTime
        })
      }, 1000)
    } else {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
        intervalRef.current = null
      }
    }

    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current)
      }
    }
  }, [playbackState.isPlaying, duration])

  // 获取音频元数据
  useEffect(() => {
    if (playbackState.currentTrack) {
      const audio = new Audio()
      audio.src = playbackState.currentTrack.url
      
      const handleLoadedMetadata = () => {
        setDuration(audio.duration)
      }
      
      audio.addEventListener('loadedmetadata', handleLoadedMetadata)
      
      return () => {
        audio.removeEventListener('loadedmetadata', handleLoadedMetadata)
      }
    }
  }, [playbackState.currentTrack])

  // 播放/暂停
  const togglePlayPause = () => {
    globalMusicService.togglePlay()
  }

  // 播放下一首
  const playNext = async () => {
    await globalMusicService.playNext()
  }

  // 播放上一首
  const playPrevious = async () => {
    await globalMusicService.playPrevious()
  }

  // 切换静音
  const toggleMute = () => {
    globalMusicService.toggleMute()
  }

  // 调整音量
  const handleVolumeChange = (event: Event, newValue: number | number[]) => {
    const newVolume = Array.isArray(newValue) ? newValue[0] : newValue
    setVolume(newVolume)
    globalMusicService.setVolume(newVolume)
  }

  // 切换播放模式
  const togglePlayMode = () => {
    console.log('togglePlayMode 被调用')
    const currentMode = playbackState.mode
    console.log('当前播放模式:', currentMode)
    
    // 简化逻辑，直接切换到下一个模式
    let newMode: MusicPlayMode
    if (currentMode === 'list') {
      newMode = 'single'
    } else if (currentMode === 'single') {
      newMode = 'shuffle'
    } else {
      newMode = 'list'
    }
    
    console.log('切换到新播放模式:', newMode)
    globalMusicService.setPlayMode(newMode)
  }

  // 播放指定曲目
  const playTrack = async (track: MediaFile) => {
    await globalMusicService.playTrack(track)
  }

  // 格式化时间
  const formatTime = (seconds: number): string => {
    if (isNaN(seconds)) return '0:00'
    
    const mins = Math.floor(seconds / 60)
    const secs = Math.floor(seconds % 60)
    return `${mins}:${secs.toString().padStart(2, '0')}`
  }

  // 获取播放模式图标
  const getPlayModeIcon = () => {
    switch (playbackState.mode) {
      case 'single':
        return <RepeatOne />
      case 'shuffle':
        return <Shuffle />
      default:
        return <Repeat />
    }
  }

  // 处理菜单
  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setMenuAnchor(event.currentTarget)
  }

  const handleMenuClose = () => {
    setMenuAnchor(null)
  }

  // 切换收藏
  const toggleFavorite = () => {
    if (playbackState.currentTrack) {
      // 这里可以添加收藏逻辑
      console.log('切换收藏:', playbackState.currentTrack.name)
    }
    handleMenuClose()
  }

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: {
          bgcolor: 'transparent',
          boxShadow: 'none',
          overflow: 'hidden'
        }
      }}
    >
      <PlayerContainer>
        <PlayerHeader>
          <Typography variant="h6">音乐播放器</Typography>
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Tooltip title="播放列表">
              <IconButton color="inherit" onClick={() => setShowPlaylist(!showPlaylist)}>
                <QueueMusic />
              </IconButton>
            </Tooltip>
            <IconButton color="inherit" onClick={onClose}>
              <Close />
            </IconButton>
          </Box>
        </PlayerHeader>

        <PlayerContent>
          <AlbumArt>
            <MusicNoteIcon sx={{ fontSize: 80, opacity: 0.8 }} />
          </AlbumArt>

          <TrackInfo>
            <Typography variant="h6" noWrap>
              {playbackState.currentTrack?.name || '未选择曲目'}
            </Typography>
            <Typography variant="body2" sx={{ opacity: 0.8 }}>
              {playbackState.currentTrack?.artist || '未知艺术家'}
            </Typography>
          </TrackInfo>

          <ProgressBar>
            <Slider
              value={currentTime}
              max={duration || 100}
              onChange={(_, value) => setCurrentTime(Array.isArray(value) ? value[0] : value)}
              sx={{
                color: 'white',
                '& .MuiSlider-thumb': {
                  width: 16,
                  height: 16,
                },
              }}
            />
          </ProgressBar>

          <TimeDisplay>
            <span>{formatTime(currentTime)}</span>
            <span>{formatTime(duration)}</span>
          </TimeDisplay>

          <PlayerControls>
            <ControlButton onClick={playPrevious}>
              <SkipPrevious />
            </ControlButton>
            <ControlButton onClick={togglePlayPause} size="large">
              {playbackState.isPlaying ? <Pause /> : <PlayArrow />}
            </ControlButton>
            <ControlButton onClick={playNext}>
              <SkipNext />
            </ControlButton>
          </PlayerControls>

          <VolumeControl>
            <IconButton color="inherit" onClick={toggleMute}>
              {playbackState.isMuted || volume === 0 ? <VolumeOff /> : <VolumeUp />}
            </IconButton>
            <Slider
              value={volume}
              max={1}
              step={0.1}
              onChange={handleVolumeChange}
              sx={{
                color: 'white',
                '& .MuiSlider-thumb': {
                  width: 12,
                  height: 12,
                },
              }}
            />
          </VolumeControl>

          <Box sx={{ display: 'flex', gap: 1 }}>
            <ControlButton onClick={() => {
              console.log('播放模式按钮被直接点击')
              const currentMode = playbackState.mode
              const newMode = currentMode === 'list' ? 'single' : currentMode === 'single' ? 'shuffle' : 'list'
              console.log('直接设置播放模式:', newMode)
              
              // 立即更新本地状态
              setPlaybackState(prev => ({ ...prev, mode: newMode }))
              
              // 同时更新全局状态
              globalMusicService.setPlayMode(newMode)
              
              // 强制组件更新
              setForceUpdate(prev => prev + 1)
            }}>
              <Tooltip title={`播放模式: ${getPlayModeText(playbackState.mode)}`}>
                {getPlayModeIcon()}
              </Tooltip>
            </ControlButton>
            <ControlButton onClick={handleMenuOpen}>
              <MoreVert />
            </ControlButton>
          </Box>
        </PlayerContent>

        {showPlaylist && (
          <Box sx={{ p: 2, borderTop: '1px solid rgba(255,255,255,0.2)' }}>
            <Typography variant="subtitle2" sx={{ mb: 1 }}>
              播放列表 ({playlist.length})
            </Typography>
            <PlaylistContainer>
              <List dense>
                {playlist.map((track, index) => (
                  <ListItem
                    key={track.id}
                    button
                    selected={playbackState.currentTrack?.id === track.id}
                    onClick={() => playTrack(track)}
                    sx={{
                      borderRadius: 1,
                      mb: 0.5,
                      '&.Mui-selected': {
                        bgcolor: 'rgba(255,255,255,0.2)',
                      },
                    }}
                  >
                    <ListItemIcon>
                      <Avatar
                        variant="rounded"
                        sx={{ width: 40, height: 40, bgcolor: 'rgba(255,255,255,0.2)' }}
                      >
                        <MusicNoteIcon />
                      </Avatar>
                    </ListItemIcon>
                    <ListItemText
                      primary={track.name}
                      secondary={track.artist || '未知艺术家'}
                      primaryTypographyProps={{
                        noWrap: true,
                        variant: 'body2',
                      }}
                      secondaryTypographyProps={{
                        noWrap: true,
                        variant: 'caption',
                      }}
                    />
                    <ListItemSecondaryAction>
                      {playbackState.currentTrack?.id === track.id && playbackState.isPlaying && (
                        <Chip label="正在播放" size="small" color="primary" />
                      )}
                    </ListItemSecondaryAction>
                  </ListItem>
                ))}
              </List>
            </PlaylistContainer>
          </Box>
        )}
      </PlayerContainer>

      <Menu
        anchorEl={menuAnchor}
        open={Boolean(menuAnchor)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: {
            bgcolor: 'background.paper',
            minWidth: 150,
          }
        }}
      >
        <MuiMenuItem onClick={toggleFavorite}>
          <FavoriteBorder sx={{ mr: 1 }} />
          添加到收藏
        </MuiMenuItem>
        <MuiMenuItem onClick={handleMenuClose}>
          <QueueMusic sx={{ mr: 1 }} />
          查看详情
        </MuiMenuItem>
        <Divider />
        <MuiMenuItem onClick={handleMenuClose}>
          分享
        </MuiMenuItem>
      </Menu>
    </Dialog>
  )
}

export default MusicPlayerDialog