// 格式化时间
const formatTime = (seconds: number): string => {
  if (isNaN(seconds) || !isFinite(seconds)) return '0:00'
  
  const mins = Math.floor(seconds / 60)
  const secs = Math.floor(seconds % 60)
  return `${mins}:${secs.toString().padStart(2, '0')}`
}

// 获取播放模式文本
const getPlayModeText = (mode: MusicPlayMode) => {
  switch (mode) {
    case 'single':
      return '单曲循环'
    case 'shuffle':
      return '随机播放'
    case 'list':
    default:
      return '列表循环'
  }
}

/**
 * 全局音乐播放器控制组件
 */
const GlobalMusicPlayer: React.FC = () => {
  const [playbackState, setPlaybackState] = useState(globalMusicService.getState())
  const [showMiniPlayer, setShowMiniPlayer] = useState(false)
  const [showDialog, setShowDialog] = useState(false)
  const [menuAnchor, setMenuAnchor] = useState<null | HTMLElement>(null)

  // 监听播放状态变化
  useEffect(() => {
    const handleStateChange = (state: typeof playbackState) => {
      setPlaybackState(state)
      
      // 如果有当前播放曲目，显示迷你播放器
      setShowMiniPlayer(!!state.currentTrack)
    }

    globalMusicService.addStateChangeListener(handleStateChange)
    
    // 初始化状态
    handleStateChange(globalMusicService.getState())
    
    return () => {
      globalMusicService.removeStateChangeListener(handleStateChange)
    }
  }, [])

  // 处理播放/暂停
  const handleTogglePlay = () => {
    globalMusicService.togglePlay()
  }

  // 处理上一首
  const handlePrevious = async () => {
    console.log('GlobalMusicPlayer: 处理上一首按钮点击')
    await globalMusicService.playPrevious()
  }

  // 处理下一首
  const handleNext = async () => {
    console.log('GlobalMusicPlayer: 处理下一首按钮点击')
    console.log('当前播放状态:', playbackState)
    console.log('播放列表长度:', playbackState.playlist.length)
    console.log('当前索引:', playbackState.currentIndex)
    console.log('当前播放模式:', playbackState.mode)
    await globalMusicService.playNext()
  }

  // 处理菜单打开
  const handleMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setMenuAnchor(event.currentTarget)
  }

  // 处理菜单关闭
  const handleMenuClose = () => {
    setMenuAnchor(null)
  }

  // 处理打开对话框
  const handleOpenDialog = () => {
    setShowDialog(true)
    handleMenuClose()
  }

  // 处理关闭对话框
  const handleCloseDialog = () => {
    setShowDialog(false)
  }

  // 处理播放模式变化
  const handlePlayModeChange = (mode: MusicPlayMode) => {
    globalMusicService.setPlayMode(mode)
    handleMenuClose()
  }

  // 处理关闭迷你播放器
  const handleCloseMiniPlayer = () => {
    setShowMiniPlayer(false)
    globalMusicService.pause()
  }

  // 如果没有播放曲目，不显示任何内容
  if (!showMiniPlayer) {
    return null
  }

  return (
    <>
      <PlayerContainer>
        {/* 迷你播放器 */}
        <MiniPlayer>
          <TrackAvatar>
            {playbackState.currentTrack?.thumbnail ? (
              <img 
                src={playbackState.currentTrack.thumbnail} 
                alt={playbackState.currentTrack.name} 
                style={{ width: '100%', height: '100%', objectFit: 'cover' }} 
              />
            ) : (
              <MusicIcon />
            )}
          </TrackAvatar>
          
          <TrackInfo>
            <TrackTitle>
              {playbackState.currentTrack?.name || '未知曲目'}
            </TrackTitle>
            <TrackArtist>
              {playbackState.currentTrack?.artist || playbackState.currentTrack?.album || '未知艺术家'}
            </TrackArtist>
          </TrackInfo>
          
          <Box display="flex" alignItems="center">
            <Tooltip title="上一首">
              <ControlButton onClick={handlePrevious} size="small">
                <PreviousIcon fontSize="small" />
              </ControlButton>
            </Tooltip>
            
            <Tooltip title={playbackState.isPlaying ? '暂停' : '播放'}>
              <ControlButton onClick={handleTogglePlay}>
                {playbackState.isPlaying ? <PauseIcon /> : <PlayIcon />}
              </ControlButton>
            </Tooltip>
            
            <Tooltip title="下一首">
              <ControlButton onClick={handleNext} size="small">
                <NextIcon fontSize="small" />
              </ControlButton>
            </Tooltip>
            
            <Tooltip title="更多选项">
              <ControlButton onClick={handleMenuOpen} size="small">
                <SettingsIcon fontSize="small" />
              </ControlButton>
            </Tooltip>
            
            <Tooltip title="关闭播放器">
              <ControlButton onClick={handleCloseMiniPlayer} size="small">
                <CloseIcon fontSize="small" />
              </ControlButton>
            </Tooltip>
          </Box>
        </MiniPlayer>
      </PlayerContainer>

      {/* 菜单 */}
      <Menu
        anchorEl={menuAnchor}
        open={Boolean(menuAnchor)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: {
            minWidth: 200,
          }
        }}
      >
        <MenuItem onClick={handleOpenDialog}>
          <ListItemIcon>
            <MusicIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>打开播放器</ListItemText>
        </MenuItem>
        
        <Divider />
        
        <MenuItem onClick={() => handlePlayModeChange('list')}>
          <ListItemIcon>
            <RepeatIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>列表循环</ListItemText>
        </MenuItem>
        
        <MenuItem onClick={() => handlePlayModeChange('single')}>
          <ListItemIcon>
            <RepeatOneIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>单曲循环</ListItemText>
        </MenuItem>
        
        <MenuItem onClick={() => handlePlayModeChange('shuffle')}>
          <ListItemIcon>
            <ShuffleIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>随机播放</ListItemText>
        </MenuItem>
      </Menu>

      {/* 音乐播放器对话框 */}
      <MusicPlayerDialog
        open={showDialog}
        onClose={handleCloseDialog}
      />
    </>
  )
}

export default GlobalMusicPlayer