import React, { useState, useRef, useEffect } from 'react'
import { useLocation, useNavigate } from 'react-router-dom'
import { useSelector } from 'react-redux'
import { RootState } from '../../store'
import MediaNavigationService from '../../services/mediaNavigationService'
import {
  Box,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  IconButton,
  Typography,
  Button,
  Chip,
  Slider,
  CircularProgress,
  Fade,
  Backdrop
} from '@mui/material'
import { styled } from '@mui/material/styles'
import {
  Close as CloseIcon,
  PlayArrow as PlayArrowIcon,
  Pause as PauseIcon,
  VolumeUp as VolumeUpIcon,
  VolumeOff as VolumeOffIcon,
  Fullscreen as FullscreenIcon,
  NavigateBefore as NavigateBeforeIcon,
  NavigateNext as NavigateNextIcon,
  ZoomIn as ZoomInIcon,
  ZoomOut as ZoomOutIcon,
  RotateLeft as RotateLeftIcon,
  RotateRight as RotateRightIcon,
  MusicNote as MusicNoteIcon
} from '@mui/icons-material'
import { MediaFile } from '../../services/mediaFileService'
import globalMusicService from '../../services/globalMusicService'

const PreviewContainer = styled(Box)(({ theme }) => ({
  position: 'relative',
  width: '100%',
  display: 'flex',
  flexDirection: 'column',
  alignItems: 'center',
  backgroundColor: 'black',
  borderRadius: theme.spacing(1),
  overflow: 'hidden',
}))

const MediaPreview = styled(Box, {
  shouldForwardProp: (prop) => prop !== 'mediaType'
})<{ mediaType: 'image' | 'video' | 'audio' }>(({ theme, mediaType }) => ({
  width: '100%',
  maxHeight: mediaType === 'video' ? '500px' : mediaType === 'audio' ? '300px' : '70vh',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  position: 'relative',
  overflow: 'hidden',
  '& img': {
    maxWidth: '100%',
    maxHeight: '100%',
    objectFit: 'contain',
    transition: 'transform 0.3s ease',
  },
  '& video': {
    width: '100%',
    maxHeight: '500px',
    display: 'block',
  },
}))

const VideoControls = styled(Box)(({ theme }) => ({
  position: 'absolute',
  bottom: 0,
  left: 0,
  width: '100%',
  backgroundColor: 'rgba(0, 0, 0, 0.7)',
  padding: theme.spacing(1),
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(1),
  color: 'white',
}))

const ImageControls = styled(Box)(({ theme }) => ({
  position: 'absolute',
  top: theme.spacing(1),
  right: theme.spacing(1),
  display: 'flex',
  flexDirection: 'column',
  gap: theme.spacing(1),
  backgroundColor: 'rgba(0, 0, 0, 0.5)',
  padding: theme.spacing(0.5),
  borderRadius: theme.spacing(1),
}))

const AudioControls = styled(Box)(({ theme }) => ({
  position: 'absolute',
  top: 0,
  left: 0,
  width: '100%',
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'center',
  alignItems: 'center',
  backgroundColor: 'rgba(0, 0, 0, 0.8)',
  color: 'white',
  gap: theme.spacing(2),
}))

const NavigationControls = styled(Box)(({ theme }) => ({
  position: 'absolute',
  top: '50%',
  transform: 'translateY(-50%)',
  width: '100%',
  display: 'flex',
  justifyContent: 'space-between',
  padding: theme.spacing(1),
  pointerEvents: 'none',
  '& button': {
    pointerEvents: 'all',
  },
}))

interface MediaPreviewDialogProps {
  open: boolean
  onClose: () => void
  media: MediaFile | null
  mediaList?: MediaFile[]
  currentIndex?: number
  onIndexChange?: (index: number) => void
  formatFileSize: (bytes: number) => string
  formatDate: (date: Date | number | string) => string
}

const MediaPreviewDialog: React.FC<MediaPreviewDialogProps> = ({
  open,
  onClose,
  media,
  mediaList = [],
  currentIndex = 0,
  onIndexChange,
  formatFileSize,
  formatDate
}) => {
  const location = useLocation()
  const navigate = useNavigate()
  const { files } = useSelector((state: RootState) => state.mediaFiles)
  
  // 状态管理
  const [isPlaying, setIsPlaying] = useState(false)
  const [isMuted, setIsMuted] = useState(false)
  const [currentTime, setCurrentTime] = useState(0)
  const [duration, setDuration] = useState(0)
  const [videoError, setVideoError] = useState<string | null>(null)
  const [imageZoom, setImageZoom] = useState(1)
  const [imageRotation, setImageRotation] = useState(0)
  const [localMedia, setLocalMedia] = useState<MediaFile | null>(media)
  const [localCurrentIndex, setLocalCurrentIndex] = useState(currentIndex)
  const [audioInitialized, setAudioInitialized] = useState(false)
  
  const videoRef = useRef<HTMLVideoElement>(null)
  
  // 处理URL参数中的文件ID
  useEffect(() => {
    if (!media && open) {
      // 如果没有传入媒体文件，尝试从URL参数中获取文件ID
      const fileId = MediaNavigationService.getInstance().extractFileIdFromUrl(location.pathname + location.search)
      
      if (fileId) {
        // 从Redux状态中查找对应的媒体文件
        const foundMedia = files.find(file => file.id === fileId)
        if (foundMedia) {
          setLocalMedia(foundMedia)
          
          // 查找在媒体列表中的索引
          const index = mediaList.findIndex(item => item.id === fileId)
          if (index !== -1) {
            setLocalCurrentIndex(index)
          }
        }
      } else {
        // 如果URL中没有文件ID，尝试从导航服务中获取当前媒体文件
        const currentMedia = MediaNavigationService.getInstance().getCurrentMediaFile()
        if (currentMedia) {
          setLocalMedia(currentMedia)
          
          // 查找在媒体列表中的索引
          const index = mediaList.findIndex(item => item.id === currentMedia.id)
          if (index !== -1) {
            setLocalCurrentIndex(index)
          }
        }
      }
    } else if (media) {
      setLocalMedia(media)
      setLocalCurrentIndex(currentIndex)
    }
  }, [media, open, location, files, mediaList, currentIndex])
  
  // 当媒体文件改变时，重置状态
  useEffect(() => {
    if (localMedia) {
      setIsPlaying(false)
      setCurrentTime(0)
      setVideoError(null)
      setImageZoom(1)
      setImageRotation(0)
      setAudioInitialized(false)
    }
  }, [localMedia])

  // 处理音频文件播放
  useEffect(() => {
    if (localMedia && localMedia.type === 'audio' && open && !audioInitialized) {
      const initializeAudioPlayback = async () => {
        try {
          // 使用全局音乐服务播放音频
          await globalMusicService.playTrack(localMedia)
          setAudioInitialized(true)
          console.log('音频文件已通过全局音乐服务播放:', localMedia.name)
        } catch (error) {
          console.error('初始化音频播放失败:', error)
        }
      }
      
      initializeAudioPlayback()
    }
  }, [localMedia, open, audioInitialized])
  
  // 更新导航服务中的当前媒体文件
  useEffect(() => {
    if (localMedia) {
      MediaNavigationService.getInstance().setCurrentMediaFile(localMedia)
    }
  }, [localMedia])

  // 视频控制函数
  const togglePlayPause = () => {
    if (videoRef.current && localMedia) {
      if (isPlaying) {
        videoRef.current.pause()
      } else {
        videoRef.current.play()
      }
      setIsPlaying(!isPlaying)
    }
  }

  const toggleMute = () => {
    if (videoRef.current) {
      videoRef.current.muted = !isMuted
      setIsMuted(!isMuted)
    }
  }

  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime)
    }
  }

  const handleLoadedMetadata = () => {
    if (videoRef.current) {
      setDuration(videoRef.current.duration)
      setVideoError(null)
    }
  }

  const handleSliderChange = (_event: Event, newValue: number | number[]) => {
    const time = Array.isArray(newValue) ? newValue[0] : newValue
    if (videoRef.current) {
      videoRef.current.currentTime = time
      setCurrentTime(time)
    }
  }

  // 图片控制函数
  const handleZoomIn = () => {
    setImageZoom(prev => Math.min(prev + 0.2, 3))
  }

  const handleZoomOut = () => {
    setImageZoom(prev => Math.max(prev - 0.2, 0.5))
  }

  const handleRotateLeft = () => {
    setImageRotation(prev => prev - 90)
  }

  const handleRotateRight = () => {
    setImageRotation(prev => prev + 90)
  }

  // 导航函数
  const handlePrevious = () => {
    if (localCurrentIndex > 0) {
      const newIndex = localCurrentIndex - 1
      setLocalCurrentIndex(newIndex)
      if (onIndexChange) {
        onIndexChange(newIndex)
      }
    }
  }

  const handleNext = () => {
    if (localCurrentIndex < mediaList.length - 1) {
      const newIndex = localCurrentIndex + 1
      setLocalCurrentIndex(newIndex)
      if (onIndexChange) {
        onIndexChange(newIndex)
      }
    }
  }

  // 格式化时间
  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60)
    const secs = Math.floor(seconds % 60)
    return `${mins}:${secs.toString().padStart(2, '0')}`
  }

  // 处理键盘快捷键
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (!open) return
      
      switch (e.key) {
        case 'ArrowLeft':
          handlePrevious()
          break
        case 'ArrowRight':
          handleNext()
          break
        case ' ':
          if (media?.type === 'video') {
            e.preventDefault()
            togglePlayPause()
          } else if (media?.type === 'audio') {
            e.preventDefault()
            // 对于音频文件，可以在这里添加与全局音乐播放器的交互
            // 例如暂停/播放当前音频
          }
          break
        case 'Escape':
          onClose()
          break
      }
    }

    window.addEventListener('keydown', handleKeyDown)
    return () => window.removeEventListener('keydown', handleKeyDown)
  }, [open, media, currentIndex])

  if (!localMedia) return null

  return (
    <Dialog
      open={open}
      onClose={onClose}
      maxWidth="md"
      fullWidth
      PaperProps={{
        sx: {
          backgroundColor: 'black',
          overflow: 'hidden'
        }
      }}
    >
      <DialogTitle sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', p: 2, pb: 1 }}>
        <Typography variant="h6" component="div" color="white">
          {localMedia.name}
        </Typography>
        <IconButton onClick={onClose} sx={{ color: 'white' }}>
          <CloseIcon />
        </IconButton>
      </DialogTitle>

      <DialogContent sx={{ p: 0, minHeight: 400 }}>
        <PreviewContainer>
          {/* 导航控制 */}
          {mediaList.length > 1 && (
            <NavigationControls>
              <IconButton
                onClick={handlePrevious}
                disabled={currentIndex === 0}
                sx={{ color: 'white', backgroundColor: 'rgba(0,0,0,0.5)' }}
              >
                <NavigateBeforeIcon />
              </IconButton>
              <IconButton
                onClick={handleNext}
                disabled={currentIndex === mediaList.length - 1}
                sx={{ color: 'white', backgroundColor: 'rgba(0,0,0,0.5)' }}
              >
                <NavigateNextIcon />
              </IconButton>
            </NavigationControls>
          )}

          {/* 媒体预览 */}
          <MediaPreview mediaType={localMedia.type}>
            {localMedia.type === 'image' ? (
              <img
                src={localMedia.url}
                alt={localMedia.name}
                style={{
                  transform: `scale(${imageZoom}) rotate(${imageRotation}deg)`,
                  transition: 'transform 0.3s ease',
                }}
              />
            ) : localMedia.type === 'audio' ? (
              <AudioControls>
                <MusicNoteIcon sx={{ fontSize: 80, opacity: 0.8 }} />
                <Typography variant="h6" align="center">
                  {localMedia.name}
                </Typography>
                <Typography variant="body2" align="center" sx={{ opacity: 0.8 }}>
                  音频文件正在通过音乐播放器播放
                </Typography>
                <Typography variant="body2" align="center" sx={{ opacity: 0.6 }}>
                  请查看页面底部的音乐播放器控制面板
                </Typography>
              </AudioControls>
            ) : (
              <video
                ref={videoRef}
                src={localMedia.url}
                onTimeUpdate={handleTimeUpdate}
                onLoadedMetadata={handleLoadedMetadata}
                onEnded={() => setIsPlaying(false)}
                onError={(e) => {
                  console.error('视频播放错误:', e)
                  const errorCode = videoRef.current?.error?.code
                  let errorMessage = '未知错误'
                  
                  if (errorCode === 1) {
                    errorMessage = '视频加载被中止'
                  } else if (errorCode === 2) {
                    errorMessage = '视频加载时发生网络错误'
                  } else if (errorCode === 3) {
                    errorMessage = '视频解码错误'
                  } else if (errorCode === 4) {
                    errorMessage = `视频格式不受支持或文件损坏 (${localMedia.format})`
                  }
                  
                  setVideoError(errorMessage)
                }}
                onLoadedData={() => {
                  console.log('视频数据加载成功')
                  setVideoError(null)
                }}
                controls
                autoPlay={false}
                playsInline
                style={{
                  width: '100%',
                  maxHeight: '500px',
                  display: 'block',
                }}
              />
            )}
          </MediaPreview>

          {/* 视频控制 */}
          {localMedia.type === 'video' && (
            <>
              {videoError && (
                <Box sx={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'center',
                  alignItems: 'center',
                  backgroundColor: 'rgba(0,0,0,0.8)',
                  color: 'white',
                  zIndex: 10,
                  p: 2,
                  textAlign: 'center'
                }}>
                  <Typography variant="h6" gutterBottom>
                    视频播放失败
                  </Typography>
                  <Typography variant="body2" gutterBottom>
                    {videoError}
                  </Typography>
                  {localMedia.format.toLowerCase() === 'mov' && (
                    <Box>
                      <Typography variant="body2" sx={{ mt: 1 }}>
                        MOV格式在某些浏览器中可能不受支持
                      </Typography>
                      <Button 
                        variant="outlined" 
                        color="primary" 
                        sx={{ mt: 2 }}
                        onClick={() => {
                          // 尝试在新窗口中打开视频
                          window.open(localMedia.url, '_blank')
                        }}
                      >
                        在新窗口中打开
                      </Button>
                    </Box>
                  )}
                </Box>
              )}
              <VideoControls>
                <IconButton color="inherit" onClick={togglePlayPause}>
                  {isPlaying ? <PauseIcon /> : <PlayArrowIcon />}
                </IconButton>
                <Typography variant="body2" sx={{ minWidth: '100px' }}>
                  {formatTime(currentTime)} / {formatTime(duration)}
                </Typography>
                <Slider
                  size="small"
                  value={currentTime}
                  max={duration}
                  onChange={handleSliderChange}
                  sx={{ flexGrow: 1, mx: 1 }}
                />
                <IconButton color="inherit" onClick={toggleMute}>
                  {isMuted ? <VolumeOffIcon /> : <VolumeUpIcon />}
                </IconButton>
                <IconButton color="inherit">
                  <FullscreenIcon />
                </IconButton>
              </VideoControls>
            </>
          )}

          {/* 图片控制 */}
          {localMedia.type === 'image' && (
            <ImageControls>
              <IconButton onClick={handleZoomIn} sx={{ color: 'white' }} title="放大">
                <ZoomInIcon />
              </IconButton>
              <IconButton onClick={handleZoomOut} sx={{ color: 'white' }} title="缩小">
                <ZoomOutIcon />
              </IconButton>
              <IconButton onClick={handleRotateLeft} sx={{ color: 'white' }} title="左旋转">
                <RotateLeftIcon />
              </IconButton>
              <IconButton onClick={handleRotateRight} sx={{ color: 'white' }} title="右旋转">
                <RotateRightIcon />
              </IconButton>
            </ImageControls>
          )}
        </PreviewContainer>
      </DialogContent>

      <DialogActions sx={{ p: 2, pt: 1, flexDirection: 'column', alignItems: 'flex-start' }}>
        <Box sx={{ width: '100%' }}>
          <Typography variant="body1" paragraph>
            <strong>分类:</strong> {localMedia.category}
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>大小:</strong> {formatFileSize(localMedia.size)}
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>修改日期:</strong> {formatDate(localMedia.lastModified || new Date())}
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>标签:</strong>
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5, mb: 2 }}>
            {localMedia.tags.map((tag) => (
              <Chip key={tag} label={tag} size="small" />
            ))}
          </Box>
        </Box>
        <Button onClick={onClose}>关闭</Button>
      </DialogActions>
    </Dialog>
  )
}

export default MediaPreviewDialog