import React, { useState, useEffect } from 'react'
import { useNavigate, useParams, useLocation } from 'react-router-dom'
import { useDispatch, useSelector } from 'react-redux'
import { AppDispatch } from '../../../store'
import entertainmentPreloadService from '../../../services/entertainmentPreloadService'
import pageAutoPlayService from '../../../services/pageAutoPlayService'
import MediaNavigationService from '../../../services/mediaNavigationService'
import { 
  Box, 
  Container, 
  Typography, 
  Grid,
  Card, 
  CardMedia,
  CardContent,
  Chip,
  TextField,
  InputAdornment,
  FormControl,
  InputLabel,
  Select,
  MenuItem
} from '@mui/material'
import { styled } from '@mui/material/styles'
import SearchIcon from '@mui/icons-material/Search'
import PhotoLibrary from '@mui/icons-material/PhotoLibrary'
import MusicNoteIcon from '@mui/icons-material/MusicNote'
import { 
  setTypeFilter, 
  setCategoryFilter, 
  setTagFilter, 
  setSearchQuery,
  selectFilteredMediaFiles,
  selectMediaFilesCategories,
  selectMediaFilesTags,
  selectMediaFilesLoading,
  selectMediaFilesError,
  clearError
} from '../../../store/slices/mediaFilesSlice'
import { MediaFile } from '../../../services/mediaFileService'
import { 
  StateWrapper, 
  Notification,
  LoadingState
} from '../../../components/common/StateHandlers'
import EntertainmentNavigation from '../../../components/Entertainment/EntertainmentNavigation'
import MediaPreviewDialog from '../../../components/Entertainment/MediaPreviewDialog'

// 样式化的组件
const PhotoCard = styled(Card)(({ theme }) => ({
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  transition: 'transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out',
  cursor: 'pointer',
  '&:hover': {
    transform: 'translateY(-8px)',
    boxShadow: theme.shadows[8],
  },
}))

const PhotoMedia = styled(CardMedia)<{ fileType: 'image' | 'audio' }>(({ fileType }) => ({
  height: 200,
  position: 'relative',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  ...(fileType === 'image' && {
    objectFit: 'cover',
  }),
  ...(fileType === 'audio' && {
    background: 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)',
    '& img': {
      display: 'none'
    }
  })
}))

const FilterSection = styled(Box)(({ theme }) => ({
  backgroundColor: theme.palette.grey[50],
  padding: theme.spacing(3),
  borderRadius: theme.spacing(2),
  marginBottom: theme.spacing(4),
}))

const PhotoWall: React.FC = () => {
  const navigate = useNavigate()
  const location = useLocation()
  const dispatch = useDispatch<AppDispatch>()
  const { category } = useParams<{ category?: string }>()
  
  // 检查并使用预加载的数据
  useEffect(() => {
    // 如果没有预加载数据，则触发预加载
    if (!entertainmentPreloadService.hasPreloaded()) {
      entertainmentPreloadService.preloadAllEntertainmentData()
        .then(() => {
          console.log('照片墙数据预加载完成')
        })
        .catch(error => {
          console.error('照片墙数据预加载失败:', error)
        })
    }
    
    // 通知页面自动播放服务页面类型变化
    pageAutoPlayService.onPageChanged('photo')
  }, [dispatch])
  
  // Redux状态
  const filteredFiles = useSelector(selectFilteredMediaFiles)
  const categories = useSelector(selectMediaFilesCategories)
  const tags = useSelector(selectMediaFilesTags)
  const loading = useSelector(selectMediaFilesLoading)
  const error = useSelector(selectMediaFilesError)
  
  // 本地状态
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState(category || 'all')
  const [selectedTag, setSelectedTag] = useState('all')
  const [selectedPhoto, setSelectedPhoto] = useState<MediaFile | null>(null)
  const [photoDialogOpen, setPhotoDialogOpen] = useState(false)
  const [notificationOpen, setNotificationOpen] = useState(false)
  const [currentPhotoIndex, setCurrentPhotoIndex] = useState(0)
  
  // 处理URL参数中的文件ID
  useEffect(() => {
    const fileId = MediaNavigationService.getInstance().extractFileIdFromUrl(location.pathname + location.search)
    
    if (fileId && filteredFiles.length > 0) {
      const foundPhoto = filteredFiles.find(file => file.id === fileId && (file.type === 'image' || file.type === 'audio'))
      if (foundPhoto) {
        setSelectedPhoto(foundPhoto)
        setPhotoDialogOpen(true)
        
        // 查找在照片列表中的索引
        const photoFiles = filteredFiles.filter(file => file.type === 'image' || file.type === 'audio')
        const index = photoFiles.findIndex(item => item.id === fileId)
        if (index !== -1) {
          setCurrentPhotoIndex(index)
        }
      }
    }
  }, [location, filteredFiles])

  // 过滤出图片和音频类型的文件
  const photoFiles = filteredFiles.filter(file => file.type === 'image' || file.type === 'audio')

  // 应用过滤器
  useEffect(() => {
    dispatch(setTypeFilter('image,audio'))
    dispatch(setCategoryFilter(selectedCategory))
    dispatch(setTagFilter(selectedTag))
    dispatch(setSearchQuery(searchTerm))
  }, [dispatch, selectedCategory, selectedTag, searchTerm])

  // 处理URL参数变化
  useEffect(() => {
    if (category) {
      setSelectedCategory(category)
    }
  }, [category])

  // 处理照片点击
  const handlePhotoClick = (photo: MediaFile) => {
    const index = photoFiles.findIndex(p => p.id === photo.id)
    setCurrentPhotoIndex(index)
    setSelectedPhoto(photo)
    setPhotoDialogOpen(true)
  }

  // 关闭照片对话框
  const handleClosePhotoDialog = () => {
    setPhotoDialogOpen(false)
    setSelectedPhoto(null)
  }

  // 照片索引变化处理
  const handlePhotoIndexChange = (index: number) => {
    setCurrentPhotoIndex(index)
    setSelectedPhoto(photoFiles[index])
  }

  // 处理分类变化
  const handleCategoryChange = (event: any) => {
    const newCategory = event.target.value
    setSelectedCategory(newCategory)
    
    // 更新URL
    if (newCategory === 'all') {
      navigate('/entertainment/PhotoWall')
    } else {
      navigate(`/entertainment/PhotoWall/${newCategory}`)
    }
  }

  // 处理标签变化
  const handleTagChange = (event: any) => {
    setSelectedTag(event.target.value)
  }

  // 处理搜索
  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(event.target.value)
  }

  // 关闭通知
  const handleCloseNotification = () => {
    setNotificationOpen(false)
    if (error) {
      dispatch(clearError())
    }
  }

  // 格式化文件大小
  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  // 格式化日期
  const formatDate = (date: Date | number | string): string => {
    let dateObj: Date;
    if (typeof date === 'number') {
      dateObj = new Date(date);
    } else if (typeof date === 'string') {
      dateObj = new Date(date);
    } else {
      dateObj = date;
    }
    
    // 检查日期是否有效
    if (isNaN(dateObj.getTime())) {
      return '无效日期';
    }
    
    return dateObj.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  }

  return (
    <Container maxWidth="lg">
      <EntertainmentNavigation
        title="照片墙"
        subtitle="记录生活中的美好瞬间，分享摄影作品和旅行见闻"
        showBackButton={true}
      >
        {/* 过滤器区域 */}
        <FilterSection>
          <Grid container spacing={3} alignItems="center">
              {/* 搜索框 */}
              <Grid size={{ xs: 12, md: 3 }}>
              <TextField
                fullWidth
                placeholder="搜索照片..."
                value={searchTerm}
                onChange={handleSearchChange}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon />
                    </InputAdornment>
                  ),
                }}
              />
            </Grid>

            {/* 分类过滤器 */}
              <Grid size={{ xs: 12, md: 3 }}>
              <FormControl fullWidth>
                <InputLabel id="category-filter-label">分类</InputLabel>
                <Select
                  labelId="category-filter-label"
                  value={selectedCategory}
                  label="分类"
                  onChange={handleCategoryChange}
                >
                  <MenuItem value="all">所有分类</MenuItem>
                  {categories.map((cat) => (
                    <MenuItem key={cat} value={cat}>
                      {cat}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            {/* 标签过滤器 */}
              <Grid size={{ xs: 12, md: 3 }}>
              <FormControl fullWidth>
                <InputLabel id="tag-filter-label">标签</InputLabel>
                <Select
                  labelId="tag-filter-label"
                  value={selectedTag}
                  label="标签"
                  onChange={handleTagChange}
                >
                  <MenuItem value="all">所有标签</MenuItem>
                  {tags.map((tag) => (
                    <MenuItem key={tag} value={tag}>
                      {tag}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </FilterSection>

        {/* 照片网格 */}
        <StateWrapper
          loading={false}
          error={error}
          empty={photoFiles.length === 0}
          emptyIcon={<PhotoLibrary />}
          emptyTitle="没有找到照片或音频"
          emptyDescription="尝试调整过滤器或上传一些照片或音频"
          emptyAction={{
            label: '返回休闲娱乐',
            onClick: () => navigate('/entertainment')
          }}
          errorTitle="加载照片时出错"
          retryAction={{
            label: '重试',
            onClick: () => window.location.reload()
          }}
        >
          <Grid container spacing={3}>
            {photoFiles.map((photo) => (
              <Grid size={{ xs: 12, sm: 6, md: 4, lg: 3 }} key={photo.id}>
                <PhotoCard onClick={() => handlePhotoClick(photo)}>
                  <PhotoMedia
                    fileType={photo.type}
                    image={photo.url}
                    title={photo.name}
                  >
                    {photo.type === 'audio' && (
                      <MusicNoteIcon sx={{ fontSize: 60, color: 'white' }} />
                    )}
                  </PhotoMedia>
                  <CardContent>
                    <Typography variant="h6" component="h3" noWrap gutterBottom>
                      {photo.name}
                    </Typography>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                      <Typography variant="body2" color="text.secondary">
                        {formatFileSize(photo.size)}
                      </Typography>
                      <Typography variant="body2" color="text.secondary">
                        {photo.type === 'image' ? '图片' : '音频'}
                      </Typography>
                    </Box>
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                      {photo.tags.map((tag: string) => (
                        <Chip key={tag} label={tag} size="small" variant="outlined" />
                      ))}
                    </Box>
                  </CardContent>
                </PhotoCard>
              </Grid>
            ))}
          </Grid>
        </StateWrapper>

        {/* 照片预览对话框 */}
        <MediaPreviewDialog
          open={photoDialogOpen}
          onClose={handleClosePhotoDialog}
          media={selectedPhoto}
          mediaList={photoFiles}
          currentIndex={currentPhotoIndex}
          onIndexChange={handlePhotoIndexChange}
          formatFileSize={formatFileSize}
          formatDate={formatDate}
        />

        {/* 错误通知 */}
        <Notification
          open={!!error || notificationOpen}
          message={error || '操作失败'}
          severity="error"
          onClose={handleCloseNotification}
        />
      </EntertainmentNavigation>
    </Container>
  )
}

export default PhotoWall