import { GoogleGenerativeAI, GenerativeModel, ChatSession } from '@google/generative-ai'

// 消息类型定义
export interface ChatMessage {
  id: string
  role: 'user' | 'assistant'
  content: string
  timestamp: number
}

// AI响应类型
export interface AIResponse {
  text: string
  error?: string
}

// AI配置选项
export interface AIConfig {
  apiKey: string
  modelName?: string
  temperature?: number
  topK?: number
  topP?: number
  maxOutputTokens?: number
}

// Google AI服务类
class GoogleAIService {
  private genAI: GoogleGenerativeAI | null = null
  private model: GenerativeModel | null = null
  private chatSession: ChatSession | null = null
  private config: AIConfig

  constructor(config: AIConfig) {
    this.config = {
      modelName: 'gemini-3-flash',
      ...config,
    }

    try {
      this.genAI = new GoogleGenerativeAI(this.config.apiKey)
      this.model = this.genAI.getGenerativeModel({
        model: this.config.modelName!,
      })
      this.chatSession = this.model.startChat()
    } catch (error) {
      console.error('Failed to initialize Google AI:', error)
      throw new Error('Failed to initialize Google AI service')
    }
  }

  /**
   * 发送消息并获取AI响应
   */
  async sendMessage(message: string): Promise<AIResponse> {
    try {
      if (!this.chatSession) {
        throw new Error('Chat session not initialized')
      }

      const result = await this.chatSession.sendMessage(message)
      const response = await result.response
      const text = response.text()

      return {
        text,
      }
    } catch (error) {
      console.error('Error sending message:', error)
      return {
        text: '',
        error: error instanceof Error ? error.message : 'Unknown error occurred',
      }
    }
  }

  /**
   * 重置聊天会话
   */
  resetChat(): void {
    try {
      if (this.model) {
        this.chatSession = this.model.startChat()
      }
    } catch (error) {
      console.error('Error resetting chat:', error)
    }
  }

  /**
   * 获取聊天历史
   */
  getChatHistory(): ChatMessage[] {
    if (!this.chatSession) {
      return []
    }

    const history = this.chatSession.getHistory()
    return history.map((msg, index) => ({
      id: `msg-${index}`,
      role: msg.role as 'user' | 'assistant',
      content: msg.parts.map((part) => part.text).join(''),
      timestamp: Date.now(),
    }))
  }
}

// 创建单例实例
let serviceInstance: GoogleAIService | null = null

/**
 * 获取Google AI服务实例
 */
export function getGoogleAIService(config?: AIConfig): GoogleAIService {
  if (!serviceInstance && config) {
    serviceInstance = new GoogleAIService(config)
  }
  
  if (!serviceInstance) {
    throw new Error('Google AI service not initialized. Please provide configuration.')
  }
  
  return serviceInstance
}

/**
 * 初始化Google AI服务
 */
export function initializeGoogleAI(config: AIConfig): GoogleAIService {
  serviceInstance = new GoogleAIService(config)
  return serviceInstance
}

