import React, { useState, useEffect } from 'react';
import {
  Box,
  Drawer,
  List,
  ListItem,
  ListItemButton,
  ListItemText,
  Typography,
  Divider,
  IconButton,
  useTheme,
  useMediaQuery,
  Fab,
  alpha,
} from '@mui/material';
import {
  Menu as MenuIcon,
  FormatListBulleted as FormatListBulletedIcon,
  Close as CloseIcon,
} from '@mui/icons-material';

interface TableOfContentsItem {
  id: string;
  title: string;
  level: number;
}

interface TableOfContentsProps {
  containerRef?: React.RefObject<HTMLElement>;
  isOpen?: boolean;
  setIsOpen?: (open: boolean) => void;
}

const TableOfContents: React.FC<TableOfContentsProps> = ({ containerRef, isOpen, setIsOpen }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [headings, setHeadings] = useState<TableOfContentsItem[]>([]);
  const [activeId, setActiveId] = useState<string>('');
  const [internalIsOpen, setInternalIsOpen] = useState(false);
  
  // 使用外部传入的 isOpen 或内部状态
  const isDrawerOpen = isMobile ? (isOpen !== undefined ? isOpen : internalIsOpen) : false;
  const setDrawerOpen = isMobile && setIsOpen ? setIsOpen : setInternalIsOpen;

  // 提取文章标题
  useEffect(() => {
    if (!containerRef?.current) return;

    const extractHeadings = () => {
      // 重置headings状态，避免累积
      const headingElements = containerRef.current?.querySelectorAll('h1, h2, h3, h4, h5, h6') || [];
      const items: TableOfContentsItem[] = [];

      headingElements.forEach((element) => {
        const id = element.id || `heading-${items.length}`;
        if (!element.id) {
          element.id = id; // 如果没有id，则设置一个
        }

        const title = element.textContent || '';
        const level = parseInt(element.tagName.substring(1), 10);

        items.push({
          id,
          title,
          level,
        });
      });

      return items;
    };

    // 初始提取
    setHeadings(extractHeadings());
    // 重置活动标题
    setActiveId('');

    // 监听内容变化
    let timeoutId: NodeJS.Timeout | null = null;
    const observer = new MutationObserver(() => {
      // 清除之前的超时，避免多次触发
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
      // 使用setTimeout确保在下一个事件循环中执行，避免频繁更新
      timeoutId = setTimeout(() => {
        setHeadings(extractHeadings());
      }, 100);
    });

    if (containerRef.current) {
      observer.observe(containerRef.current, {
        childList: true,
        subtree: true,
      });
    }

    return () => {
      observer.disconnect();
      // 清除超时
      if (timeoutId) {
        clearTimeout(timeoutId);
      }
    };
  }, [containerRef]);

  // 监听滚动，更新活动标题
  useEffect(() => {
    if (!containerRef?.current || headings.length === 0) return;

    const handleScroll = () => {
      const container = containerRef.current;
      if (!container) return;

      const scrollTop = container.scrollTop;
      const offset = 100; // 提前激活的偏移量

      // 从下往上查找第一个可见的标题
      for (let i = headings.length - 1; i >= 0; i--) {
        const element = document.getElementById(headings[i].id);
        if (element) {
          const elementTop = element.offsetTop;
          if (elementTop <= scrollTop + offset) {
            setActiveId(headings[i].id);
            break;
          }
        }
      }
    };

    const container = containerRef.current;
    container.addEventListener('scroll', handleScroll);
    handleScroll(); // 初始调用

    return () => {
      container.removeEventListener('scroll', handleScroll);
    };
  }, [containerRef, headings]);

  // 点击标题滚动到对应位置
  const handleHeadingClick = (id: string) => {
    const element = document.getElementById(id);
    if (element && containerRef?.current) {
      const container = containerRef.current;
      const elementTop = element.offsetTop;
      
      container.scrollTo({
        top: elementTop - 50, // 留出一些空间
        behavior: 'smooth',
      });

      // 在移动设备上点击后关闭目录
      if (isMobile) {
        setDrawerOpen(false);
      }
    }
  };

  // 获取标题缩进
  const getIndent = (level: number) => {
    return (level - 1) * 16; // 每级缩进16px
  };

  // 移动端目录抽屉
  if (isMobile) {
    return (
      <Drawer
        anchor="right"
        open={isDrawerOpen}
        onClose={() => setDrawerOpen(false)}
        PaperProps={{
          sx: {
            width: 380,
            borderTopLeftRadius: '36px',
            borderTopRightRadius: '36px',
            backgroundColor: theme.palette.mode === 'dark' ? 'rgba(28, 28, 28, 0.98)' : '#ffffff',
            borderLeft: `2px solid ${alpha(theme.palette.primary.main, 0.22)}`,
            boxShadow: theme.palette.mode === 'dark'
              ? '0 18px 64px rgba(0, 0, 0, 0.65)'
              : '0 18px 64px rgba(102, 126, 234, 0.28)',
          },
        }}
      >
        <Box sx={{ 
          width: '100%', 
          height: '100%', 
          display: 'flex', 
          flexDirection: 'column',
          backgroundColor: theme.palette.mode === 'dark' ? 'rgba(28, 28, 28, 0.98)' : '#ffffff',
        }}>
          <Box sx={{ 
            p: 5, 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'space-between',
            borderBottom: `2px solid ${alpha(theme.palette.primary.main, 0.22)}`,
          }}>
            <Typography 
              variant="h6" 
              sx={{ 
                fontWeight: 900,
                color: theme.palette.mode === 'dark' ? '#f0f0f0' : '#1a1a1a',
                fontSize: '1.45rem',
                letterSpacing: '0.5px',
                transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
              }}
            >
              目录
            </Typography>
            <IconButton 
              onClick={() => setDrawerOpen(false)}
              sx={{
                transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
                '&:hover': {
                  backgroundColor: alpha(theme.palette.primary.main, 0.2),
                  transform: 'rotate(90deg) scale(1.25)',
                },
                '&:active': {
                  transform: 'rotate(90deg) scale(0.9)',
                },
              }}
            >
              <CloseIcon />
            </IconButton>
          </Box>
          <Divider />
          <Box sx={{ flex: 1, overflow: 'auto', p: 3.5 }}>
            {headings.length > 0 ? (
              <List dense>
                {headings.map((heading) => (
                  <ListItem key={heading.id} disablePadding sx={{ mb: 1.75 }}>
                    <ListItemButton
                      selected={activeId === heading.id}
                      onClick={() => handleHeadingClick(heading.id)}
                      sx={{ 
                        pl: 2.75 + getIndent(heading.level) / 8,
                        borderRadius: '18px',
                        transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
                        backgroundColor: activeId === heading.id 
                          ? alpha(theme.palette.primary.main, 0.28) 
                          : 'transparent',
                        '&:hover': {
                          backgroundColor: alpha(theme.palette.primary.main, 0.2),
                          transform: 'translateX(14px)',
                        },
                      }}
                    >
                      <ListItemText
                        primary={heading.title}
                        primaryTypographyProps={{
                          variant: 'body2',
                          color: activeId === heading.id 
                            ? theme.palette.primary.main 
                            : (theme.palette.mode === 'dark' ? '#f0f0f0' : '#1a1a1a'),
                          fontWeight: activeId === heading.id ? 900 : 700,
                          fontSize: '1.075rem',
                          letterSpacing: '0.2px',
                          transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
                        }}
                      />
                    </ListItemButton>
                  </ListItem>
                ))}
              </List>
            ) : (
              <Box sx={{ p: 5.5, textAlign: 'center' }}>
                <Typography 
                  variant="body2" 
                  sx={{ 
                    color: theme.palette.mode === 'dark' ? '#c0c0c0' : '#707070',
                    fontSize: '1.025rem',
                    fontWeight: 600,
                    letterSpacing: '0.2px',
                  }}
                >
                  没有找到标题
                </Typography>
              </Box>
            )}
          </Box>
        </Box>
      </Drawer>
    );
  }

  // 桌面端目录
  return (
    <Box
      sx={{
        position: 'sticky',
        top: 20,
        maxHeight: 'calc(100vh - 40px)',
        overflowY: 'auto',
        width: 340,
        p: 4.5,
        borderRadius: '32px',
        backgroundColor: theme.palette.mode === 'dark' ? 'rgba(28, 28, 28, 0.98)' : '#ffffff',
        backdropFilter: 'blur(12px)',
        border: `2px solid ${alpha(theme.palette.primary.main, 0.2)}`,
        boxShadow: theme.palette.mode === 'dark' 
          ? '0 12px 48px rgba(0, 0, 0, 0.55)' 
          : '0 12px 48px rgba(102, 126, 234, 0.22)',
        transition: 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
        '&:hover': {
          boxShadow: theme.palette.mode === 'dark' 
            ? '0 16px 60px rgba(0, 0, 0, 0.65)' 
            : '0 16px 60px rgba(102, 126, 234, 0.28)',
        },
        '&::-webkit-scrollbar': {
          width: '10px',
        },
        '&::-webkit-scrollbar-track': {
          background: 'transparent',
        },
        '&::-webkit-scrollbar-thumb': {
          background: alpha(theme.palette.primary.main, 0.5),
          borderRadius: '7px',
          '&:hover': {
            background: alpha(theme.palette.primary.main, 0.7),
          },
        },
      }}
    >
      <Typography 
        variant="h6" 
        gutterBottom
        sx={{ 
          fontWeight: 900,
          color: theme.palette.mode === 'dark' ? '#f0f0f0' : '#1a1a1a',
          mb: 4,
          fontSize: '1.4rem',
          letterSpacing: '0.5px',
          transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
        }}
      >
        目录
      </Typography>
      <Divider sx={{ mb: 4, borderColor: alpha(theme.palette.primary.main, 0.2) }} />
      {headings.length > 0 ? (
          <List dense>
            {headings.map((heading) => (
              <ListItem key={heading.id} disablePadding sx={{ mb: 1.75 }}>
                <ListItemButton
                  selected={activeId === heading.id}
                  onClick={() => handleHeadingClick(heading.id)}
                  sx={{ 
                    pl: 2.25 + getIndent(heading.level) / 8,
                    borderRadius: '18px',
                    transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
                    backgroundColor: activeId === heading.id 
                      ? alpha(theme.palette.primary.main, 0.28) 
                      : 'transparent',
                    '&:hover': {
                      backgroundColor: alpha(theme.palette.primary.main, 0.2),
                      transform: 'translateX(14px)',
                    },
                  }}
                >
                  <ListItemText
                    primary={heading.title}
                    primaryTypographyProps={{
                      variant: 'body2',
                      color: activeId === heading.id 
                        ? theme.palette.primary.main 
                        : (theme.palette.mode === 'dark' ? '#f0f0f0' : '#1a1a1a'),
                      fontWeight: activeId === heading.id ? 900 : 700,
                      fontSize: '1.075rem',
                      letterSpacing: '0.2px',
                      transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
                    }}
                  />
                </ListItemButton>
              </ListItem>
            ))}
          </List>
        ) : (
          <Box sx={{ p: 5.5, textAlign: 'center' }}>
            <Typography 
              variant="body2" 
              sx={{ 
                color: theme.palette.mode === 'dark' ? '#c0c0c0' : '#707070',
                fontSize: '1.025rem',
                fontWeight: 600,
                letterSpacing: '0.2px',
              }}
            >
              没有找到标题
            </Typography>
          </Box>
        )}
    </Box>
  );
};

export default TableOfContents;