import { configureStore } from '@reduxjs/toolkit'
import { setupListeners } from '@reduxjs/toolkit/query'
import authReducer from './slices/authSlice'
import themeReducer from './slices/themeSlice'
import mediaFilesReducer from './slices/mediaFilesSlice'
import mediaLoadingReducer from './slices/mediaLoadingSlice'
import { authApi } from './api/authApi'
import { unifiedBlogApi } from './api/unifiedBlogApi'
import { experienceApi } from './api/experienceApi'
import { tutorialApi } from './api/tutorialApi'
import { essayApi } from './api/essayApi'
import { notesApi } from './api/notesApi'
import { aiApi } from './api/aiApi'

export const store = configureStore({
  reducer: {
    auth: authReducer,
    theme: themeReducer,
    mediaFiles: mediaFilesReducer,
    mediaLoading: mediaLoadingReducer,
    [authApi.reducerPath]: authApi.reducer,
    [unifiedBlogApi.reducerPath]: unifiedBlogApi.reducer,
    [experienceApi.reducerPath]: experienceApi.reducer,
    [tutorialApi.reducerPath]: tutorialApi.reducer,
    [essayApi.reducerPath]: essayApi.reducer,
    [notesApi.reducerPath]: notesApi.reducer,
    [aiApi.reducerPath]: aiApi.reducer,
  },
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().concat(
      authApi.middleware,
      unifiedBlogApi.middleware,
      experienceApi.middleware,
      tutorialApi.middleware,
      essayApi.middleware,
      notesApi.middleware,
      aiApi.middleware
    ),
})

setupListeners(store.dispatch)

export type RootState = ReturnType<typeof store.getState>
export type AppDispatch = typeof store.dispatch