import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import {
  Container,
  Typography,
  Box,
  Paper,
  Grid,
  CircularProgress,
  Alert,
  Pagination,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  ToggleButton,
  ToggleButtonGroup,
  Fab,
  Zoom,
  Fade,
  Skeleton,
  Chip,
  useTheme,
  alpha,
} from '@mui/material';
import {
  Add,
  ViewList,
  ViewModule,
  KeyboardArrowUp,
} from '@mui/icons-material';
import { useGetBlogPostsQuery } from '../../store/api/unifiedBlogApi';
import ArticleCard from '../../components/blog/ArticleCard';
import ArticleCardSkeleton from '../../components/blog/ArticleCardSkeleton';
import { MarkdownStyleComponent } from '../../components/blog/Markdown';
import { ConditionalRender } from '../../components/auth/ProtectedRoute';
import { Permission } from '../../utils/permissions.tsx';

// 分类选项
const categories = ['全部', '前端开发', '后端开发', '移动开发', '数据库', '人工智能', '未分类'];
const sortOptions = ['最新发布', '最多浏览', '最多点赞'];

const Blog = () => {
  const [page, setPage] = useState(1);
  const [category, setCategory] = useState('全部');
  const [sortBy, setSortBy] = useState('最新发布');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [dataSource, setDataSource] = useState<'local' | 'remote' | 'all'>('local');
  const [showBackToTop, setShowBackToTop] = useState(false);
  
  const postsPerPage = 6;
  const theme = useTheme();
  const containerRef = useRef<HTMLDivElement>(null);

  // 使用统一的博客API获取数据
  const { data: blogData, error, isLoading } = useGetBlogPostsQuery({
    page,
    limit: postsPerPage,
    category: category === '全部' ? undefined : category,
    source: dataSource
  });

  const posts = blogData?.data || [];
  const pagination = blogData?.pagination;

  // 添加调试日志
  useEffect(() => {
    console.log('Blog组件 - 博客数据:', blogData);
    console.log('Blog组件 - 加载状态:', isLoading);
    console.log('Blog组件 - 文章列表:', posts);
    console.log('Blog组件 - 数据源:', dataSource);
    console.log('文章列表:', posts.map(post => ({
      slug: post.slug,
      title: post.title,
      coverImage: post.coverImage,
      imageSrc: post.coverImage && post.coverImage.startsWith('/') ? post.coverImage : `/${post.coverImage}`
    })));
  }, [blogData, isLoading, posts, dataSource]);

  // 监听滚动事件，显示/隐藏返回顶部按钮
  useEffect(() => {
    const handleScroll = () => {
      if (containerRef.current) {
        const scrollTop = containerRef.current.scrollTop;
        setShowBackToTop(scrollTop > 300);
      }
    };

    const container = containerRef.current;
    if (container) {
      container.addEventListener('scroll', handleScroll);
      return () => {
        container.removeEventListener('scroll', handleScroll);
      };
    }
  }, []);

  // 返回顶部函数
  const scrollToTop = () => {
    if (containerRef.current) {
      containerRef.current.scrollTo({
        top: 0,
        behavior: 'smooth'
      });
    }
  };

  const handlePageChange = (_event: React.ChangeEvent<unknown>, value: number) => {
    setPage(value);
  };

  const handleCategoryChange = (event: any) => {
    setCategory(event.target.value);
    setPage(1);
  };

  const handleSortChange = (event: any) => {
    setSortBy(event.target.value);
    setPage(1);
  };

  const handleViewModeChange = (
    _event: React.MouseEvent<HTMLElement>,
    nextViewMode: 'grid' | 'list' | null,
  ) => {
    if (nextViewMode !== null) {
      setViewMode(nextViewMode);
    }
  };

  const handleDataSourceChange = (
    _event: React.MouseEvent<HTMLElement>,
    nextDataSource: 'local' | 'remote' | 'all' | null,
  ) => {
    if (nextDataSource !== null) {
      setDataSource(nextDataSource);
      setPage(1);
    }
  };

  // 获取英雄文章（第一篇文章）
  const heroPost = posts.length > 0 ? posts[0] : null;
  const morePosts = posts.length > 1 ? posts.slice(1) : [];

  return (
    <>
      <MarkdownStyleComponent />
      <Container 
        maxWidth="lg" 
        sx={{ 
          py: 6,
          maxHeight: '100vh',
          overflowY: 'auto',
          scrollBehavior: 'smooth',
          '&::-webkit-scrollbar': {
            width: '8px',
          },
          '&::-webkit-scrollbar-track': {
            background: alpha(theme.palette.grey[200], 0.5),
            borderRadius: '4px',
          },
          '&::-webkit-scrollbar-thumb': {
            background: alpha(theme.palette.grey[500], 0.5),
            borderRadius: '4px',
            '&:hover': {
              background: alpha(theme.palette.grey[500], 0.7),
            },
          },
        }}
        ref={containerRef}
      >
        <Box sx={{ mb: 6, textAlign: 'center' }}>
          <Typography 
            variant="h3" 
            component="h1" 
            gutterBottom
            sx={{
              fontSize: '3rem',
              fontWeight: 700,
              background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
              WebkitBackgroundClip: 'text',
              WebkitTextFillColor: 'transparent',
              backgroundClip: 'text',
              mb: 2,
            }}
          >
            知识博客
          </Typography>
          <Typography 
            variant="h6" 
            color="text.secondary"
            sx={{
              fontSize: '1.2rem',
              fontWeight: 400,
              color: theme.palette.mode === 'dark' ? '#b0b0b0' : '#666666',
            }}
          >
            分享技术知识，记录学习心得
          </Typography>
        </Box>

        {/* 数据源选择 */}
        <Paper 
          sx={{ 
            p: 3, 
            mb: 4,
            borderRadius: '12px',
            boxShadow: theme.palette.mode === 'dark' 
              ? '0 2px 8px rgba(0, 0, 0, 0.3)'
              : '0 2px 12px rgba(102, 126, 234, 0.08)',
            border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
          }}
        >
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 2 }}>
            <ToggleButtonGroup
              value={dataSource}
              exclusive
              onChange={handleDataSourceChange}
              aria-label="数据源"
              size="small"
              sx={{
                '& .MuiToggleButton-root': {
                  borderRadius: '8px',
                  px: 2,
                  py: 1,
                  fontSize: '0.9rem',
                  fontWeight: 500,
                  border: `1px solid ${alpha(theme.palette.primary.main, 0.3)}`,
                  color: theme.palette.mode === 'dark' ? '#e0e0e0' : '#667eea',
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    backgroundColor: theme.palette.mode === 'dark' 
                      ? 'rgba(255, 255, 255, 0.1)' 
                      : 'rgba(102, 126, 234, 0.1)',
                    transform: 'translateY(-1px)',
                  },
                  '&.Mui-selected': {
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    color: '#ffffff',
                    border: 'none',
                    fontWeight: 600,
                  },
                },
              }}
            >
              <ToggleButton value="local" aria-label="本地文章">
                本地文章
              </ToggleButton>
              <ToggleButton value="remote" aria-label="远程文章">
                远程文章
              </ToggleButton>
              <ToggleButton value="all" aria-label="所有文章">
                所有文章
              </ToggleButton>
            </ToggleButtonGroup>

            <ToggleButtonGroup
              value={viewMode}
              exclusive
              onChange={handleViewModeChange}
              aria-label="视图模式"
              size="small"
              sx={{
                '& .MuiToggleButton-root': {
                  borderRadius: '8px',
                  px: 1.5,
                  py: 1,
                  border: `1px solid ${alpha(theme.palette.primary.main, 0.3)}`,
                  color: theme.palette.mode === 'dark' ? '#e0e0e0' : '#667eea',
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    backgroundColor: theme.palette.mode === 'dark' 
                      ? 'rgba(255, 255, 255, 0.1)' 
                      : 'rgba(102, 126, 234, 0.1)',
                    transform: 'translateY(-1px)',
                  },
                  '&.Mui-selected': {
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    color: '#ffffff',
                    border: 'none',
                  },
                },
              }}
            >
              <ToggleButton value="grid" aria-label="网格视图">
                <ViewModule />
              </ToggleButton>
              <ToggleButton value="list" aria-label="列表视图">
                <ViewList />
              </ToggleButton>
            </ToggleButtonGroup>
          </Box>
        </Paper>

        {/* 分类筛选 */}
        <Box sx={{ mb: 4 }}>
          <Typography 
            variant="h6" 
            gutterBottom 
            sx={{ 
              mb: 2,
              fontSize: '1.1rem',
              fontWeight: 600,
              color: theme.palette.mode === 'dark' ? '#ffffff' : '#333333',
            }}
          >
            文章分类
          </Typography>
          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.5 }}>
            {categories.map((cat) => (
              <Chip
                key={cat}
                label={cat}
                onClick={() => handleCategoryChange({ target: { value: cat } })}
                clickable
                sx={{
                  px: 2,
                  py: 1,
                  borderRadius: '20px',
                  fontSize: '0.9rem',
                  fontWeight: 500,
                  backgroundColor: category === cat
                    ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
                    : theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.05)' : 'rgba(102, 126, 234, 0.08)',
                  color: category === cat
                    ? '#ffffff'
                    : theme.palette.mode === 'dark' ? '#e0e0e0' : '#667eea',
                  border: category === cat
                    ? 'none'
                    : `1px solid ${alpha(theme.palette.primary.main, 0.3)}`,
                  transition: 'all 0.3s ease',
                  '&:hover': {
                    transform: 'translateY(-2px)',
                    boxShadow: category === cat
                      ? '0 4px 12px rgba(102, 126, 234, 0.4)'
                      : '0 4px 12px rgba(102, 126, 234, 0.2)',
                    backgroundColor: category === cat
                      ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
                      : theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(102, 126, 234, 0.15)',
                  },
                }}
              />
            ))}
          </Box>
        </Box>

        {/* 筛选和排序 */}
        <Paper 
          sx={{ 
            p: 3, 
            mb: 4,
            borderRadius: '12px',
            boxShadow: theme.palette.mode === 'dark' 
              ? '0 2px 8px rgba(0, 0, 0, 0.3)'
              : '0 2px 12px rgba(102, 126, 234, 0.08)',
            border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
          }}
        >
          <Grid container spacing={2} alignItems="center">
            <Grid size={{ xs: 12, sm: 6, md: 3 }}>
              <FormControl fullWidth variant="outlined" size="small">
                <InputLabel sx={{ fontSize: '0.9rem' }}>排序方式</InputLabel>
                <Select
                  value={sortBy}
                  onChange={handleSortChange}
                  label="排序方式"
                  sx={{
                    borderRadius: '8px',
                    '& .MuiOutlinedInput-notchedOutline': {
                      borderColor: alpha(theme.palette.primary.main, 0.3),
                    },
                    '&:hover .MuiOutlinedInput-notchedOutline': {
                      borderColor: alpha(theme.palette.primary.main, 0.5),
                    },
                  }}
                >
                  {sortOptions.map((option) => (
                    <MenuItem key={option} value={option} sx={{ fontSize: '0.9rem' }}>
                      {option}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        </Paper>

        {isLoading ? (
          <>
            {/* 精选文章骨架屏 */}
            {viewMode === 'grid' && (
              <Box sx={{ mb: 6 }}>
                <Typography 
                  variant="h4" 
                  component="h2" 
                  gutterBottom 
                  sx={{ 
                    fontWeight: 700,
                    fontSize: '2rem',
                    color: theme.palette.mode === 'dark' ? '#ffffff' : '#333333',
                    mb: 3,
                  }}
                >
                  精选文章
                </Typography>
                <ArticleCardSkeleton featured={true} />
              </Box>
            )}

            {/* 更多文章骨架屏 */}
            <Box>
              {viewMode === 'grid' && (
                <Typography 
                  variant="h4" 
                  component="h2" 
                  gutterBottom 
                  sx={{ 
                    fontWeight: 700,
                    fontSize: '2rem',
                    color: theme.palette.mode === 'dark' ? '#ffffff' : '#333333',
                    mb: 3,
                  }}
                >
                  更多文章
                </Typography>
              )}
              
              <Grid container spacing={3}>
                {Array.from({ length: viewMode === 'grid' ? 4 : 3 }).map((_, index) => (
                  <Grid size={{ xs: 12, md: viewMode === 'grid' ? 6 : 12 }} key={`skeleton-${index}`}>
                    <ArticleCardSkeleton viewMode={viewMode} />
                  </Grid>
                ))}
              </Grid>
            </Box>
          </>
        ) : error ? (
          <Alert 
            severity="error" 
            sx={{ 
              mb: 3,
              borderRadius: '12px',
            }}
          >
            加载博客文章时出错: {JSON.stringify(error)}
          </Alert>
        ) : (
          <>
            {/* 精选文章 */}
            {heroPost && viewMode === 'grid' && (
              <Fade in timeout={500}>
                <Box sx={{ mb: 6 }}>
                  <Typography 
                    variant="h4" 
                    component="h2" 
                    gutterBottom 
                    sx={{ 
                      fontWeight: 700,
                      fontSize: '2rem',
                      color: theme.palette.mode === 'dark' ? '#ffffff' : '#333333',
                      mb: 3,
                    }}
                  >
                    精选文章
                  </Typography>
                  <ArticleCard post={heroPost} featured={true} />
                </Box>
              </Fade>
            )}

            {/* 更多文章 */}
            {morePosts.length > 0 && (
              <Fade in timeout={600}>
                <Box>
                  {viewMode === 'grid' && (
                    <Typography 
                      variant="h4" 
                      component="h2" 
                      gutterBottom 
                      sx={{ 
                        fontWeight: 700,
                        fontSize: '2rem',
                        color: theme.palette.mode === 'dark' ? '#ffffff' : '#333333',
                        mb: 3,
                      }}
                    >
                      更多文章
                    </Typography>
                  )}
                  
                  <Grid container spacing={3}>
                    {(viewMode === 'grid' ? morePosts : posts).map((post, index) => (
                      <Grid size={{ xs: 12, md: viewMode === 'grid' ? 6 : 12 }} key={post.slug}>
                        <Fade in timeout={700 + index * 100}>
                          <Box>
                            <ArticleCard post={post} featured={false} />
                          </Box>
                        </Fade>
                      </Grid>
                    ))}
                  </Grid>
                </Box>
              </Fade>
            )}

            {/* 分页 */}
            {pagination && pagination.totalPages > 1 && (
              <Fade in timeout={800}>
                <Box sx={{ display: 'flex', justifyContent: 'center', mt: 6 }}>
                  <Pagination
                    count={pagination.totalPages}
                    page={page}
                    onChange={handlePageChange}
                    color="primary"
                    size="large"
                    sx={{
                      '& .MuiPaginationItem-root': {
                        borderRadius: '8px',
                        fontWeight: 500,
                        fontSize: '0.95rem',
                      },
                      '& .MuiPaginationItem-page.Mui-selected': {
                        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                        color: '#ffffff',
                        fontWeight: 600,
                      },
                    }}
                  />
                </Box>
              </Fade>
            )}
          </>
        )}

        {/* 写文章按钮 */}
        <ConditionalRender requiredPermission={Permission.WRITE_BLOG}>
          <Zoom in={true}>
            <Fab
              color="primary"
              aria-label="写文章"
              component={Link}
              to="/blog/create"
              sx={{
                position: 'fixed',
                bottom: 16,
                right: 16,
                zIndex: 1000,
                background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                '&:hover': {
                  background: 'linear-gradient(135deg, #5a6fd6 0%, #6a4190 100%)',
                  transform: 'scale(1.05)',
                  boxShadow: '0 8px 20px rgba(102, 126, 234, 0.4)',
                },
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 12px rgba(102, 126, 234, 0.3)',
              }}
            >
              <Add />
            </Fab>
          </Zoom>
        </ConditionalRender>

        {/* 返回顶部按钮 */}
        <Zoom in={showBackToTop}>
          <Fab
            color="secondary"
            size="small"
            aria-label="返回顶部"
            onClick={scrollToTop}
            sx={{
              position: 'fixed',
              bottom: 80,
              right: 16,
              zIndex: 1000,
              background: theme.palette.mode === 'dark' 
                ? 'rgba(255, 255, 255, 0.1)' 
                : 'rgba(102, 126, 234, 0.1)',
              color: theme.palette.mode === 'dark' ? '#ffffff' : '#667eea',
              border: `1px solid ${alpha(theme.palette.primary.main, 0.3)}`,
              '&:hover': {
                background: theme.palette.mode === 'dark' 
                  ? 'rgba(255, 255, 255, 0.2)' 
                  : 'rgba(102, 126, 234, 0.2)',
                transform: 'translateY(-2px)',
                boxShadow: '0 4px 12px rgba(102, 126, 234, 0.2)',
              },
              transition: 'all 0.3s ease',
            }}
          >
            <KeyboardArrowUp />
          </Fab>
        </Zoom>
      </Container>
    </>
  );
};

export default Blog;