import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Box,
  Paper,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  Grid,
  CircularProgress,
  Alert,
  Divider,
  IconButton,
} from '@mui/material';
import {
  Save,
  Preview,
  ArrowBack,
  Add,
  Close,
} from '@mui/icons-material';
import { useParams, useNavigate } from 'react-router-dom';
import { MarkdownStyleComponent } from '../../components/blog/Markdown';
import Markdown from '../../components/blog/Markdown';
import { Permission } from '../../utils/permissions.tsx';
import { ProtectedRoute } from '../../components/auth/ProtectedRoute';

// 分类选项
const categories = ['前端开发', '后端开发', '移动开发', '数据库', '人工智能', '未分类'];

interface BlogFormData {
  title: string;
  content: string;
  excerpt: string;
  category: string;
  tags: string[];
  coverImage: string;
  isDraft: boolean;
}

const BlogEditor: React.FC = () => {
  const { slug } = useParams<{ slug?: string }>();
  const navigate = useNavigate();
  const [isEditing] = useState(!!slug);
  const [isPreview, setIsPreview] = useState(false);
  const [tagInput, setTagInput] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  
  const [formData, setFormData] = useState<BlogFormData>({
    title: '',
    content: '',
    excerpt: '',
    category: '未分类',
    tags: [],
    coverImage: '',
    isDraft: false,
  });

  // 如果是编辑模式，加载文章数据
  useEffect(() => {
    if (slug) {
      // 这里应该调用API获取文章数据
      // const { data: post } = useGetBlogPostQuery({ slug, source: 'local' });
      // 暂时使用模拟数据
      const mockPost = {
        title: '示例文章标题',
        content: '# 示例文章内容\n\n这是一篇示例文章的内容。',
        excerpt: '这是一篇示例文章的摘要。',
        category: '前端开发',
        tags: ['React', 'TypeScript'],
        coverImage: '',
      };
      
      setFormData({
        title: mockPost.title,
        content: mockPost.content,
        excerpt: mockPost.excerpt,
        category: mockPost.category,
        tags: mockPost.tags,
        coverImage: mockPost.coverImage,
        isDraft: false,
      });
    }
  }, [slug]);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    // 清除错误信息
    if (error) setError('');
  };

  const handleCategoryChange = (e: any) => {
    setFormData(prev => ({ ...prev, category: e.target.value }));
  };

  const handleAddTag = () => {
    if (tagInput.trim() && !formData.tags.includes(tagInput.trim())) {
      setFormData(prev => ({
        ...prev,
        tags: [...prev.tags, tagInput.trim()]
      }));
      setTagInput('');
    }
  };

  const handleRemoveTag = (tagToRemove: string) => {
    setFormData(prev => ({
      ...prev,
      tags: prev.tags.filter(tag => tag !== tagToRemove)
    }));
  };

  const handleTagInputKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddTag();
    }
  };

  const handleSave = async (isDraft: boolean = false) => {
    if (!formData.title.trim() || !formData.content.trim()) {
      setError('标题和内容不能为空');
      return;
    }

    setIsSaving(true);
    setError('');
    
    try {
      // 这里应该调用API保存文章
      // if (isEditing) {
      //   await updateBlogPost({ slug, ...formData, isDraft }).unwrap();
      // } else {
      //   await createBlogPost({ ...formData, isDraft }).unwrap();
      // }
      
      // 模拟API调用
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      setSuccess(isDraft ? '草稿保存成功' : '文章发布成功');
      
      // 2秒后跳转到博客列表
      setTimeout(() => {
        navigate('/blog');
      }, 2000);
    } catch (err) {
      setError(isDraft ? '保存草稿失败' : '发布文章失败');
      console.error('保存文章失败:', err);
    } finally {
      setIsSaving(false);
    }
  };

  const goBack = () => {
    navigate('/blog');
  };

  const togglePreview = () => {
    setIsPreview(!isPreview);
  };

  return (
    <ProtectedRoute requiredPermission={Permission.WRITE_BLOG}>
      <>
        <MarkdownStyleComponent />
        <Container maxWidth="lg" sx={{ py: 4 }}>
          <Box sx={{ mb: 4, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <Typography variant="h3" component="h1">
              {isEditing ? '编辑文章' : '写文章'}
            </Typography>
            <Box>
              <Button
                variant="outlined"
                startIcon={<ArrowBack />}
                onClick={goBack}
                sx={{ mr: 2 }}
              >
                返回
              </Button>
              <Button
                variant="outlined"
                startIcon={<Preview />}
                onClick={togglePreview}
                sx={{ mr: 2 }}
              >
                {isPreview ? '编辑' : '预览'}
              </Button>
            </Box>
          </Box>

          {error && (
            <Alert severity="error" sx={{ mb: 3 }}>
              {error}
            </Alert>
          )}

          {success && (
            <Alert severity="success" sx={{ mb: 3 }}>
              {success}
            </Alert>
          )}

          <Paper sx={{ p: { xs: 2, md: 4 } }}>
            {!isPreview ? (
              <Box component="form">
                <Grid container spacing={3}>
                  <Grid size={{ xs: 12 }}>
                    <TextField
                      fullWidth
                      label="文章标题"
                      name="title"
                      value={formData.title}
                      onChange={handleInputChange}
                      variant="outlined"
                      required
                    />
                  </Grid>
                  
                  <Grid size={{ xs: 12 }}>
                    <TextField
                      fullWidth
                      label="文章摘要"
                      name="excerpt"
                      value={formData.excerpt}
                      onChange={handleInputChange}
                      variant="outlined"
                      multiline
                      rows={2}
                      helperText="文章摘要将显示在文章列表中"
                    />
                  </Grid>
                  
                  <Grid size={{ xs: 12, sm: 6 }}>
                    <FormControl fullWidth variant="outlined">
                      <InputLabel>分类</InputLabel>
                      <Select
                        value={formData.category}
                        onChange={handleCategoryChange}
                        label="分类"
                      >
                        {categories.map((category) => (
                          <MenuItem key={category} value={category}>
                            {category}
                          </MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  </Grid>
                  
                  <Grid size={{ xs: 12, sm: 6 }}>
                    <TextField
                      fullWidth
                      label="封面图片URL"
                      name="coverImage"
                      value={formData.coverImage}
                      onChange={handleInputChange}
                      variant="outlined"
                      helperText="可选"
                    />
                  </Grid>
                  
                  <Grid size={{ xs: 12 }}>
                    <Box sx={{ mb: 2 }}>
                      <Typography variant="subtitle1" gutterBottom>
                        标签
                      </Typography>
                      <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 1 }}>
                        {formData.tags.map((tag) => (
                          <Chip
                            key={tag}
                            label={tag}
                            onDelete={() => handleRemoveTag(tag)}
                            deleteIcon={<Close />}
                            size="small"
                          />
                        ))}
                      </Box>
                      <Box sx={{ display: 'flex', gap: 1 }}>
                        <TextField
                          size="small"
                          placeholder="输入标签后按回车添加"
                          value={tagInput}
                          onChange={(e) => setTagInput(e.target.value)}
                          onKeyPress={handleTagInputKeyPress}
                        />
                        <IconButton onClick={handleAddTag} color="primary">
                          <Add />
                        </IconButton>
                      </Box>
                    </Box>
                  </Grid>
                  
                  <Grid size={{ xs: 12 }}>
                    <TextField
                      fullWidth
                      label="文章内容"
                      name="content"
                      value={formData.content}
                      onChange={handleInputChange}
                      variant="outlined"
                      multiline
                      rows={20}
                      required
                      helperText="支持Markdown格式"
                    />
                  </Grid>
                  
                  <Grid size={{ xs: 12 }}>
                    <Divider sx={{ my: 2 }} />
                    <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                      <Button
                        variant="outlined"
                        onClick={() => handleSave(true)}
                        disabled={isSaving}
                      >
                        {isSaving ? <CircularProgress size={20} sx={{ mr: 1 }} /> : null}
                        保存草稿
                      </Button>
                      <Button
                        variant="contained"
                        color="primary"
                        onClick={() => handleSave(false)}
                        disabled={isSaving}
                        startIcon={<Save />}
                      >
                        {isSaving ? <CircularProgress size={20} sx={{ mr: 1 }} /> : null}
                        发布文章
                      </Button>
                    </Box>
                  </Grid>
                </Grid>
              </Box>
            ) : (
              <Box>
                <Typography variant="h4" component="h2" gutterBottom>
                  {formData.title || '无标题'}
                </Typography>
                
                <Box sx={{ mb: 3 }}>
                  {formData.category && (
                    <Chip label={formData.category} size="small" color="primary" sx={{ mr: 1 }} />
                  )}
                  {formData.tags.map((tag) => (
                    <Chip key={tag} label={tag} size="small" sx={{ mr: 1 }} />
                  ))}
                </Box>
                
                {formData.excerpt && (
                  <Box sx={{ mb: 3 }}>
                    <Typography variant="h6" gutterBottom>
                      摘要
                    </Typography>
                    <Typography variant="body1">
                      {formData.excerpt}
                    </Typography>
                  </Box>
                )}
                
                <Box sx={{ mb: 3 }}>
                  <Typography variant="h6" gutterBottom>
                    内容
                  </Typography>
                  <Markdown content={formData.content} />
                </Box>
                
                <Divider sx={{ my: 2 }} />
                <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                  <Button
                    variant="outlined"
                    onClick={() => handleSave(true)}
                    disabled={isSaving}
                  >
                    {isSaving ? <CircularProgress size={20} sx={{ mr: 1 }} /> : null}
                    保存草稿
                  </Button>
                  <Button
                    variant="contained"
                    color="primary"
                    onClick={() => handleSave(false)}
                    disabled={isSaving}
                    startIcon={<Save />}
                  >
                    {isSaving ? <CircularProgress size={20} sx={{ mr: 1 }} /> : null}
                    发布文章
                  </Button>
                </Box>
              </Box>
            )}
          </Paper>
        </Container>
      </>
    </ProtectedRoute>
  );
};

export default BlogEditor;