import React, { useState } from 'react';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneDark, oneLight } from 'react-syntax-highlighter/dist/cjs/styles/prism';
import {
  Box,
  IconButton,
  Typography,
  useTheme,
  useMediaQuery,
  Tooltip,
  Paper,
  Chip,
  alpha
} from '@mui/material';
import {
  ContentCopy as CopyIcon,
  Check as CheckIcon
} from '@mui/icons-material';

// 声明react-syntax-highlighter模块类型
declare module 'react-syntax-highlighter' {
  interface PrismProps {
    language: string;
    style: any;
    customStyle?: React.CSSProperties;
    wrapLines?: boolean;
    wrapLongLines?: boolean;
    showLineNumbers?: boolean;
    lineProps?: (lineNumber: number) => React.HTMLProps<HTMLElement>;
    children: React.ReactNode;
  }
  export const Prism: React.FC<PrismProps>;
}

// 声明样式模块类型
declare module 'react-syntax-highlighter/dist/cjs/styles/prism' {
  const oneDark: any;
  const oneLight: any;
  export { oneDark, oneLight };
}

interface CodeBlockProps {
  language: string;
  children: string;
  isMobile: boolean;
}

const CodeBlock: React.FC<CodeBlockProps> = ({ language, children, isMobile }) => {
  const theme = useTheme();
  const prefersDarkMode = useMediaQuery('(prefers-color-scheme: dark)');
  const codeTheme = prefersDarkMode ? oneDark : oneLight;
  const [copied, setCopied] = React.useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(children);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy text: ', err);
    }
  };

  return (
    <Box sx={{ position: 'relative', mb: 3 }}>
      <Box
        sx={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          px: 3,
          py: 2,
          backgroundColor: prefersDarkMode ? 'rgba(33, 37, 43, 0.95)' : 'rgba(241, 243, 244, 0.98)',
          borderTopLeftRadius: '24px',
          borderTopRightRadius: '24px',
          border: `1.5px solid ${prefersDarkMode ? 'rgba(255, 255, 255, 0.18)' : 'rgba(0, 0, 0, 0.12)'}`,
          borderBottom: 'none',
          transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)',
          '&:hover': {
            backgroundColor: prefersDarkMode ? 'rgba(40, 44, 52, 0.98)' : 'rgba(232, 234, 237, 0.98)',
            borderColor: prefersDarkMode ? 'rgba(255, 255, 255, 0.24)' : 'rgba(0, 0, 0, 0.18)',
          },
        }}
      >
        <Typography 
          variant="caption" 
          sx={{ 
            color: prefersDarkMode ? '#abb2bf' : '#5f6368',
            fontWeight: 900,
            fontSize: '1.05rem',
            letterSpacing: 0.75,
            textTransform: 'uppercase',
            transition: 'all 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
          }}
        >
          {language}
        </Typography>
        <Tooltip title={copied ? "已复制!" : "复制代码"} placement="top">
          <IconButton
            size="small"
            onClick={handleCopy}
            sx={{
              color: prefersDarkMode ? '#abb2bf' : '#5f6368',
              borderRadius: '12px',
              transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)',
              '&:hover': {
                backgroundColor: alpha(prefersDarkMode ? '#ffffff' : '#000000', 0.16),
                transform: 'scale(1.18)',
                boxShadow: prefersDarkMode 
                  ? '0 4px 16px rgba(0, 0, 0, 0.35)' 
                  : '0 4px 16px rgba(102, 126, 234, 0.25)',
              },
              '&:active': {
                transform: 'scale(0.92)',
              },
            }}
          >
            {copied ? <CheckIcon fontSize="small" /> : <CopyIcon fontSize="small" />}
          </IconButton>
        </Tooltip>
      </Box>
      <SyntaxHighlighter
        style={codeTheme}
        language={language}
        PreTag="div"
        customStyle={{
          borderRadius: '0 0 24px 24px',
          fontSize: isMobile ? '0.925rem' : '1.05rem',
          margin: '0',
          maxHeight: isMobile ? '360px' : '580px',
          overflow: 'auto',
          backgroundColor: prefersDarkMode ? 'rgba(40, 44, 52, 0.98)' : 'rgba(246, 248, 250, 0.98)',
          border: `1.5px solid ${prefersDarkMode ? 'rgba(255, 255, 255, 0.18)' : 'rgba(0, 0, 0, 0.12)'}`,
          borderTop: 'none',
          boxShadow: prefersDarkMode 
            ? '0 8px 32px rgba(0, 0, 0, 0.6)' 
            : '0 8px 32px rgba(102, 126, 234, 0.2)',
          transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)',
        }}
        wrapLines={true}
        wrapLongLines={false}
        showLineNumbers={true}
        lineProps={(lineNumber: number) => ({
          style: {
            display: 'block',
            paddingLeft: '1em',
          },
        })}
      >
        {children}
      </SyntaxHighlighter>
    </Box>
  );
};

export default CodeBlock;