import { globalMusicService } from './globalMusicService'
import { api } from './api'
import { MediaFile } from '../types/media'
import { ErrorHandlerUtils, ErrorType } from '../utils/errorHandler'

/**
 * 页面音乐自动播放服务
 * 负责在不同页面自动播放预设的背景音乐
 */
class PageAutoPlayService {
  private static instance: PageAutoPlayService
  private isInitialized = false
  private autoPlayEnabled = true
  private currentBackgroundMusic: MediaFile | null = null
  private userInteractionDetected = false
  private audioContext: AudioContext | null = null
  private autoPlayAttempts = 0
  private maxAutoPlayAttempts = 3

  private constructor() {
    // 监听用户交互，以便启用自动播放
    this.setupUserInteractionListeners()
  }

  static getInstance(): PageAutoPlayService {
    if (!PageAutoPlayService.instance) {
      PageAutoPlayService.instance = new PageAutoPlayService()
    }
    return PageAutoPlayService.instance
  }

  /**
   * 初始化自动播放服务
   */
  async initialize(): Promise<void> {
    if (this.isInitialized) return

    try {
      // 创建音频上下文
      this.audioContext = new (window.AudioContext || (window as any).webkitAudioContext)()
      
      // 获取背景音乐列表
      await this.loadBackgroundMusic()
      
      this.isInitialized = true
      console.log('页面音乐自动播放服务初始化成功')
    } catch (error) {
      console.error('页面音乐自动播放服务初始化失败:', error)
      
      // 使用错误处理工具处理错误
      await ErrorHandlerUtils.handleError(
        error instanceof Error ? error : new Error(String(error)),
        { operation: 'initializePageAutoPlayService' }
      )
      
      // 初始化失败不应该阻止应用运行，但应该记录
      console.warn('页面音乐自动播放服务初始化失败，但应用仍可继续运行')
    }
  }

  /**
   * 设置用户交互监听器
   */
  private setupUserInteractionListeners(): void {
    const events = ['click', 'keydown', 'touchstart', 'mousemove']
    
    const handleUserInteraction = () => {
      if (!this.userInteractionDetected) {
        this.userInteractionDetected = true
        console.log('检测到用户交互，启用自动播放')
        
        // 尝试恢复音频上下文
        if (this.audioContext && this.audioContext.state === 'suspended') {
          this.audioContext.resume()
        }
        
        // 尝试自动播放背景音乐
        this.tryAutoPlayBackgroundMusic()
        
        // 移除事件监听器
        events.forEach(event => {
          document.removeEventListener(event, handleUserInteraction)
        })
      }
    }
    
    // 添加事件监听器
    events.forEach(event => {
      document.addEventListener(event, handleUserInteraction, { once: true })
    })
  }

  /**
   * 加载背景音乐
   */
  private async loadBackgroundMusic(): Promise<void> {
    try {
      // 使用带重试的机制获取音乐文件列表
      const musicFiles = await ErrorHandlerUtils.executeWithRetry(
        () => api.entertainment.getMediaFilesByType('audio'),
        { maxAttempts: 3, delayMs: 1000 },
        { operation: 'loadBackgroundMusic' }
      )
      
      // 验证音乐文件列表不为空
      ErrorHandlerUtils.validateDataNotEmpty(
        musicFiles,
        '没有找到音乐文件',
        { operation: 'loadBackgroundMusic' }
      )
      
      // 选择第一首音乐作为默认背景音乐
      this.currentBackgroundMusic = musicFiles[0]
      
      // 设置播放列表
      globalMusicService.setPlaylist(musicFiles)
      
      console.log(`加载背景音乐: ${this.currentBackgroundMusic.name}`)
    } catch (error) {
      console.error('加载背景音乐失败:', error)
      
      // 使用错误处理工具处理错误
      await ErrorHandlerUtils.handleError(
        error instanceof Error ? error : new Error(String(error)),
        { operation: 'loadBackgroundMusic' }
      )
      
      // 加载背景音乐失败不应该阻止应用运行，但应该记录
      console.warn('背景音乐加载失败，页面将没有背景音乐')
    }
  }

  /**
   * 尝试自动播放背景音乐
   */
  async tryAutoPlayBackgroundMusic(): Promise<void> {
    if (!this.autoPlayEnabled || !this.currentBackgroundMusic) {
      return
    }
    
    if (this.autoPlayAttempts >= this.maxAutoPlayAttempts) {
      console.warn('已达到最大自动播放尝试次数，停止尝试')
      return
    }
    
    this.autoPlayAttempts++
    
    try {
      // 检查浏览器是否支持自动播放
      const canAutoPlay = await this.checkAutoPlaySupport()
      
      if (canAutoPlay) {
        console.log('尝试自动播放背景音乐')
        
        // 使用带重试的机制播放音乐
        await ErrorHandlerUtils.executeWithRetry(
          () => globalMusicService.playTrack(this.currentBackgroundMusic!),
          { maxAttempts: 2, delayMs: 500 },
          { operation: 'autoPlayBackgroundMusic', trackName: this.currentBackgroundMusic.name }
        )
        
        globalMusicService.setVolume(0.3) // 设置较低的音量
        console.log('背景音乐自动播放成功')
      } else {
        console.log('浏览器不支持自动播放，等待用户交互')
      }
    } catch (error) {
      console.error(`自动播放背景音乐失败 (尝试 ${this.autoPlayAttempts}/${this.maxAutoPlayAttempts}):`, error)
      
      // 使用错误处理工具处理错误
      await ErrorHandlerUtils.handleError(
        error instanceof Error ? error : new Error(String(error)),
        { 
          operation: 'tryAutoPlayBackgroundMusic', 
          attempt: this.autoPlayAttempts,
          maxAttempts: this.maxAutoPlayAttempts,
          trackName: this.currentBackgroundMusic.name 
        }
      )
      
      // 如果失败，延迟后再次尝试
      if (this.autoPlayAttempts < this.maxAutoPlayAttempts) {
        setTimeout(() => {
          this.tryAutoPlayBackgroundMusic()
        }, 2000)
      }
    }
  }

  /**
   * 检查浏览器是否支持自动播放
   */
  async checkAutoPlaySupport(): Promise<boolean> {
    try {
      // 创建一个测试音频元素
      const testAudio = new Audio()
      testAudio.volume = 0
      testAudio.src = this.currentBackgroundMusic?.url || ''
      
      // 尝试播放
      const playPromise = testAudio.play()
      
      if (playPromise !== undefined) {
        await playPromise
        testAudio.pause()
        return true
      }
      
      return false
    } catch (error) {
      return false
    }
  }

  /**
   * 页面变化时调用，根据页面类型播放不同的音乐
   */
  async onPageChanged(pageType: string): Promise<void> {
    if (!this.isInitialized) {
      await this.initialize()
    }
    
    console.log(`页面变化: ${pageType}`)
    
    // 根据页面类型选择不同的背景音乐
    await this.selectBackgroundMusicByPage(pageType)
    
    // 尝试自动播放
    if (this.userInteractionDetected) {
      await this.tryAutoPlayBackgroundMusic()
    }
  }

  /**
   * 根据页面类型选择背景音乐
   */
  private async selectBackgroundMusicByPage(pageType: string): Promise<void> {
    try {
      // 使用带重试的机制获取音乐文件列表
      const musicFiles = await ErrorHandlerUtils.executeWithRetry(
        () => api.entertainment.getMediaFilesByType('audio'),
        { maxAttempts: 2, delayMs: 1000 },
        { operation: 'selectBackgroundMusicByPage', pageType }
      )
      
      // 验证音乐文件列表不为空
      if (musicFiles.length === 0) {
        console.warn('没有音乐文件可供选择背景音乐')
        return
      }
      
      // 根据页面类型选择音乐
      let selectedMusic: MediaFile | null = null
      
      switch (pageType) {
        case 'home':
          // 首页选择轻松的音乐
          selectedMusic = musicFiles.find(file => 
            file.tags.includes('轻松') || file.tags.includes('背景音乐')
          ) || musicFiles[0]
          break
          
        case 'entertainment':
          // 娱乐页面选择欢快的音乐
          selectedMusic = musicFiles.find(file => 
            file.tags.includes('欢快') || file.tags.includes('流行')
          ) || musicFiles[0]
          break
          
        case 'photo':
          // 照片墙页面选择舒缓的音乐
          selectedMusic = musicFiles.find(file => 
            file.tags.includes('舒缓') || file.tags.includes('经典')
          ) || musicFiles[0]
          break
          
        case 'music':
          // 音乐页面选择用户喜欢的音乐
          selectedMusic = musicFiles.find(file => 
            file.tags.includes('喜欢') || file.tags.includes('收藏')
          ) || musicFiles[0]
          break
          
        case 'media':
          // 媒体库页面选择中性音乐
          selectedMusic = musicFiles.find(file => 
            file.tags.includes('中性') || file.tags.includes('新歌')
          ) || musicFiles[0]
          break
          
        default:
          // 默认使用第一首音乐
          selectedMusic = musicFiles[0]
      }
      
      if (selectedMusic && selectedMusic.id !== this.currentBackgroundMusic?.id) {
        this.currentBackgroundMusic = selectedMusic
        console.log(`根据页面类型选择背景音乐: ${selectedMusic.name}`)
      }
    } catch (error) {
      console.error('根据页面类型选择背景音乐失败:', error)
      
      // 使用错误处理工具处理错误
      await ErrorHandlerUtils.handleError(
        error instanceof Error ? error : new Error(String(error)),
        { operation: 'selectBackgroundMusicByPage', pageType }
      )
      
      // 选择背景音乐失败不应该阻止应用运行，但应该记录
      console.warn('根据页面类型选择背景音乐失败，将使用默认背景音乐')
    }
  }

  /**
   * 启用/禁用自动播放
   */
  setAutoPlayEnabled(enabled: boolean): void {
    this.autoPlayEnabled = enabled
    console.log(`自动播放${enabled ? '已启用' : '已禁用'}`)
    
    // 如果禁用自动播放，停止当前播放
    if (!enabled && globalMusicService.getState().isPlaying) {
      globalMusicService.pause()
    }
  }

  /**
   * 获取当前背景音乐
   */
  getCurrentBackgroundMusic(): MediaFile | null {
    return this.currentBackgroundMusic
  }

  /**
   * 获取自动播放状态
   */
  getAutoPlayStatus(): {
    enabled: boolean
    initialized: boolean
    userInteractionDetected: boolean
    currentMusic: MediaFile | null
    autoPlayAttempts: number
  } {
    return {
      enabled: this.autoPlayEnabled,
      initialized: this.isInitialized,
      userInteractionDetected: this.userInteractionDetected,
      currentMusic: this.currentBackgroundMusic,
      autoPlayAttempts: this.autoPlayAttempts
    }
  }
}

// 导出单例实例
export default PageAutoPlayService.getInstance()