import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react'
import type { RootState } from '../index'

export interface Note {
  _id: string
  title: string
  content: string
  category: string
  tags: string[]
  progress: number // 0-100
  isCompleted: boolean
  isArchived: boolean
  createdAt: string
  updatedAt: string
}

export interface NotesResponse {
  success: boolean
  data: Note[]
  pagination: {
    page: number
    limit: number
    total: number
    totalPages: number
  }
}

export interface NoteResponse {
  success: boolean
  data: Note
}

export interface CreateNoteRequest {
  title: string
  content: string
  category: string
  tags: string[]
  progress?: number
  isCompleted?: boolean
  isArchived?: boolean
}

export const notesApi = createApi({
  reducerPath: 'notesApi',
  baseQuery: fetchBaseQuery({
    baseUrl: '/api/v1/notes',
    prepareHeaders: (headers, { getState }) => {
      const token = (getState() as RootState).auth.token
      if (token) {
        headers.set('authorization', `Bearer ${token}`)
      }
      return headers
    },
  }),
  tagTypes: ['Note'],
  endpoints: (builder) => ({
    getNotes: builder.query<NotesResponse, { page?: number; limit?: number; category?: string; tag?: string; completed?: boolean; archived?: boolean }>({
      query: ({ page = 1, limit = 20, category, tag, completed, archived }) => {
        let queryParams = `?page=${page}&limit=${limit}`
        if (category) queryParams += `&category=${category}`
        if (tag) queryParams += `&tag=${tag}`
        if (completed !== undefined) queryParams += `&completed=${completed}`
        if (archived !== undefined) queryParams += `&archived=${archived}`
        return queryParams
      },
      providesTags: ['Note'],
    }),
    getNote: builder.query<NoteResponse, string>({
      query: (id) => `/${id}`,
      providesTags: (_result, _error, id) => [{ type: 'Note', id }],
    }),
    createNote: builder.mutation<NoteResponse, CreateNoteRequest>({
      query: (note) => ({
        url: '',
        method: 'POST',
        body: note,
      }),
      invalidatesTags: ['Note'],
    }),
    updateNote: builder.mutation<NoteResponse, { id: string; data: Partial<CreateNoteRequest> }>({
      query: ({ id, data }) => ({
        url: `/${id}`,
        method: 'PUT',
        body: data,
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'Note', id }],
    }),
    deleteNote: builder.mutation<void, string>({
      query: (id) => ({
        url: `/${id}`,
        method: 'DELETE',
      }),
      invalidatesTags: ['Note'],
    }),
    searchNotes: builder.query<NotesResponse, { query: string; page?: number; limit?: number }>({
      query: ({ query, page = 1, limit = 20 }) => `/search?q=${encodeURIComponent(query)}&page=${page}&limit=${limit}`,
      providesTags: ['Note'],
    }),
    updateNoteProgress: builder.mutation<NoteResponse, { id: string; progress: number; isCompleted?: boolean }>({
      query: ({ id, progress, isCompleted }) => ({
        url: `/${id}/progress`,
        method: 'POST',
        body: { progress, isCompleted },
      }),
      invalidatesTags: (_result, _error, { id }) => [{ type: 'Note', id }],
    }),
    getCategories: builder.query<{ success: boolean; data: { category: string; count: number }[] }, void>({
      query: () => '/categories',
    }),
  }),
})

export const {
  useGetNotesQuery,
  useGetNoteQuery,
  useCreateNoteMutation,
  useUpdateNoteMutation,
  useDeleteNoteMutation,
  useSearchNotesQuery,
  useUpdateNoteProgressMutation,
  useGetCategoriesQuery,
} = notesApi