import React, { useState } from 'react'
import { useSelector } from 'react-redux'
import {
  Container,
  Paper,
  Typography,
  Box,
  Avatar,
  Button,
  TextField,
  Grid,
  IconButton,
  CircularProgress,
  Alert,
  Divider,
} from '@mui/material'
import { Edit, PhotoCamera, Save, Cancel } from '@mui/icons-material'
import { RootState } from '../../store/index'
import { useUpdateProfileMutation } from '../../store/api/authApi'

const Profile = () => {
  const { user, isLoading } = useSelector((state: RootState) => state.auth)
  const [updateProfile] = useUpdateProfileMutation()
  
  const [isEditing, setIsEditing] = useState(false)
  const [formData, setFormData] = useState({
    name: user?.name || '',
    email: user?.email || '',
    bio: user?.bio || '',
    avatar: user?.avatar || '',
  })
  const [errors, setErrors] = useState({
    name: '',
    email: '',
  })
  const [successMessage, setSuccessMessage] = useState('')
  const [selectedAvatar, setSelectedAvatar] = useState<File | null>(null)
  const [avatarPreview, setAvatarPreview] = useState<string>(user?.avatar || '')

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target
    setFormData(prev => ({ ...prev, [name]: value }))
    
    // 清除字段错误
    if (errors[name as keyof typeof errors]) {
      setErrors(prev => ({ ...prev, [name]: '' }))
    }
  }

  const handleAvatarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0]
      setSelectedAvatar(file)
      
      // 创建预览
      const reader = new FileReader()
      reader.onload = () => {
        setAvatarPreview(reader.result as string)
      }
      reader.readAsDataURL(file)
    }
  }

  const validateForm = () => {
    const newErrors = {
      name: '',
      email: '',
    }
    
    if (!formData.name.trim()) {
      newErrors.name = '姓名不能为空'
    }
    
    if (!formData.email.trim()) {
      newErrors.email = '邮箱不能为空'
    } else if (!/\S+@\S+\.\S+/.test(formData.email)) {
      newErrors.email = '请输入有效的邮箱地址'
    }
    
    setErrors(newErrors)
    return !newErrors.name && !newErrors.email
  }

  const handleSave = async () => {
    if (validateForm()) {
      try {
        // 如果有新头像，先上传
        let avatarUrl = formData.avatar
        if (selectedAvatar) {
          // 这里应该调用上传API，现在使用模拟
          avatarUrl = URL.createObjectURL(selectedAvatar)
        }
        
        await updateProfile({
          ...formData,
          avatar: avatarUrl
        }).unwrap()
        
        setSuccessMessage('个人资料更新成功')
        setIsEditing(false)
        setSelectedAvatar(null)
        
        // 3秒后清除成功消息
        setTimeout(() => setSuccessMessage(''), 3000)
      } catch (error) {
        console.error('更新个人资料失败:', error)
      }
    }
  }

  const handleCancel = () => {
    // 重置表单数据
    setFormData({
      name: user?.name || '',
      email: user?.email || '',
      bio: user?.bio || '',
      avatar: user?.avatar || '',
    })
    setAvatarPreview(user?.avatar || '')
    setSelectedAvatar(null)
    setIsEditing(false)
    setErrors({ name: '', email: '' })
  }

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Paper elevation={3} sx={{ p: 4, borderRadius: 2 }}>
        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
          <Typography variant="h4" component="h1">
            个人资料
          </Typography>
          {!isEditing ? (
            <Button
              variant="outlined"
              startIcon={<Edit />}
              onClick={() => setIsEditing(true)}
            >
              编辑
            </Button>
          ) : (
            <Box>
              <Button
                variant="contained"
                startIcon={<Save />}
                onClick={handleSave}
                disabled={isLoading}
                sx={{ mr: 1 }}
              >
                {isLoading ? <CircularProgress size={20} /> : '保存'}
              </Button>
              <Button
                variant="outlined"
                startIcon={<Cancel />}
                onClick={handleCancel}
              >
                取消
              </Button>
            </Box>
          )}
        </Box>
        
        {successMessage && (
          <Alert severity="success" sx={{ mb: 3 }}>
            {successMessage}
          </Alert>
        )}
        
        <Grid container spacing={3}>
          <Grid size={{ xs: 12, md: 4 }} sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <Box sx={{ position: 'relative' }}>
              <Avatar
                src={avatarPreview}
                alt={formData.name}
                sx={{ width: 150, height: 150, mb: 2 }}
              />
              {isEditing && (
                <IconButton
                  aria-label="upload picture"
                  component="label"
                  sx={{
                    position: 'absolute',
                    bottom: 10,
                    right: 10,
                    backgroundColor: 'background.paper',
                    boxShadow: 2,
                  }}
                >
                  <input hidden accept="image/*" type="file" onChange={handleAvatarChange} />
                  <PhotoCamera />
                </IconButton>
              )}
            </Box>
            <Typography variant="h6">{formData.name}</Typography>
            <Typography variant="body2" color="text.secondary">
              {user?.role || '普通用户'}
            </Typography>
          </Grid>
          
          <Grid size={{ xs: 12, md: 8 }}>
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
              <TextField
                label="姓名"
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                disabled={!isEditing}
                error={!!errors.name}
                helperText={errors.name}
                fullWidth
              />
              
              <TextField
                label="邮箱"
                name="email"
                value={formData.email}
                onChange={handleInputChange}
                disabled={!isEditing}
                error={!!errors.email}
                helperText={errors.email}
                fullWidth
              />
              
              <TextField
                label="个人简介"
                name="bio"
                value={formData.bio}
                onChange={handleInputChange}
                disabled={!isEditing}
                multiline
                rows={4}
                fullWidth
              />
              
              <Divider />
              
              <Box>
                <Typography variant="h6" gutterBottom>
                  账户信息
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  注册时间: {user?.createdAt ? new Date(user.createdAt).toLocaleDateString() : '未知'}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  最后登录: {user?.lastLogin ? new Date(user.lastLogin).toLocaleString() : '未知'}
                </Typography>
              </Box>
            </Box>
          </Grid>
        </Grid>
      </Paper>
    </Container>
  )
}

export default Profile