/**
 * 博客模块数据加载器
 * 集成统一数据缓存服务，提供高效的博客数据加载
 */

import { DataLoader, DataType, CacheKeyStrategy, dataService } from './dataCache';
import { BlogPostWithId } from '../../types';
import { api } from './api';

// 博客查询参数接口
export interface BlogQueryParams {
  page?: number;
  limit?: number;
  category?: string;
  tag?: string;
  search?: string;
  sortBy?: 'date' | 'title' | 'viewCount';
  sortOrder?: 'asc' | 'desc';
}

// 博客文章列表响应接口
export interface BlogPostsResponse {
  posts: BlogPostWithId[];
  total: number;
  page: number;
  limit: number;
  totalPages: number;
  categories: string[];
  tags: string[];
}

// 博客统计信息接口
export interface BlogStats {
  totalPosts: number;
  totalCategories: number;
  totalTags: number;
  postsByCategory: Record<string, number>;
  postsByTag: Record<string, number>;
  recentPosts: BlogPostWithId[];
  popularPosts: BlogPostWithId[];
}

// 博客文章列表加载器
class BlogPostsLoader implements DataLoader<BlogPostsResponse> {
  identifier = DataType.BLOG_POSTS;
  private params: BlogQueryParams;

  constructor(params: BlogQueryParams = {}) {
    this.params = params;
  }

  async load(): Promise<BlogPostsResponse> {
    console.log(`加载博客文章列表，参数:`, this.params);
    
    try {
      // 使用新的 API 获取所有文章
      const result = await api.blog.getBlogPosts({
        page: this.params.page || 1,
        limit: this.params.limit || 10,
        category: this.params.category,
        tag: this.params.tag,
        source: 'local'
      });
      
      if (!result.success) {
        throw new Error('获取博客文章失败');
      }
      
      const allPosts = result.data || [];
      
      // 如果有搜索条件，需要进一步过滤
      let filteredPosts = [...allPosts];
      
      // 按搜索词过滤
      if (this.params.search) {
        const searchLower = this.params.search.toLowerCase();
        filteredPosts = filteredPosts.filter(post => 
          post.title.toLowerCase().includes(searchLower) ||
          post.excerpt.toLowerCase().includes(searchLower) ||
          post.content.toLowerCase().includes(searchLower)
        );
      }
      
      // 获取所有分类和标签
      const categories = [...new Set(allPosts.map(post => post.category))];
      const tags = [...new Set(allPosts.flatMap(post => post.tags || []))];
      
      console.log(`成功加载 ${filteredPosts.length} 篇博客文章`);
      
      return {
        posts: filteredPosts,
        total: result.pagination?.total || filteredPosts.length,
        page: this.params.page || 1,
        limit: this.params.limit || 10,
        totalPages: result.pagination?.totalPages || 1,
        categories,
        tags
      };
    } catch (error) {
      console.error('加载博客文章列表失败:', error);
      throw error;
    }
  }
}

// 单个博客文章加载器
class BlogPostLoader implements DataLoader<BlogPostWithId | null> {
  identifier = DataType.BLOG_POST;
  private slug: string;

  constructor(slug: string) {
    this.slug = slug;
  }

  async load(): Promise<BlogPostWithId | null> {
    console.log(`加载博客文章，slug: ${this.slug}`);
    
    try {
      const result = await api.blog.getBlogPost({ slug: this.slug, source: 'local' });
      
      if (result.success && result.data) {
        console.log(`成功加载博客文章: ${result.data.title}`);
        return result.data;
      } else {
        console.warn(`未找到博客文章，slug: ${this.slug}`);
        return null;
      }
    } catch (error) {
      console.error(`加载博客文章失败，slug: ${this.slug}`, error);
      throw error;
    }
  }
}

// 博客统计信息加载器
class BlogStatsLoader implements DataLoader<BlogStats> {
  identifier = DataType.BLOG_STATS;
  dependencies = [DataType.BLOG_POSTS];

  async load(): Promise<BlogStats> {
    console.log('加载博客统计信息');
    
    try {
      // 使用新的 API 获取所有文章
      const result = await api.blog.getBlogPosts({
        page: 1,
        limit: 1000, // 获取所有文章
        source: 'local'
      });
      
      if (!result.success) {
        throw new Error('获取博客文章失败');
      }
      
      const allPosts = result.data || [];
      
      // 统计分类
      const postsByCategory: Record<string, number> = {};
      allPosts.forEach(post => {
        const category = post.category || '未分类';
        postsByCategory[category] = (postsByCategory[category] || 0) + 1;
      });
      
      // 统计标签
      const postsByTag: Record<string, number> = {};
      allPosts.forEach(post => {
        if (post.tags) {
          post.tags.forEach(tag => {
            postsByTag[tag] = (postsByTag[tag] || 0) + 1;
          });
        }
      });
      
      // 获取最近文章（最新的5篇）
      const recentPosts = [...allPosts]
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())
        .slice(0, 5);
      
      // 获取热门文章（按浏览量排序的前5篇）
      const popularPosts = [...allPosts]
        .sort((a, b) => (b.viewCount || 0) - (a.viewCount || 0))
        .slice(0, 5);
      
      const stats: BlogStats = {
        totalPosts: allPosts.length,
        totalCategories: Object.keys(postsByCategory).length,
        totalTags: Object.keys(postsByTag).length,
        postsByCategory,
        postsByTag,
        recentPosts,
        popularPosts
      };
      
      console.log('成功加载博客统计信息:', stats);
      return stats;
    } catch (error) {
      console.error('加载博客统计信息失败:', error);
      throw error;
    }
  }
}

// 博客数据服务
export class BlogDataService {
  private static instance: BlogDataService;
  
  private constructor() {
    this.registerLoaders();
  }
  
  static getInstance(): BlogDataService {
    if (!BlogDataService.instance) {
      BlogDataService.instance = new BlogDataService();
    }
    return BlogDataService.instance;
  }
  
  private registerLoaders() {
    // 注册博客数据加载器
    dataService.registerDataLoader(new BlogPostsLoader());
    dataService.registerDataLoader(new BlogPostLoader(''));
    dataService.registerDataLoader(new BlogStatsLoader());
  }
  
  // 获取博客文章列表
  async getBlogPosts(params: BlogQueryParams = {}): Promise<BlogPostsResponse> {
    const loader = new BlogPostsLoader(params);
    const key = CacheKeyStrategy.generateKey(DataType.BLOG_POSTS, params);
    
    // 临时注册加载器
    dataService.registerDataLoader(loader);
    
    return await dataService.getData(key, loader);
  }
  
  // 获取单个博客文章
  async getBlogPost(slug: string): Promise<BlogPostWithId | null> {
    const loader = new BlogPostLoader(slug);
    const key = CacheKeyStrategy.generateKey(DataType.BLOG_POST, { slug });
    
    // 临时注册加载器
    dataService.registerDataLoader(loader);
    
    return await dataService.getData(key, loader);
  }
  
  // 获取博客统计信息
  async getBlogStats(): Promise<BlogStats> {
    const loader = new BlogStatsLoader();
    const key = 'blog_stats';
    
    // 临时注册加载器
    dataService.registerDataLoader(loader);
    
    return await dataService.getData(key, loader);
  }
  
  // 刷新博客文章列表
  async refreshBlogPosts(params: BlogQueryParams = {}): Promise<BlogPostsResponse> {
    this.clearBlogCache();
    return this.getBlogPosts(params);
  }
  
  // 刷新单个博客文章
  async refreshBlogPost(slug: string): Promise<BlogPostWithId | null> {
    this.clearBlogCache();
    return this.getBlogPost(slug);
  }
  
  // 刷新博客统计信息
  async refreshBlogStats(): Promise<BlogStats> {
    this.clearBlogCache();
    return this.getBlogStats();
  }
  
  // 搜索博客文章
  async searchBlogPosts(query: string, params: BlogQueryParams = {}): Promise<BlogPostsResponse> {
    return this.getBlogPosts({ ...params, search: query });
  }
  
  // 清除博客相关缓存
  clearBlogCache() {
    // 由于dataService没有clearCache方法，我们使用refreshData来清除特定类型的缓存
    try {
      dataService.refreshData(DataType.BLOG_POSTS);
      dataService.refreshData(DataType.BLOG_POST);
      dataService.refreshData('blog_stats');
      console.log('博客相关缓存已清除');
    } catch (error) {
      console.error('清除博客缓存失败:', error);
      // 如果refreshData失败，则清除所有缓存
      dataService.clearAllCache();
    }
  }
  
  // 预加载博客数据
  async preloadBlogData() {
    try {
      // 预加载博客文章列表
      await this.getBlogPosts({ limit: 10 });
      console.log('博客文章列表预加载完成');
      
      // 预加载博客统计信息
      await this.getBlogStats();
      console.log('博客统计信息预加载完成');
    } catch (error) {
      console.error('博客数据预加载失败:', error);
    }
  }
}

// 导出单例实例
export const blogDataService = BlogDataService.getInstance();