/**
 * 错误处理工具类
 * 提供统一的错误处理机制，包括网络异常、数据为空等场景
 */

// 错误类型枚举
export enum ErrorType {
  NETWORK_ERROR = 'NETWORK_ERROR',
  DATA_EMPTY = 'DATA_EMPTY',
  PERMISSION_DENIED = 'PERMISSION_DENIED',
  TIMEOUT = 'TIMEOUT',
  UNKNOWN = 'UNKNOWN'
}

// 错误严重程度
export enum ErrorSeverity {
  LOW = 'LOW',
  MEDIUM = 'MEDIUM',
  HIGH = 'HIGH',
  CRITICAL = 'CRITICAL'
}

// 自定义错误类
export class AppError extends Error {
  public readonly type: ErrorType
  public readonly severity: ErrorSeverity
  public readonly context?: Record<string, any>
  public readonly timestamp: Date
  public readonly retryable: boolean

  constructor(
    message: string,
    type: ErrorType = ErrorType.UNKNOWN,
    severity: ErrorSeverity = ErrorSeverity.MEDIUM,
    context?: Record<string, any>,
    retryable: boolean = false
  ) {
    super(message)
    this.name = 'AppError'
    this.type = type
    this.severity = severity
    this.context = context
    this.timestamp = new Date()
    this.retryable = retryable
  }
}

// 错误处理器接口
export interface ErrorHandler {
  handle(error: AppError): void | Promise<void>
}

// 默认错误处理器
class DefaultErrorHandler implements ErrorHandler {
  async handle(error: AppError): Promise<void> {
    // 根据错误类型和严重程度进行不同的处理
    switch (error.type) {
      case ErrorType.NETWORK_ERROR:
        console.error(`网络错误: ${error.message}`, error.context)
        break
      case ErrorType.DATA_EMPTY:
        console.warn(`数据为空: ${error.message}`, error.context)
        break
      case ErrorType.PERMISSION_DENIED:
        console.error(`权限被拒绝: ${error.message}`, error.context)
        break
      case ErrorType.TIMEOUT:
        console.error(`操作超时: ${error.message}`, error.context)
        break
      default:
        console.error(`未知错误: ${error.message}`, error.context)
    }
  }
}

// 重试配置
export interface RetryConfig {
  maxAttempts: number
  delayMs: number
  backoffMultiplier?: number
  maxDelayMs?: number
}

// 默认重试配置
const DEFAULT_RETRY_CONFIG: RetryConfig = {
  maxAttempts: 3,
  delayMs: 1000,
  backoffMultiplier: 2,
  maxDelayMs: 10000
}

/**
 * 错误处理工具类
 */
export class ErrorHandlerUtils {
  private static errorHandler: ErrorHandler = new DefaultErrorHandler()

  /**
   * 设置自定义错误处理器
   */
  static setErrorHandler(handler: ErrorHandler): void {
    this.errorHandler = handler
  }

  /**
   * 处理错误
   */
  static async handleError(error: Error | AppError, context?: Record<string, any>): Promise<void> {
    let appError: AppError

    if (error instanceof AppError) {
      appError = error
    } else {
      // 将普通Error转换为AppError
      appError = new AppError(
        error.message,
        ErrorType.UNKNOWN,
        ErrorSeverity.MEDIUM,
        context
      )
    }

    await this.errorHandler.handle(appError)
  }

  /**
   * 创建网络错误
   */
  static createNetworkError(message: string, context?: Record<string, any>): AppError {
    return new AppError(
      message,
      ErrorType.NETWORK_ERROR,
      ErrorSeverity.HIGH,
      context,
      true // 网络错误通常可以重试
    )
  }

  /**
   * 创建数据为空错误
   */
  static createDataEmptyError(message: string, context?: Record<string, any>): AppError {
    return new AppError(
      message,
      ErrorType.DATA_EMPTY,
      ErrorSeverity.LOW,
      context,
      false // 数据为空通常不需要重试
    )
  }

  /**
   * 创建权限错误
   */
  static createPermissionError(message: string, context?: Record<string, any>): AppError {
    return new AppError(
      message,
      ErrorType.PERMISSION_DENIED,
      ErrorSeverity.HIGH,
      context,
      false // 权限错误通常不需要重试
    )
  }

  /**
   * 创建超时错误
   */
  static createTimeoutError(message: string, context?: Record<string, any>): AppError {
    return new AppError(
      message,
      ErrorType.TIMEOUT,
      ErrorSeverity.MEDIUM,
      context,
      true // 超时错误可以重试
    )
  }

  /**
   * 带重试的异步操作执行器
   */
  static async executeWithRetry<T>(
    operation: () => Promise<T>,
    config: Partial<RetryConfig> = {},
    context?: Record<string, any>
  ): Promise<T> {
    const finalConfig = { ...DEFAULT_RETRY_CONFIG, ...config }
    let lastError: Error | AppError | null = null
    let delay = finalConfig.delayMs

    for (let attempt = 1; attempt <= finalConfig.maxAttempts; attempt++) {
      try {
        return await operation()
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error))

        // 如果是最后一次尝试，直接抛出错误
        if (attempt === finalConfig.maxAttempts) {
          break
        }

        // 如果错误不可重试，直接抛出
        if (lastError instanceof AppError && !lastError.retryable) {
          break
        }

        // 等待后重试
        await this.delay(delay)
        
        // 计算下次延迟时间（指数退避）
        if (finalConfig.backoffMultiplier) {
          delay = Math.min(delay * finalConfig.backoffMultiplier, finalConfig.maxDelayMs || delay)
        }

        console.warn(`操作失败，${delay}ms后进行第${attempt + 1}次重试:`, lastError.message)
      }
    }

    // 处理最后的错误
    if (lastError) {
      await this.handleError(lastError, context)
      throw lastError
    }

    // 不应该到达这里，但为了类型安全
    throw new Error('执行失败且没有捕获到错误')
  }

  /**
   * 带超时的异步操作执行器
   */
  static async executeWithTimeout<T>(
    operation: () => Promise<T>,
    timeoutMs: number,
    context?: Record<string, any>
  ): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const timeoutId = setTimeout(() => {
        const error = this.createTimeoutError(
          `操作在${timeoutMs}ms后超时`,
          context
        )
        reject(error)
      }, timeoutMs)

      operation()
        .then(result => {
          clearTimeout(timeoutId)
          resolve(result)
        })
        .catch(error => {
          clearTimeout(timeoutId)
          reject(error)
        })
    })
  }

  /**
   * 检查数据是否为空
   */
  static validateDataNotEmpty<T>(
    data: T | null | undefined,
    errorMessage: string = '数据不能为空',
    context?: Record<string, any>
  ): T {
    if (data === null || data === undefined || 
        (Array.isArray(data) && data.length === 0) ||
        (typeof data === 'object' && Object.keys(data).length === 0)) {
      throw this.createDataEmptyError(errorMessage, context)
    }
    return data
  }

  /**
   * 安全地执行异步操作，捕获并处理所有错误
   */
  static async safeExecute<T>(
    operation: () => Promise<T>,
    fallbackValue?: T,
    context?: Record<string, any>
  ): Promise<T | undefined> {
    try {
      return await operation()
    } catch (error) {
      await this.handleError(error instanceof Error ? error : new Error(String(error)), context)
      return fallbackValue
    }
  }

  /**
   * 延迟函数
   */
  private static delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms))
  }
}

export default ErrorHandlerUtils