/**
 * 缓存更新策略
 * 提供多种缓存更新策略，包括基于文件系统监控、定时更新和手动更新
 */

import { dataService, DataType } from './dataCache';
import { blogDataService } from './blogDataLoader';
import { entertainmentDataService } from './entertainmentDataLoader';

// 缓存更新策略枚举
export enum CacheUpdateStrategy {
  MANUAL = 'manual',           // 手动更新
  INTERVAL = 'interval',       // 定时更新
  FILE_WATCHER = 'file_watcher' // 文件系统监控
}

// 缓存更新配置
export interface CacheUpdateConfig {
  strategy: CacheUpdateStrategy;
  interval?: number;           // 定时更新间隔（毫秒）
  watchPaths?: string[];       // 监控的路径
  debounceMs?: number;         // 防抖时间（毫秒）
  enabled?: boolean;           // 是否启用
}

// 文件变化事件类型
export enum FileChangeType {
  ADDED = 'added',
  CHANGED = 'changed',
  REMOVED = 'removed'
}

// 文件变化事件
export interface FileChangeEvent {
  type: FileChangeType;
  path: string;
  timestamp: number;
}

// 缓存更新事件
export interface CacheUpdateEvent {
  dataType: DataType | string;
  timestamp: number;
  success: boolean;
  error?: string;
  affectedKeys?: string[];
}

// 缓存更新监听器
export type CacheUpdateListener = (event: CacheUpdateEvent) => void;

/**
 * 缓存更新管理器
 */
export class CacheUpdateManager {
  private static instance: CacheUpdateManager;
  private config: Map<DataType | string, CacheUpdateConfig> = new Map();
  private listeners: CacheUpdateListener[] = [];
  private intervals: Map<string, NodeJS.Timeout> = new Map();
  private fileWatchers: Map<string, any> = new Map(); // 实际实现中会使用chokidar等库
  private debounceTimers: Map<string, NodeJS.Timeout> = new Map();
  private isInitialized = false;

  private constructor() {}

  static getInstance(): CacheUpdateManager {
    if (!CacheUpdateManager.instance) {
      CacheUpdateManager.instance = new CacheUpdateManager();
    }
    return CacheUpdateManager.instance;
  }

  /**
   * 初始化缓存更新管理器
   */
  async initialize(): Promise<void> {
    if (this.isInitialized) {
      return;
    }

    console.log('初始化缓存更新管理器');
    
    // 设置默认配置
    this.setupDefaultConfigs();
    
    // 启用配置的更新策略
    await this.enableConfiguredStrategies();
    
    this.isInitialized = true;
    console.log('缓存更新管理器初始化完成');
  }

  /**
   * 设置默认配置
   */
  private setupDefaultConfigs(): void {
    // 博客文章配置 - 使用文件系统监控
    this.config.set(DataType.BLOG_POSTS, {
      strategy: CacheUpdateStrategy.FILE_WATCHER,
      watchPaths: ['src/content/blog'],
      debounceMs: 1000,
      enabled: true
    });

    // 博客统计配置 - 依赖博客文章更新
    this.config.set(DataType.BLOG_STATS, {
      strategy: CacheUpdateStrategy.MANUAL,
      enabled: true
    });

    // 媒体文件配置 - 使用文件系统监控
    this.config.set(DataType.MEDIA_FILES, {
      strategy: CacheUpdateStrategy.FILE_WATCHER,
      watchPaths: ['public/media', 'public/images', 'public/videos', 'public/audio'],
      debounceMs: 1000,
      enabled: true
    });

    // 媒体统计配置 - 依赖媒体文件更新
    this.config.set(DataType.MEDIA_STATS, {
      strategy: CacheUpdateStrategy.MANUAL,
      enabled: true
    });
  }

  /**
   * 启用配置的更新策略
   */
  private async enableConfiguredStrategies(): Promise<void> {
    for (const [dataType, config] of this.config.entries()) {
      if (config.enabled) {
        await this.enableStrategy(dataType, config);
      }
    }
  }

  /**
   * 启用特定数据类型的更新策略
   */
  async enableStrategy(dataType: DataType | string, config: CacheUpdateConfig): Promise<void> {
    console.log(`启用${dataType}的${config.strategy}更新策略`);
    
    // 先禁用现有策略
    await this.disableStrategy(dataType);
    
    // 根据策略类型启用新策略
    switch (config.strategy) {
      case CacheUpdateStrategy.INTERVAL:
        this.enableIntervalStrategy(dataType, config);
        break;
      case CacheUpdateStrategy.FILE_WATCHER:
        await this.enableFileWatcherStrategy(dataType, config);
        break;
      case CacheUpdateStrategy.MANUAL:
        // 手动策略不需要启用任何东西
        break;
    }
  }

  /**
   * 禁用特定数据类型的更新策略
   */
  async disableStrategy(dataType: DataType | string): Promise<void> {
    // 清除定时器
    const interval = this.intervals.get(dataType.toString());
    if (interval) {
      clearInterval(interval);
      this.intervals.delete(dataType.toString());
    }
    
    // 清除文件监控
    const watcher = this.fileWatchers.get(dataType.toString());
    if (watcher) {
      // 实际实现中会调用watcher.close()
      this.fileWatchers.delete(dataType.toString());
    }
    
    // 清除防抖定时器
    const debounceTimer = this.debounceTimers.get(dataType.toString());
    if (debounceTimer) {
      clearTimeout(debounceTimer);
      this.debounceTimers.delete(dataType.toString());
    }
  }

  /**
   * 启用定时更新策略
   */
  private enableIntervalStrategy(dataType: DataType | string, config: CacheUpdateConfig): void {
    if (!config.interval) {
      console.warn(`${dataType}的定时更新策略未设置间隔时间`);
      return;
    }
    
    const interval = setInterval(async () => {
      await this.updateCache(dataType);
    }, config.interval);
    
    this.intervals.set(dataType.toString(), interval);
    console.log(`${dataType}的定时更新策略已启用，间隔: ${config.interval}ms`);
  }

  /**
   * 启用文件系统监控策略
   */
  private async enableFileWatcherStrategy(dataType: DataType | string, config: CacheUpdateConfig): Promise<void> {
    if (!config.watchPaths || config.watchPaths.length === 0) {
      console.warn(`${dataType}的文件监控策略未设置监控路径`);
      return;
    }
    
    // 注意：这里是一个简化的实现
    // 实际应用中应该使用chokidar等库来监控文件系统变化
    console.log(`${dataType}的文件监控策略已启用，监控路径:`, config.watchPaths);
    
    // 模拟文件监控
    // 在实际实现中，这里会使用chokidar等库
    // const chokidar = await import('chokidar');
    // const watcher = chokidar.watch(config.watchPaths);
    // watcher.on('all', (event, path) => {
    //   this.handleFileChange(dataType, event as FileChangeType, path, config.debounceMs);
    // });
    // this.fileWatchers.set(dataType.toString(), watcher);
  }

  /**
   * 处理文件变化事件
   */
  private handleFileChange(
    dataType: DataType | string, 
    changeType: FileChangeType, 
    path: string, 
    debounceMs?: number
  ): void {
    console.log(`检测到文件变化: ${changeType} - ${path}`);
    
    // 清除之前的防抖定时器
    const timerId = this.debounceTimers.get(dataType.toString());
    if (timerId) {
      clearTimeout(timerId);
    }
    
    // 设置新的防抖定时器
    const newTimerId = setTimeout(async () => {
      await this.updateCache(dataType);
      this.debounceTimers.delete(dataType.toString());
    }, debounceMs || 1000);
    
    this.debounceTimers.set(dataType.toString(), newTimerId);
  }

  /**
   * 更新缓存
   */
  async updateCache(dataType: DataType | string): Promise<void> {
    console.log(`开始更新${dataType}缓存`);
    const startTime = Date.now();
    
    try {
      let affectedKeys: string[] = [];
      
      switch (dataType) {
        case DataType.BLOG_POSTS:
          await blogDataService.refreshBlogPosts();
          affectedKeys.push(DataType.BLOG_POSTS);
          // 博客文章更新后，统计信息也需要更新
          await blogDataService.refreshBlogStats();
          affectedKeys.push(DataType.BLOG_STATS);
          break;
          
        case DataType.BLOG_STATS:
          await blogDataService.refreshBlogStats();
          affectedKeys.push(DataType.BLOG_STATS);
          break;
          
        case DataType.MEDIA_FILES:
          await entertainmentDataService.refreshMediaFiles();
          affectedKeys.push(DataType.MEDIA_FILES);
          // 媒体文件更新后，统计信息也需要更新
          await entertainmentDataService.refreshMediaStats();
          affectedKeys.push(DataType.MEDIA_STATS);
          break;
          
        case DataType.MEDIA_STATS:
          await entertainmentDataService.refreshMediaStats();
          affectedKeys.push(DataType.MEDIA_STATS);
          break;
          
        default:
          console.warn(`未知的数据类型: ${dataType}`);
          return;
      }
      
      const duration = Date.now() - startTime;
      console.log(`${dataType}缓存更新完成，耗时: ${duration}ms`);
      
      // 通知监听器
      this.notifyListeners({
        dataType,
        timestamp: Date.now(),
        success: true,
        affectedKeys
      });
    } catch (error) {
      const duration = Date.now() - startTime;
      console.error(`${dataType}缓存更新失败，耗时: ${duration}ms`, error);
      
      // 通知监听器
      this.notifyListeners({
        dataType,
        timestamp: Date.now(),
        success: false,
        error: error instanceof Error ? error.message : String(error)
      });
    }
  }

  /**
   * 手动更新缓存
   */
  async manualUpdate(dataType: DataType | string): Promise<void> {
    await this.updateCache(dataType);
  }

  /**
   * 更新所有缓存
   */
  async updateAllCaches(): Promise<void> {
    console.log('开始更新所有缓存');
    
    for (const dataType of this.config.keys()) {
      await this.updateCache(dataType);
    }
    
    console.log('所有缓存更新完成');
  }

  /**
   * 添加缓存更新监听器
   */
  addListener(listener: CacheUpdateListener): void {
    this.listeners.push(listener);
  }

  /**
   * 移除缓存更新监听器
   */
  removeListener(listener: CacheUpdateListener): void {
    const index = this.listeners.indexOf(listener);
    if (index > -1) {
      this.listeners.splice(index, 1);
    }
  }

  /**
   * 通知所有监听器
   */
  private notifyListeners(event: CacheUpdateEvent): void {
    for (const listener of this.listeners) {
      try {
        listener(event);
      } catch (error) {
        console.error('缓存更新监听器执行失败:', error);
      }
    }
  }

  /**
   * 获取数据类型的配置
   */
  getConfig(dataType: DataType | string): CacheUpdateConfig | undefined {
    return this.config.get(dataType);
  }

  /**
   * 设置数据类型的配置
   */
  setConfig(dataType: DataType | string, config: CacheUpdateConfig): void {
    this.config.set(dataType, config);
    
    // 如果已初始化，立即应用新配置
    if (this.isInitialized && config.enabled) {
      this.enableStrategy(dataType, config);
    }
  }

  /**
   * 获取所有配置
   */
  getAllConfigs(): Map<DataType | string, CacheUpdateConfig> {
    return new Map(this.config);
  }

  /**
   * 销毁缓存更新管理器
   */
  async destroy(): Promise<void> {
    console.log('销毁缓存更新管理器');
    
    // 禁用所有策略
    for (const dataType of this.config.keys()) {
      await this.disableStrategy(dataType);
    }
    
    // 清空监听器
    this.listeners = [];
    
    this.isInitialized = false;
    console.log('缓存更新管理器已销毁');
  }
}

// 导出单例实例
export const cacheUpdateManager = CacheUpdateManager.getInstance();