import { marked } from 'marked';
import hljs from 'highlight.js';

// 初始化marked配置
const configureMarked = () => {
  marked.setOptions({
    breaks: true,
    gfm: true,
  });
  
  // 自定义渲染器来处理代码高亮
  const renderer = new marked.Renderer();
  
  renderer.code = function({ text, lang }: { text: string; lang?: string }) {
    const language = lang || '';
    if (language && hljs.getLanguage(language)) {
      try {
        const highlighted = hljs.highlight(text, { language: language });
        return `<pre><code class="hljs language-${language}">${highlighted.value}</code></pre>`;
      } catch (err) {
        console.error('代码高亮处理错误:', err);
      }
    }
    
    const highlighted = hljs.highlightAuto(text);
    return `<pre><code class="hljs">${highlighted.value}</code></pre>`;
  };
  
  marked.use({ renderer });
};

// 确保marked只配置一次
if (!marked.defaults) {
  configureMarked();
}

// 处理Markdown内容中的环境变量引用
export const processMarkdownContent = (content: string): string => {
  // 处理环境变量引用，如 ${import.meta.env.BASE_URL}
  return content.replace(/\$\{import\.meta\.env\.([^}]+)\}/g, (match, envVar) => {
    return import.meta.env[envVar] || match;
  });
};

// 将Markdown转换为HTML
export const markdownToHtml = async (markdown: string): Promise<string> => {
  const processedContent = processMarkdownContent(markdown);
  const html = await marked(processedContent);
  return html;
};

// 提取Markdown摘要
export const extractExcerpt = (content: string, maxLength: number = 160): string => {
  // 移除Markdown语法
  const plainText = content
    .replace(/^#+\s+/gm, '') // 移除标题
    .replace(/\*\*(.*?)\*\*/g, '$1') // 移除粗体
    .replace(/\*(.*?)\*/g, '$1') // 移除斜体
    .replace(/`(.*?)`/g, '$1') // 移除行内代码
    .replace(/```[\s\S]*?```/g, '') // 移除代码块
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // 移除链接，保留文本
    .replace(/!\[([^\]]*)\]\([^)]+\)/g, '$1') // 移除图片，保留alt文本
    .replace(/\n+/g, ' ') // 将换行符替换为空格
    .trim();
  
  // 截取指定长度
  if (plainText.length <= maxLength) {
    return plainText;
  }
  
  return plainText.substring(0, maxLength).replace(/\s+\S*$/, '') + '...';
};

// 获取文章中的标题
export const extractHeadings = (content: string) => {
  const headingRegex = /^(#{1,6})\s+(.+)$/gm;
  const headings: { level: number; text: string; id: string }[] = [];
  let match;
  
  while ((match = headingRegex.exec(content)) !== null) {
    const level = match[1].length;
    const text = match[2].trim();
    const id = text.toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-');
    
    headings.push({ level, text, id });
  }
  
  return headings;
};