import React, { useState, useRef, useEffect } from 'react';
import {
  Box,
  Skeleton,
  IconButton,
  Tooltip,
  Typography,
  useTheme,
  alpha,
  Zoom,
  Fade
} from '@mui/material';
import {
  Refresh as RefreshIcon,
  BrokenImage as BrokenImageIcon,
  ZoomIn as ZoomInIcon
} from '@mui/icons-material';

interface LazyImageProps {
  src: string;
  alt: string;
  className?: string;
  style?: React.CSSProperties;
  placeholder?: string;
  threshold?: number;
  height?: number | string;
  width?: number | string;
  objectFit?: 'cover' | 'contain' | 'fill' | 'none' | 'scale-down';
  borderRadius?: number | string;
  enableZoom?: boolean;
  showRetryButton?: boolean;
  onLoad?: () => void;
  onError?: () => void;
}

const LazyImage: React.FC<LazyImageProps> = ({ 
  src, 
  alt, 
  className = '', 
  style = {},
  placeholder = '/assets/blog/placeholder.svg',
  threshold = 0.1,
  height = 'auto',
  width = '100%',
  objectFit = 'cover',
  borderRadius = 0,
  enableZoom = false,
  showRetryButton = true,
  onLoad,
  onError
}) => {
  const theme = useTheme();
  const [isLoaded, setIsLoaded] = useState(false);
  const [isInView, setIsInView] = useState(false);
  const [hasError, setHasError] = useState(false);
  const [isZoomed, setIsZoomed] = useState(false);
  const [retryCount, setRetryCount] = useState(0);
  const imgRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // 初始时，如果组件已经挂载，直接设置为在视口中
    if (!isLoaded && !hasError) {
      setIsInView(true);
    }
  }, []);

  useEffect(() => {
    // 如果图片已经在视口中，设置IntersectionObserver
    if (containerRef.current && !isLoaded && !isInView) {
      const observer = new IntersectionObserver(
        ([entry]) => {
          if (entry.isIntersecting) {
            setIsInView(true);
            observer.disconnect();
          }
        },
        { threshold, rootMargin: '50px' } // 添加rootMargin提前加载
      );

      observer.observe(containerRef.current);

      return () => {
        if (containerRef.current) {
          observer.unobserve(containerRef.current);
        }
      };
    }
  }, [threshold, isLoaded, isInView]);

  // 添加调试日志
  useEffect(() => {
    if (isInView) {
      console.log('LazyImage - 图片即将加载:', src);
    }
  }, [isInView, src]);

  // 添加图片加载状态的调试日志
  useEffect(() => {
    console.log('LazyImage - 图片状态更新:', {
      src,
      isInView,
      isLoaded,
      hasError,
      retryCount
    });
  }, [isInView, isLoaded, hasError, retryCount, src]);

  const handleLoad = () => {
    console.log('LazyImage - 图片加载成功:', src);
    setIsLoaded(true);
    setHasError(false);
    if (onLoad) onLoad();
  };

  const handleError = (e: React.SyntheticEvent<HTMLImageElement, Event>) => {
    console.error('LazyImage - 图片加载失败:', src, e);
    setHasError(true);
    setIsLoaded(false);
    if (onError) onError();
    
    // 如果是相对路径，尝试添加基础路径
    if (src && !src.startsWith('http') && !src.startsWith('/')) {
      const absoluteSrc = `/${src}`;
      console.log('LazyImage - 尝试使用绝对路径:', absoluteSrc);
      setHasError(false); // 重置错误状态，尝试新路径
      if (imgRef.current) {
        imgRef.current.src = absoluteSrc;
      }
    }
    // 如果是绝对路径但仍然失败，尝试使用占位图
    else if (src && src.startsWith('/') && retryCount < 2) {
      console.log('LazyImage - 尝试使用占位图:', placeholder);
      setHasError(false); // 重置错误状态，尝试新路径
      setRetryCount(prev => prev + 1);
      if (imgRef.current) {
        imgRef.current.src = placeholder;
      }
    }
    // 如果占位图也加载失败，使用默认处理
    else if (retryCount >= 2) {
      console.log('LazyImage - 占位图也加载失败，显示错误状态');
    }
  };

  const handleRetry = () => {
    setRetryCount(prev => prev + 1);
    setHasError(false);
    setIsLoaded(false);
    // 强制重新加载图片，添加时间戳防止缓存
    if (imgRef.current) {
      const retrySrc = src.includes('?') ? `${src}&retry=${Date.now()}` : `${src}?retry=${Date.now()}`;
      imgRef.current.src = retrySrc;
    }
  };

  // 检查占位图是否存在
  const checkPlaceholderExists = () => {
    const img = new Image();
    img.onload = () => true;
    img.onerror = () => false;
    img.src = placeholder;
    return img.complete;
  };

  const handleZoomToggle = () => {
    setIsZoomed(!isZoomed);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Escape' && isZoomed) {
      setIsZoomed(false);
    }
  };

  return (
    <>
      <Box 
        ref={containerRef}
        className={`lazy-image-container ${className}`}
        sx={{
          position: 'relative',
          overflow: 'hidden',
          backgroundColor: theme.palette.mode === 'dark' 
            ? alpha(theme.palette.grey[800], 0.6) 
            : alpha(theme.palette.grey[200], 0.6),
          borderRadius: typeof borderRadius === 'number' ? `${borderRadius}px` : borderRadius,
          height,
          width,
          cursor: enableZoom ? 'pointer' : 'default',
          transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)',
          boxShadow: theme.palette.mode === 'dark'
            ? '0 3px 12px rgba(0, 0, 0, 0.35)'
            : '0 3px 16px rgba(102, 126, 234, 0.12)',
          '&:hover': enableZoom ? {
            transform: 'scale(1.04)',
            boxShadow: theme.palette.mode === 'dark'
              ? `0 14px 40px ${alpha(theme.palette.common.black, 0.55)}`
              : `0 14px 40px ${alpha(theme.palette.primary.main, 0.25)}`
          } : {
            boxShadow: theme.palette.mode === 'dark'
              ? `0 10px 32px ${alpha(theme.palette.common.black, 0.45)}`
              : `0 10px 32px ${alpha(theme.palette.primary.main, 0.18)}`
          },
          ...style
        }}
        onClick={enableZoom ? handleZoomToggle : undefined}
        onKeyDown={handleKeyDown}
        tabIndex={enableZoom ? 0 : -1}
        role={enableZoom ? "button" : undefined}
        aria-label={enableZoom ? "点击放大图片" : undefined}
      >
        {/* 加载骨架屏 */}
        {!isLoaded && !hasError && (
          <Skeleton 
            variant="rectangular" 
            width="100%" 
            height="100%" 
            animation="wave"
            sx={{
              position: 'absolute',
              top: 0,
              left: 0,
              transform: 'scale(1.02)',
              background: theme.palette.mode === 'dark'
                ? `linear-gradient(90deg, ${alpha(theme.palette.grey[800], 0.6)} 25%, ${alpha(theme.palette.grey[700], 0.7)} 50%, ${alpha(theme.palette.grey[800], 0.6)} 75%)`
                : `linear-gradient(90deg, ${alpha(theme.palette.grey[200], 0.6)} 25%, ${alpha(theme.palette.grey[300], 0.7)} 50%, ${alpha(theme.palette.grey[200], 0.6)} 75%)`,
              backgroundSize: '200% 100%',
              animation: 'skeleton-loading 1.8s infinite',
              '@keyframes skeleton-loading': {
                '0%': { backgroundPosition: '200% 0' },
                '100%': { backgroundPosition: '-200% 0' }
              }
            }}
          />
        )}
        
        {/* 错误状态 */}
        {hasError && (
          <Fade in timeout={300}>
            <Box
              sx={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                alignItems: 'center',
                justifyContent: 'center',
                backgroundColor: theme.palette.mode === 'dark'
                  ? alpha(theme.palette.grey[800], 0.95)
                  : alpha(theme.palette.grey[100], 0.98),
                color: theme.palette.text.secondary,
                p: 3,
                textAlign: 'center',
                transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)'
              }}
            >
              <BrokenImageIcon 
                sx={{ 
                  fontSize: 80, 
                  mb: 3, 
                  opacity: 0.65,
                  color: theme.palette.mode === 'dark'
                    ? theme.palette.grey[600]
                    : theme.palette.grey[400],
                  transition: 'all 0.35s ease',
                  '&:hover': {
                    transform: 'scale(1.12)',
                    opacity: 0.85
                  }
                }} 
              />
              <Typography 
                variant="body1" 
                gutterBottom
                sx={{
                  fontWeight: 700,
                  color: theme.palette.text.primary,
                  fontSize: '1.05rem'
                }}
              >
                图片加载失败
              </Typography>
              <Typography 
                variant="body2"
                sx={{
                  mb: 3,
                  opacity: 0.8,
                  fontSize: '0.9rem'
                }}
              >
                请检查网络连接或稍后重试
              </Typography>
              {showRetryButton && (
                <Tooltip title="重新加载图片">
                  <IconButton 
                    onClick={handleRetry}
                    size="medium"
                    sx={{
                      mt: 1.5,
                      backgroundColor: theme.palette.primary.main,
                      color: theme.palette.primary.contrastText,
                      borderRadius: 2.5,
                      p: 1.75,
                      transition: 'all 0.35s cubic-bezier(0.4, 0, 0.2, 1)',
                      '&:hover': {
                        backgroundColor: theme.palette.primary.dark,
                        transform: 'scale(1.18)',
                        boxShadow: theme.palette.mode === 'dark'
                          ? `0 8px 28px ${alpha(theme.palette.primary.main, 0.55)}`
                          : `0 8px 28px ${alpha(theme.palette.primary.main, 0.45)}`
                      },
                      '&:active': {
                        transform: 'scale(0.95)'
                      }
                    }}
                  >
                    <RefreshIcon />
                  </IconButton>
                </Tooltip>
              )}
            </Box>
          </Fade>
        )}
        
        {/* 实际图片 */}
        {isInView && !hasError && (
          <Fade in timeout={500}>
            <img
              ref={imgRef}
              src={src}
              alt={alt}
              onLoad={handleLoad}
              onError={handleError}
              loading="lazy"
              crossOrigin="anonymous"
              style={{
                width: '100%',
                height: '100%',
                objectFit,
                opacity: isLoaded ? 1 : 0,
                transition: 'opacity 0.7s cubic-bezier(0.4, 0, 0.2, 1), transform 0.3s ease',
              }}
            />
          </Fade>
        )}

        {/* 放大图标 */}
        {enableZoom && isLoaded && !isZoomed && (
          <Fade in timeout={300}>
            <Box
              sx={{
                position: 'absolute',
                bottom: 18,
                right: 18,
                opacity: 0,
                transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)',
                transform: 'translateY(14px)',
                '.lazy-image-container:hover &': {
                  opacity: 1,
                  transform: 'translateY(0)'
                }
              }}
            >
              <Tooltip title="点击放大图片" arrow>
                <IconButton
                  size="medium"
                  sx={{
                    backgroundColor: theme.palette.mode === 'dark'
                      ? alpha(theme.palette.common.black, 0.85)
                      : alpha(theme.palette.common.white, 0.98),
                    color: theme.palette.text.primary,
                    borderRadius: 2.5,
                    p: 1.5,
                    boxShadow: theme.palette.mode === 'dark'
                      ? `0 6px 28px ${alpha(theme.palette.common.black, 0.65)}`
                      : `0 6px 28px ${alpha(theme.palette.common.black, 0.25)}`,
                    transition: 'all 0.35s cubic-bezier(0.4, 0, 0.2, 1)',
                    '&:hover': {
                      backgroundColor: theme.palette.primary.main,
                      color: theme.palette.primary.contrastText,
                      transform: 'scale(1.18)',
                      boxShadow: `0 10px 32px ${alpha(theme.palette.primary.main, 0.55)}`
                    },
                    '&:active': {
                      transform: 'scale(0.95)'
                    }
                  }}
                >
                  <ZoomInIcon fontSize="small" />
                </IconButton>
              </Tooltip>
            </Box>
          </Fade>
        )}
      </Box>

      {/* 图片放大模态框 */}
      {enableZoom && isZoomed && (
        <Fade in timeout={300}>
          <Box
            sx={{
              position: 'fixed',
              top: 0,
              left: 0,
              width: '100vw',
              height: '100vh',
              backgroundColor: 'rgba(0, 0, 0, 0.98)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 9999,
              cursor: 'zoom-out',
              p: 4,
              backdropFilter: 'blur(12px)',
              transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)'
            }}
            onClick={handleZoomToggle}
            onKeyDown={handleKeyDown}
            tabIndex={0}
            role="button"
            aria-label="点击关闭放大图片"
          >
            <Zoom in timeout={400}>
              <Box
                component="img"
                src={src}
                alt={alt}
                loading="eager"
                crossOrigin="anonymous"
                sx={{
                  maxWidth: '95%',
                  maxHeight: '95%',
                  objectFit: 'contain',
                  borderRadius: 3,
                  boxShadow: `0 28px 96px ${alpha(theme.palette.common.black, 0.75)}`,
                  transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)',
                  '&:hover': {
                    transform: 'scale(1.025)',
                    boxShadow: `0 36px 112px ${alpha(theme.palette.common.black, 0.85)}`
                  }
                }}
              />
            </Zoom>
            <Tooltip title="关闭 (ESC)" arrow placement="top">
              <IconButton
                sx={{
                  position: 'absolute',
                  top: 32,
                  right: 32,
                  width: 56,
                  height: 56,
                  color: 'white',
                  backgroundColor: alpha(theme.palette.common.black, 0.75),
                  borderRadius: 2.5,
                  transition: 'all 0.35s cubic-bezier(0.4, 0, 0.2, 1)',
                  '&:hover': {
                    backgroundColor: alpha(theme.palette.error.main, 0.98),
                    transform: 'rotate(90deg) scale(1.18)',
                    boxShadow: `0 8px 32px ${alpha(theme.palette.error.main, 0.65)}`
                  },
                  '&:active': {
                    transform: 'rotate(90deg) scale(0.95)'
                  }
                }}
              >
                <RefreshIcon sx={{ fontSize: 32 }} />
              </IconButton>
            </Tooltip>
          </Box>
        </Fade>
      )}
    </>
  );
};

export default LazyImage;