/**
 * 配置管理服务
 * 负责管理应用配置，包括媒体文件路径、UI设置等
 */
export class ConfigService {
  private static instance: ConfigService
  private config: AppConfig

  private constructor() {
    // 默认配置
    this.config = {
      media: {
        basePath: '/media',
        paths: {
          images: '/media/images',
          videos: '/media/videos',
          audios: '/media/audios'
        },
        supportedFileTypes: {
          images: ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.svg'],
          videos: ['.mp4', '.avi', '.mov', '.wmv', '.flv', '.webm', '.mkv'],
          audios: ['.mp3', '.wav', '.flac', '.aac', '.ogg', '.wma']
        },
        maxFileSize: {
          images: 10 * 1024 * 1024, // 10MB
          videos: 500 * 1024 * 1024, // 500MB
          audios: 50 * 1024 * 1024 // 50MB
        }
      },
      ui: {
        itemsPerPage: 20,
        thumbnailSize: {
          width: 200,
          height: 150
        },
        previewSize: {
          width: 800,
          height: 600
        }
      },
      scanning: {
        interval: 60000, // 60秒
        autoStart: true
      }
    }
    
    // 尝试从localStorage加载配置
    this.loadConfigFromStorage()
  }

  static getInstance(): ConfigService {
    if (!ConfigService.instance) {
      ConfigService.instance = new ConfigService()
    }
    return ConfigService.instance
  }

  /**
   * 获取完整配置
   */
  getConfig(): AppConfig {
    return { ...this.config }
  }

  /**
   * 获取媒体配置
   */
  getMediaConfig(): MediaConfig {
    return { ...this.config.media }
  }

  /**
   * 获取UI配置
   */
  getUIConfig(): UIConfig {
    return { ...this.config.ui }
  }

  /**
   * 获取扫描配置
   */
  getScanningConfig(): ScanningConfig {
    return { ...this.config.scanning }
  }

  /**
   * 更新媒体配置
   */
  updateMediaConfig(mediaConfig: Partial<MediaConfig>): void {
    this.config.media = { ...this.config.media, ...mediaConfig }
    this.saveConfigToStorage()
  }

  /**
   * 更新UI配置
   */
  updateUIConfig(uiConfig: Partial<UIConfig>): void {
    this.config.ui = { ...this.config.ui, ...uiConfig }
    this.saveConfigToStorage()
  }

  /**
   * 更新扫描配置
   */
  updateScanningConfig(scanningConfig: Partial<ScanningConfig>): void {
    this.config.scanning = { ...this.config.scanning, ...scanningConfig }
    this.saveConfigToStorage()
  }

  /**
   * 获取媒体文件URL
   * @param fileType 文件类型
   * @param fileName 文件名
   * @returns 文件URL
   */
  getMediaFileUrl(fileType: 'images' | 'videos' | 'audios', fileName: string): string {
    const path = this.config.media.paths[fileType]
    return `${path}/${fileName}`
  }

  /**
   * 获取媒体文件绝对路径
   * @param fileType 文件类型
   * @param fileName 文件名
   * @returns 文件绝对路径
   */
  getMediaFilePath(fileType: 'images' | 'videos' | 'audios', fileName: string): string {
    const baseUrl = window.location.origin
    const path = this.config.media.paths[fileType]
    return `${baseUrl}${path}/${fileName}`
  }

  /**
   * 获取媒体文件目录路径
   * @param fileType 文件类型
   * @returns 目录路径
   */
  getMediaDirectoryPath(fileType: 'images' | 'videos' | 'audios'): string {
    return this.config.media.paths[fileType]
  }

  /**
   * 设置媒体文件路径
   * @param fileType 文件类型
   * @param path 路径
   */
  setMediaPath(fileType: 'images' | 'videos' | 'audios', path: string): void {
    this.config.media.paths[fileType] = path
    this.saveConfigToStorage()
  }

  /**
   * 批量设置媒体文件路径
   * @param paths 路径对象
   */
  setMediaPaths(paths: Partial<{ images: string; videos: string; audios: string }>): void {
    this.config.media.paths = { ...this.config.media.paths, ...paths }
    this.saveConfigToStorage()
  }

  /**
   * 重置配置为默认值
   */
  resetToDefaults(): void {
    this.config = {
      media: {
        basePath: '/media',
        paths: {
          images: '/media/images',
          videos: '/media/videos',
          audios: '/media/audios'
        },
        supportedFileTypes: {
          images: ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp', '.svg'],
          videos: ['.mp4', '.avi', '.mov', '.wmv', '.flv', '.webm', '.mkv'],
          audios: ['.mp3', '.wav', '.flac', '.aac', '.ogg', '.wma']
        },
        maxFileSize: {
          images: 10 * 1024 * 1024, // 10MB
          videos: 500 * 1024 * 1024, // 500MB
          audios: 50 * 1024 * 1024 // 50MB
        }
      },
      ui: {
        itemsPerPage: 20,
        thumbnailSize: {
          width: 200,
          height: 150
        },
        previewSize: {
          width: 800,
          height: 600
        }
      },
      scanning: {
        interval: 60000, // 60秒
        autoStart: true
      }
    }
    
    this.saveConfigToStorage()
  }

  /**
   * 从localStorage加载配置
   */
  private loadConfigFromStorage(): void {
    try {
      const storedConfig = localStorage.getItem('entertainment-app-config')
      if (storedConfig) {
        const parsedConfig = JSON.parse(storedConfig)
        this.config = { ...this.config, ...parsedConfig }
      }
    } catch (error) {
      console.error('加载配置失败:', error)
    }
  }

  /**
   * 保存配置到localStorage
   */
  private saveConfigToStorage(): void {
    try {
      localStorage.setItem('entertainment-app-config', JSON.stringify(this.config))
    } catch (error) {
      console.error('保存配置失败:', error)
    }
  }
}

// 配置接口定义
export interface AppConfig {
  media: MediaConfig
  ui: UIConfig
  scanning: ScanningConfig
}

export interface MediaConfig {
  basePath: string
  paths: {
    images: string
    videos: string
    audios: string
  }
  supportedFileTypes: {
    images: string[]
    videos: string[]
    audios: string[]
  }
  maxFileSize: {
    images: number
    videos: number
    audios: number
  }
}

export interface UIConfig {
  itemsPerPage: number
  thumbnailSize: {
    width: number
    height: number
  }
  previewSize: {
    width: number
    height: number
  }
}

export interface ScanningConfig {
  interval: number
  autoStart: boolean
}

// 导出单例实例
export default ConfigService.getInstance()