import React, { useState, useEffect } from 'react';
import {
  Box,
  Card,
  CardContent,
  Typography,
  Button,
  Grid,
  CircularProgress,
  Chip,
  useTheme,
  useMediaQuery,
  alpha,
  Fade,
  Skeleton,
  Backdrop
} from '@mui/material';
import {
  ArrowBack as PreviousIcon,
  ArrowForward as NextIcon,
  Article as ArticleIcon,
  Schedule as ScheduleIcon
} from '@mui/icons-material';
import { useNavigate, useLocation } from 'react-router-dom';
import { BlogPostWithId } from '../../types/blog';

interface AdjacentPostsNavigationProps {
  previousPost: BlogPostWithId | null;
  nextPost: BlogPostWithId | null;
}

const AdjacentPostsNavigation: React.FC<AdjacentPostsNavigationProps> = ({ previousPost, nextPost }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const isSmallMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const navigate = useNavigate();
  const location = useLocation();
  const [isTransitioning, setIsTransitioning] = useState(false);
  const [currentPath, setCurrentPath] = useState(location.pathname);
  const loading = false; // 不再需要加载状态，因为数据已经传入
  const error = null; // 不再需要错误状态

  // 监听路由变化，当路由变化且不是第一次加载时，表示文章切换完成
  useEffect(() => {
    if (location.pathname !== currentPath && isTransitioning) {
      // 延迟一点时间再关闭加载状态，确保新文章内容已经渲染
      const timer = setTimeout(() => {
        // 恢复透明度
        document.body.style.opacity = '1';
        
        setIsTransitioning(false);
      }, 300);
      
      setCurrentPath(location.pathname);
      
      return () => clearTimeout(timer);
    }
  }, [location.pathname, currentPath, isTransitioning]);

  // 添加一个额外的监听器，确保在文章加载完成后关闭加载状态
  useEffect(() => {
    // 如果当前处于切换状态，检查页面是否已经加载完成
    if (isTransitioning) {
      // 设置一个超时，确保加载状态不会一直显示
      const safetyTimer = setTimeout(() => {
        if (isTransitioning) {
          document.body.style.opacity = '1';
          setIsTransitioning(false);
        }
      }, 2000); // 2秒后强制关闭加载状态，防止卡住
      
      return () => clearTimeout(safetyTimer);
    }
  }, [isTransitioning]);

  const handleNavigate = (slug: string) => {
    if (!slug || isTransitioning) return;
    
    setIsTransitioning(true);
    
    // 添加平滑过渡效果
    document.body.style.transition = 'opacity 0.3s ease-in-out';
    document.body.style.opacity = '0.7';
    
    // 执行导航
    navigate(`/blog/${slug}`);
    
    // 注意：不再在这里设置恢复透明度和滚动到顶部的逻辑
    // 这些操作将在路由变化完成后，在useEffect中处理
  };

  const PostCard = ({ post, direction }: { post: BlogPostWithId | null; direction: 'previous' | 'next' }) => {
    const isDisabled = !post;
    const isPrevious = direction === 'previous';
    
    return (
      <Card
        sx={{
          height: '100%',
          display: 'flex',
          flexDirection: 'column',
          opacity: isDisabled ? 0.5 : 1,
          transition: 'all 0.7s cubic-bezier(0.4, 0, 0.2, 1)',
          cursor: isDisabled ? 'not-allowed' : 'pointer',
          borderRadius: '32px',
          border: `1.5px solid ${theme.palette.mode === 'dark' 
            ? alpha(theme.palette.primary.main, 0.36)
            : alpha(theme.palette.primary.main, 0.28)}`,
          backgroundColor: theme.palette.mode === 'dark'
            ? alpha(theme.palette.grey[900], 0.75)
            : alpha('#ffffff', 0.98),
          boxShadow: theme.palette.mode === 'dark'
            ? '0 10px 36px rgba(0, 0, 0, 0.5)'
            : '0 10px 32px rgba(0, 0, 0, 0.16)',
          '&:hover': !isDisabled ? {
            transform: 'translateY(-24px)',
            boxShadow: theme.palette.mode === 'dark'
              ? '0 24px 72px rgba(0, 0, 0, 0.65), 0 0 0 3.5px rgba(102, 126, 234, 0.5)'
              : '0 28px 72px rgba(0, 0, 0, 0.22), 0 0 0 3.5px rgba(102, 126, 234, 0.4)',
            borderColor: '#667eea',
          } : {},
        }}
      >
        <CardContent sx={{ 
          flex: 1, 
          display: 'flex', 
          flexDirection: 'column',
          p: 4.5,
          pb: 5,
          pt: 5
        }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 3.5 }}>
            {isPrevious ? (
              <PreviousIcon sx={{ mr: 1.5, color: 'primary.main', fontSize: isSmallMobile ? 24 : 32 }} />
            ) : (
              <NextIcon sx={{ ml: 1.5, color: 'primary.main', fontSize: isSmallMobile ? 24 : 32 }} />
            )}
            <Typography 
              variant={isSmallMobile ? "subtitle1" : "h6"} 
              component="div" 
              sx={{ fontWeight: 800 }}
            >
              {isPrevious ? '上一篇' : '下一篇'}
            </Typography>
          </Box>
          
          {post ? (
            <Fade in={true} timeout={500}>
              <Box>
                <Typography
                  variant="h6"
                  sx={{
                    fontWeight: 900,
                    mb: 3.5,
                    color: theme.palette.text.primary,
                    display: '-webkit-box',
                    WebkitLineClamp: isSmallMobile ? 2 : 3,
                    WebkitBoxOrient: 'vertical',
                    overflow: 'hidden',
                    lineHeight: 1.6,
                    minHeight: isSmallMobile ? '3em' : '4.5em',
                    fontSize: isSmallMobile ? '1.3rem' : '1.55rem',
                    transition: 'all 0.55s cubic-bezier(0.4, 0, 0.2, 1)',
                  }}
                >
                  {post.title}
                </Typography>
                
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 3.5 }}>
                  <ScheduleIcon sx={{ fontSize: isSmallMobile ? 20 : 24, mr: 2, color: 'text.secondary', transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)' }} />
                  <Typography variant="body2" color="text.secondary" fontSize={isSmallMobile ? '0.95rem' : '1.05rem'} fontWeight={700} sx={{ transition: 'all 0.45s cubic-bezier(0.4, 0, 0.2, 1)' }}>
                    {new Date(post.date).toLocaleDateString('zh-CN', {
                      year: 'numeric',
                      month: 'long',
                      day: 'numeric'
                    })}
                  </Typography>
                </Box>
                
                {post.category && (
                  <Chip
                    label={post.category}
                    size="small"
                    sx={{
                      mb: 4,
                      border: `1.5px solid ${theme.palette.mode === 'dark'
                        ? alpha(theme.palette.primary.main, 0.6)
                        : alpha(theme.palette.primary.main, 0.5)}`,
                      backgroundColor: theme.palette.mode === 'dark'
                        ? alpha(theme.palette.primary.main, 0.18)
                        : alpha(theme.palette.primary.main, 0.12),
                      color: theme.palette.mode === 'dark'
                        ? '#667eea'
                        : '#667eea',
                      fontWeight: 700,
                      fontSize: isSmallMobile ? '0.9rem' : '0.925rem',
                      height: isSmallMobile ? 34 : 40,
                      borderRadius: '22px',
                      px: 2,
                      transition: 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
                      '&:hover': {
                        transform: 'scale(1.22)',
                        backgroundColor: theme.palette.mode === 'dark'
                          ? alpha(theme.palette.primary.main, 0.24)
                          : alpha(theme.palette.primary.main, 0.18),
                        borderColor: '#667eea',
                        boxShadow: `0 12px 28px ${alpha(theme.palette.primary.main, 0.4)}`
                      }
                    }}
                  />
                )}
                
                <Button
                  variant={isPrevious ? "outlined" : "contained"}
                  fullWidth
                  startIcon={isTransitioning ? <CircularProgress size={18} color="inherit" /> : (isPrevious ? <PreviousIcon /> : undefined)}
                  endIcon={!isPrevious && !isTransitioning ? <NextIcon /> : undefined}
                  onClick={() => handleNavigate(post.slug)}
                  disabled={isTransitioning}
                  sx={{
                    mt: 'auto',
                    py: isSmallMobile ? 2 : 2.25,
                    fontWeight: 900,
                    transition: 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
                    fontSize: isSmallMobile ? '1rem' : '1.1rem',
                    borderRadius: '18px',
                    px: 4,
                    ...(isPrevious ? {
                      borderColor: theme.palette.mode === 'dark'
                        ? alpha(theme.palette.primary.main, 0.8)
                        : alpha(theme.palette.primary.main, 0.7),
                      color: theme.palette.mode === 'dark'
                        ? '#667eea'
                        : '#667eea',
                      '&:hover': {
                        transform: 'translateY(-10px)',
                        borderColor: '#667eea',
                        backgroundColor: theme.palette.mode === 'dark'
                          ? alpha(theme.palette.primary.main, 0.24)
                          : alpha(theme.palette.primary.main, 0.16),
                        boxShadow: `0 12px 28px ${alpha(theme.palette.primary.main, 0.45)}`
                      }
                    } : {
                      backgroundColor: theme.palette.mode === 'dark'
                        ? 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)'
                        : 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                      '&:hover': {
                        transform: 'translateY(-10px)',
                        boxShadow: `0 14px 36px ${alpha(theme.palette.primary.main, 0.65)}`,
                        backgroundColor: theme.palette.mode === 'dark'
                          ? 'linear-gradient(135deg, #764ba2 0%, #667eea 100%)'
                          : 'linear-gradient(135deg, #764ba2 0%, #667eea 100%)'
                      }
                    }),
                    '&:disabled': {
                      opacity: 0.5,
                      color: theme.palette.action.disabled,
                      backgroundColor: isPrevious ? 'transparent' : alpha(theme.palette.primary.main, 0.15),
                      borderColor: isPrevious ? alpha(theme.palette.primary.main, 0.15) : undefined,
                      transform: 'none',
                      boxShadow: 'none'
                    }
                  }}
                >
                  {isTransitioning ? '切换中...' : `阅读${isPrevious ? '上一篇' : '下一篇'}`}
                </Button>
              </Box>
            </Fade>
          ) : (
            <Box sx={{ textAlign: 'center', py: isSmallMobile ? 1.5 : 2 }}>
              <ArticleIcon sx={{ 
                fontSize: isSmallMobile ? 36 : 48, 
                color: 'text.disabled', 
                mb: 1 
              }} />
              <Typography 
                variant="body2" 
                color="text.disabled"
                fontSize={isSmallMobile ? '0.75rem' : '0.875rem'}
              >
                {isPrevious ? '已是第一篇文章' : '已是最后一篇文章'}
              </Typography>
            </Box>
          )}
        </CardContent>
      </Card>
    );
  };

  if (error) {
    return (
      <Box sx={{ mt: 4, textAlign: 'center' }}>
        <Typography color="error">加载相邻文章失败</Typography>
      </Box>
    );
  }

  return (
    <>
      {isTransitioning && (
        <Backdrop
          sx={{ 
            color: '#fff', 
            zIndex: (theme) => theme.zIndex.drawer + 1,
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center',
            alignItems: 'center',
            gap: 3.5,
            backgroundColor: theme.palette.mode === 'dark'
              ? 'rgba(0, 0, 0, 0.88)'
              : 'rgba(0, 0, 0, 0.75)',
            backdropFilter: 'blur(10px)'
          }}
          open={isTransitioning}
        >
          <CircularProgress 
            color="inherit" 
            size={52}
            thickness={3.75}
            sx={{
              '& .MuiCircularProgress-circle': {
                strokeLinecap: 'round'
              }
            }}
          />
          <Typography 
            variant="h6" 
            component="div"
            sx={{
              fontWeight: 700,
              letterSpacing: 0.5,
              textShadow: '0 2px 10px rgba(0, 0, 0, 0.35)',
              fontSize: '1.15rem'
            }}
          >
            正在切换文章...
          </Typography>
        </Backdrop>
      )}
      
      <Box sx={{ 
        mt: { xs: 4, sm: 5 }, 
        mb: { xs: 4, sm: 5 },
        px: { xs: 1.5, sm: 0 }
      }}>
        <Grid container spacing={isSmallMobile ? 2 : 3}>
          <Grid item xs={12} md={6}>
            <PostCard post={previousPost} direction="previous" />
          </Grid>
          <Grid item xs={12} md={6}>
            <PostCard post={nextPost} direction="next" />
          </Grid>
        </Grid>
      </Box>
    </>
  );
};

export default AdjacentPostsNavigation;