import React, { useState, useEffect, useRef } from 'react'
import { useNavigate, useParams, useLocation } from 'react-router-dom'
import { useDispatch, useSelector } from 'react-redux'
import { AppDispatch } from '../../../store'
import entertainmentPreloadService from '../../../services/entertainmentPreloadService'
import pageAutoPlayService from '../../../services/pageAutoPlayService'
import { 
  Box, 
  Container, 
  Typography, 
  Grid,
  Card, 
  CardMedia,
  CardContent,
  Chip,
  Button,
  TextField,
  InputAdornment,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  IconButton,
  Fab,
  Fade,
  Slide,
  Backdrop
} from '@mui/material'
import { styled } from '@mui/material/styles'
import SearchIcon from '@mui/icons-material/Search'
import PlayArrowIcon from '@mui/icons-material/PlayArrow'
import PauseIcon from '@mui/icons-material/Pause'
import VolumeUpIcon from '@mui/icons-material/VolumeUp'
import VolumeOffIcon from '@mui/icons-material/VolumeOff'
import FullscreenIcon from '@mui/icons-material/Fullscreen'
import VideoLibraryIcon from '@mui/icons-material/VideoLibrary'
import MusicNoteIcon from '@mui/icons-material/MusicNote'
import { 
  setTypeFilter, 
  setCategoryFilter, 
  setTagFilter, 
  setSearchQuery,
  selectFilteredMediaFiles,
  selectMediaFilesCategories,
  selectMediaFilesTags,
  selectMediaFilesLoading,
  selectMediaFilesError,
  clearError
} from '../../../store/slices/mediaFilesSlice'
import { MediaFile } from '../../../services/mediaFileService'
import { 
  StateWrapper, 
  Notification,
  LoadingState
} from '../../../components/common/StateHandlers'
import EntertainmentNavigation from '../../../components/Entertainment/EntertainmentNavigation'
import MediaPreviewDialog from '../../../components/Entertainment/MediaPreviewDialog'

// 样式化的组件
const VideoCard = styled(Card)(({ theme }) => ({
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  transition: 'transform 0.3s ease-in-out, box-shadow 0.3s ease-in-out',
  cursor: 'pointer',
  '&:hover': {
    transform: 'translateY(-8px)',
    boxShadow: theme.shadows[8],
  },
}))

const VideoThumbnail = styled(CardMedia)<{ fileType: 'video' | 'audio' }>(({ fileType }) => ({
  height: 180,
  position: 'relative',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  ...(fileType === 'video' && {
    '& img': {
      width: '100%',
      height: '100%',
      objectFit: 'cover',
    }
  }),
  ...(fileType === 'audio' && {
    background: 'linear-gradient(135deg, #4facfe 0%, #00f2fe 100%)',
    '& img': {
      display: 'none'
    }
  })
}))

const PlayOverlay = styled(Box)(() => ({
  position: 'absolute',
  top: 0,
  left: 0,
  width: '100%',
  height: '100%',
  backgroundColor: 'rgba(0, 0, 0, 0.3)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  opacity: 0,
  transition: 'opacity 0.3s ease-in-out',
  '&:hover': {
    opacity: 1,
  },
}))

const FilterSection = styled(Box)(({ theme }) => ({
  backgroundColor: theme.palette.grey[50],
  padding: theme.spacing(3),
  borderRadius: theme.spacing(2),
  marginBottom: theme.spacing(4),
}))

const VideoPlayerContainer = styled(Box)(({ theme }) => ({
  position: 'relative',
  width: '100%',
  backgroundColor: 'black',
  borderRadius: theme.spacing(1),
  overflow: 'hidden',
}))

const VideoPlayer = styled('video')({
  width: '100%',
  maxHeight: '500px',
  display: 'block',
})

const VideoControls = styled(Box)(({ theme }) => ({
  position: 'absolute',
  bottom: 0,
  left: 0,
  width: '100%',
  backgroundColor: 'rgba(0, 0, 0, 0.7)',
  padding: theme.spacing(1),
  display: 'flex',
  alignItems: 'center',
  gap: theme.spacing(1),
}))

const MediaLibrary: React.FC = () => {
  const navigate = useNavigate()
  const location = useLocation()
  const dispatch = useDispatch<AppDispatch>()
  const { category, fileId } = useParams<{ category?: string, fileId?: string }>()
  
  // 检查并使用预加载的数据
  useEffect(() => {
    // 如果没有预加载数据，则触发预加载
    if (!entertainmentPreloadService.hasPreloaded()) {
      entertainmentPreloadService.preloadAllEntertainmentData()
        .then(() => {
          console.log('媒体库数据预加载完成')
        })
        .catch(error => {
          console.error('媒体库数据预加载失败:', error)
        })
    }
    
    // 通知页面自动播放服务页面类型变化
    pageAutoPlayService.onPageChanged('media')
  }, [dispatch])
  
  // Redux状态
  const filteredFiles = useSelector(selectFilteredMediaFiles)
  const categories = useSelector(selectMediaFilesCategories)
  const tags = useSelector(selectMediaFilesTags)
  const loading = useSelector(selectMediaFilesLoading)
  const error = useSelector(selectMediaFilesError)
  
  // 本地状态
  const [searchTerm, setSearchTerm] = useState('')
  const [selectedCategory, setSelectedCategory] = useState(category || 'all')
  const [selectedTag, setSelectedTag] = useState('all')
  const [selectedVideo, setSelectedVideo] = useState<MediaFile | null>(null)
  const [previewDialogOpen, setPreviewDialogOpen] = useState(false)
  const [notificationOpen, setNotificationOpen] = useState(false)
  const [currentMediaIndex, setCurrentMediaIndex] = useState(0)

  // 过滤出视频和音频类型的文件
  const videoFiles = filteredFiles.filter(file => file.type === 'video' || file.type === 'audio')

  // 应用过滤器
  useEffect(() => {
    dispatch(setTypeFilter('video,audio'))
    dispatch(setCategoryFilter(selectedCategory))
    dispatch(setTagFilter(selectedTag))
    dispatch(setSearchQuery(searchTerm))
  }, [dispatch, selectedCategory, selectedTag, searchTerm])

  // 处理URL参数变化
  useEffect(() => {
    if (category) {
      setSelectedCategory(category)
    }
  }, [category])

  // 处理URL参数中的fileId，自动打开视频播放弹窗
  useEffect(() => {
    if (fileId && videoFiles.length > 0) {
      const targetFile = videoFiles.find(file => file.id === fileId)
      if (targetFile && (!selectedVideo || selectedVideo.id !== fileId)) {
        // 找到目标文件且当前没有打开或打开的不是目标文件
        handleVideoClick(targetFile)
      }
    }
  }, [fileId, videoFiles.length, selectedVideo])

  // 处理视频点击
  const handleVideoClick = (video: MediaFile) => {
    const index = videoFiles.findIndex(v => v.id === video.id)
    setCurrentMediaIndex(index)
    setSelectedVideo(video)
    setPreviewDialogOpen(true)
  }

  // 处理媒体索引变化
  const handleMediaIndexChange = (index: number) => {
    setCurrentMediaIndex(index)
    setSelectedVideo(videoFiles[index])
  }

  // 关闭预览对话框
  const handleClosePreviewDialog = () => {
    setPreviewDialogOpen(false)
    setSelectedVideo(null)
  }

  // 处理分类变化
  const handleCategoryChange = (event: any) => {
    const newCategory = event.target.value
    setSelectedCategory(newCategory)
    
    // 更新URL
    if (newCategory === 'all') {
      navigate('/entertainment/MediaLibrary')
    } else {
      navigate(`/entertainment/MediaLibrary/${newCategory}`)
    }
  }

  // 处理标签变化
  const handleTagChange = (event: any) => {
    setSelectedTag(event.target.value)
  }

  // 处理搜索
  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearchTerm(event.target.value)
  }

  // 播放/暂停视频
  const togglePlayPause = () => {
    if (videoRef.current) {
      if (isPlaying) {
        videoRef.current.pause()
      } else {
        videoRef.current.play()
      }
      setIsPlaying(!isPlaying)
    }
  }

  // 静音/取消静音
  const toggleMute = () => {
    if (videoRef.current) {
      videoRef.current.muted = !isMuted
      setIsMuted(!isMuted)
    }
  }

  // 处理时间更新
  const handleTimeUpdate = () => {
    if (videoRef.current) {
      setCurrentTime(videoRef.current.currentTime)
    }
  }

  // 处理视频加载
  const handleLoadedMetadata = () => {
    if (videoRef.current) {
      setDuration(videoRef.current.duration)
    }
  }

  // 处理滑块变化
  const handleSliderChange = (_event: Event, newValue: number | number[]) => {
    const time = Array.isArray(newValue) ? newValue[0] : newValue
    if (videoRef.current) {
      videoRef.current.currentTime = time
      setCurrentTime(time)
    }
  }

  // 关闭通知
  const handleCloseNotification = () => {
    setNotificationOpen(false)
    if (error) {
      dispatch(clearError())
    }
  }

  // 格式化文件大小
  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes'
    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  // 格式化日期
  const formatDate = (date: Date | number | string): string => {
    let dateObj: Date;
    if (typeof date === 'number') {
      dateObj = new Date(date);
    } else if (typeof date === 'string') {
      dateObj = new Date(date);
    } else {
      dateObj = date;
    }
    
    // 检查日期是否有效
    if (isNaN(dateObj.getTime())) {
      return '无效日期';
    }
    
    return dateObj.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  }

  // 格式化时间
  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60)
    const secs = Math.floor(seconds % 60)
    return `${mins}:${secs.toString().padStart(2, '0')}`
  }

  return (
    <Container maxWidth="lg">
      <EntertainmentNavigation
        title="媒体库"
        subtitle="收藏喜欢的视频和影视作品，记录观影心得和推荐"
        showBackButton={true}
      >
        <Box>
      {/* 过滤器区域 */}
      <FilterSection>
        <Grid container spacing={3} alignItems="center">
            {/* 搜索框 */}
            <Grid size={{ xs: 12, md: 4 }}>
            <TextField
              fullWidth
              placeholder="搜索视频..."
              value={searchTerm}
              onChange={handleSearchChange}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchIcon />
                  </InputAdornment>
                ),
              }}
            />
          </Grid>

          {/* 分类过滤器 */}
          <Grid size={{ xs: 12, md: 4 }}>
            <FormControl fullWidth>
              <InputLabel id="category-filter-label">分类</InputLabel>
              <Select
                labelId="category-filter-label"
                value={selectedCategory}
                label="分类"
                onChange={handleCategoryChange}
              >
                <MenuItem value="all">所有分类</MenuItem>
                {categories.map((cat) => (
                  <MenuItem key={cat} value={cat}>
                    {cat}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>

          {/* 标签过滤器 */}
          <Grid size={{ xs: 12, md: 4 }}>
            <FormControl fullWidth>
              <InputLabel id="tag-filter-label">标签</InputLabel>
              <Select
                labelId="tag-filter-label"
                value={selectedTag}
                label="标签"
                onChange={handleTagChange}
              >
                <MenuItem value="all">所有标签</MenuItem>
                {tags.map((tag) => (
                  <MenuItem key={tag} value={tag}>
                    {tag}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
        </Grid>
      </FilterSection>

      {/* 视频网格 */}
      <StateWrapper
        loading={false}
        error={error}
        empty={videoFiles.length === 0}
        emptyIcon={<VideoLibraryIcon />}
        emptyTitle="没有找到视频或音频"
        emptyDescription="尝试调整过滤器或上传一些视频或音频"
        emptyAction={{
          label: '返回休闲娱乐',
          onClick: () => navigate('/entertainment')
        }}
        errorTitle="加载视频时出错"
        retryAction={{
          label: '重试',
          onClick: () => window.location.reload()
        }}
      >
        <Grid container spacing={3}>
            {videoFiles.map((video) => (
              <Grid size={{ xs: 12, sm: 6, md: 4, lg: 3 }} key={video.id}>
              <VideoCard onClick={() => handleVideoClick(video)}>
                <VideoThumbnail fileType={video.type}>
                  {video.type === 'video' ? (
                    <Box
                      component="img"
                      src={video.thumbnail || 'https://via.placeholder.com/320x180?text=Video'}
                      alt={video.name}
                    />
                  ) : (
                    <MusicNoteIcon sx={{ fontSize: 60, color: 'white' }} />
                  )}
                  {video.type === 'video' && (
                    <PlayOverlay>
                      <PlayArrowIcon sx={{ fontSize: 48, color: 'white' }} />
                    </PlayOverlay>
                  )}
                </VideoThumbnail>
                <CardContent>
                  <Typography variant="h6" component="h3" noWrap gutterBottom>
                    {video.name}
                  </Typography>
                  <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                    <Typography variant="body2" color="text.secondary">
                      {formatFileSize(video.size)}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      {video.type === 'video' 
                        ? (video.duration ? formatTime(video.duration) : '--:--')
                        : '音频'
                      }
                    </Typography>
                  </Box>
                  <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                    {video.tags.map((tag) => (
                      <Chip key={tag} label={tag} size="small" variant="outlined" />
                    ))}
                  </Box>
                </CardContent>
              </VideoCard>
            </Grid>
          ))}
        </Grid>
      </StateWrapper>

      {/* 媒体预览对话框 */}
      <MediaPreviewDialog
        open={previewDialogOpen}
        onClose={handleClosePreviewDialog}
        media={selectedVideo}
        mediaList={videoFiles}
        currentIndex={currentMediaIndex}
        onIndexChange={handleMediaIndexChange}
        formatFileSize={formatFileSize}
        formatDate={formatDate}
      />

      {/* 错误通知 */}
      <Notification
        open={!!error || notificationOpen}
        message={error || '操作失败'}
        severity="error"
        onClose={handleCloseNotification}
      />

    </Box>
  </EntertainmentNavigation>
</Container>
  )
}

export default MediaLibrary