/**
 * 统一数据加载与缓存架构
 * 为博客模块和娱乐模块提供高效的数据加载和缓存服务
 */

import { BlogPostWithId } from '../../types';
import { MediaFileWithId } from './api';

// 缓存项接口
export interface CacheItem<T> {
  data: T;
  timestamp: number;
  ttl: number; // 生存时间(毫秒)
  lastAccessed: number;
  hitCount: number;
}

// 缓存配置接口
export interface CacheConfig {
  maxSize: number; // 最大缓存项数
  defaultTtl: number; // 默认TTL(毫秒)
  cleanupInterval: number; // 清理间隔(毫秒)
  enableMetrics: boolean; // 是否启用指标收集
}

// 缓存指标接口
export interface CacheMetrics {
  hits: number;
  misses: number;
  evictions: number;
  totalRequests: number;
  hitRate: number;
  memoryUsage: number;
  oldestItem: number;
  newestItem: number;
}

// 数据加载器接口
export interface DataLoader<T> {
  load(): Promise<T>;
  identifier: string;
  dependencies?: string[]; // 依赖的其他数据标识符
}

// 数据类型枚举
export enum DataType {
  BLOG_POSTS = 'blog_posts',
  BLOG_POST = 'blog_post',
  BLOG_STATS = 'blog_stats',
  MEDIA_FILES = 'media_files',
  MEDIA_FILE = 'media_file',
  MEDIA_STATS = 'media_stats'
}

// 缓存键生成策略
export class CacheKeyStrategy {
  static generateKey(type: DataType, params: Record<string, any> = {}): string {
    const paramString = Object.keys(params)
      .sort()
      .map(key => `${key}:${params[key]}`)
      .join('|');
    
    return paramString ? `${type}:${paramString}` : type;
  }
  
  static extractType(key: string): DataType {
    return key.split(':')[0] as DataType;
  }
  
  static extractParams(key: string): Record<string, string> {
    const parts = key.split(':');
    if (parts.length <= 1) return {};
    
    const params: Record<string, string> = {};
    for (let i = 1; i < parts.length; i++) {
      const [key, value] = parts[i].split('=');
      if (key && value) {
        params[key] = value;
      }
    }
    
    return params;
  }
}

// 缓存策略接口
export interface CacheStrategy {
  shouldEvict(item: CacheItem<any>, cache: Map<string, CacheItem<any>>): boolean;
  onEvict?(key: string, item: CacheItem<any>): void;
}

// LRU缓存策略
export class LRUStrategy implements CacheStrategy {
  shouldEvict(item: CacheItem<any>, cache: Map<string, CacheItem<any>>): boolean {
    // 找出最久未访问的项
    let oldestKey = '';
    let oldestTime = Date.now();
    
    for (const [key, cacheItem] of cache.entries()) {
      if (cacheItem.lastAccessed < oldestTime) {
        oldestTime = cacheItem.lastAccessed;
        oldestKey = key;
      }
    }
    
    return oldestKey !== '';
  }
  
  onEvict(key: string, item: CacheItem<any>): void {
    console.log(`LRU策略驱逐缓存项: ${key}, 最后访问: ${new Date(item.lastAccessed).toISOString()}`);
  }
}

// TTL缓存策略
export class TTLStrategy implements CacheStrategy {
  shouldEvict(item: CacheItem<any>): boolean {
    return Date.now() - item.timestamp > item.ttl;
  }
  
  onEvict(key: string, item: CacheItem<any>): void {
    console.log(`TTL策略驱逐缓存项: ${key}, 创建时间: ${new Date(item.timestamp).toISOString()}, TTL: ${item.ttl}ms`);
  }
}

// 复合缓存策略
export class CompositeStrategy implements CacheStrategy {
  constructor(private strategies: CacheStrategy[]) {}
  
  shouldEvict(item: CacheItem<any>, cache: Map<string, CacheItem<any>>): boolean {
    return this.strategies.some(strategy => strategy.shouldEvict(item, cache));
  }
  
  onEvict(key: string, item: CacheItem<any>): void {
    this.strategies.forEach(strategy => {
      if (strategy.onEvict) {
        strategy.onEvict(key, item);
      }
    });
  }
}

// 核心缓存管理器
export class CacheManager {
  private cache = new Map<string, CacheItem<any>>();
  private metrics: CacheMetrics = {
    hits: 0,
    misses: 0,
    evictions: 0,
    totalRequests: 0,
    hitRate: 0,
    memoryUsage: 0,
    oldestItem: 0,
    newestItem: 0
  };
  
  private cleanupTimer?: Timer;
  
  constructor(
    private config: CacheConfig,
    private strategy: CacheStrategy = new CompositeStrategy([new TTLStrategy(), new LRUStrategy()])
  ) {
    this.startCleanupTimer();
  }
  
  /**
   * 获取缓存项
   */
  async get<T>(key: string): Promise<T | null> {
    this.metrics.totalRequests++;
    
    const item = this.cache.get(key);
    
    if (!item) {
      this.metrics.misses++;
      this.updateHitRate();
      return null;
    }
    
    // 检查是否过期
    if (Date.now() - item.timestamp > item.ttl) {
      this.cache.delete(key);
      this.metrics.misses++;
      this.updateHitRate();
      return null;
    }
    
    // 更新访问信息
    item.lastAccessed = Date.now();
    item.hitCount++;
    
    this.metrics.hits++;
    this.updateHitRate();
    
    return item.data as T;
  }
  
  /**
   * 设置缓存项
   */
  set<T>(key: string, data: T, ttl?: number): void {
    const item: CacheItem<T> = {
      data,
      timestamp: Date.now(),
      ttl: ttl || this.config.defaultTtl,
      lastAccessed: Date.now(),
      hitCount: 0
    };
    
    // 如果缓存已满，执行驱逐策略
    if (this.cache.size >= this.config.maxSize) {
      this.evict();
    }
    
    this.cache.set(key, item);
    this.updateMetrics();
  }
  
  /**
   * 删除缓存项
   */
  delete(key: string): boolean {
    return this.cache.delete(key);
  }
  
  /**
   * 清空缓存
   */
  clear(): void {
    this.cache.clear();
    this.resetMetrics();
  }
  
  /**
   * 检查缓存项是否存在且未过期
   */
  has(key: string): boolean {
    const item = this.cache.get(key);
    if (!item) return false;
    
    // 检查是否过期
    if (Date.now() - item.timestamp > item.ttl) {
      this.cache.delete(key);
      return false;
    }
    
    return true;
  }
  
  /**
   * 获取缓存大小
   */
  size(): number {
    return this.cache.size;
  }
  
  /**
   * 获取缓存指标
   */
  getMetrics(): CacheMetrics {
    this.updateMetrics();
    return { ...this.metrics };
  }
  
  /**
   * 执行驱逐策略
   */
  private evict(): void {
    let evicted = false;
    
    for (const [key, item] of this.cache.entries()) {
      if (this.strategy.shouldEvict(item, this.cache)) {
        this.cache.delete(key);
        this.metrics.evictions++;
        
        if (this.strategy.onEvict) {
          this.strategy.onEvict(key, item);
        }
        
        evicted = true;
        break;
      }
    }
    
    // 如果没有找到可驱逐的项，删除最旧的项
    if (!evicted && this.cache.size > 0) {
      let oldestKey = '';
      let oldestTime = Date.now();
      
      for (const [key, item] of this.cache.entries()) {
        if (item.timestamp < oldestTime) {
          oldestTime = item.timestamp;
          oldestKey = key;
        }
      }
      
      if (oldestKey) {
        this.cache.delete(oldestKey);
        this.metrics.evictions++;
        
        if (this.strategy.onEvict) {
          this.strategy.onEvict(oldestKey, this.cache.get(oldestKey)!);
        }
      }
    }
  }
  
  /**
   * 启动清理定时器
   */
  private startCleanupTimer(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
    }
    
    this.cleanupTimer = setInterval(() => {
      this.cleanup();
    }, this.config.cleanupInterval);
  }
  
  /**
   * 清理过期项
   */
  private cleanup(): void {
    const now = Date.now();
    const keysToDelete: string[] = [];
    
    for (const [key, item] of this.cache.entries()) {
      if (now - item.timestamp > item.ttl) {
        keysToDelete.push(key);
      }
    }
    
    keysToDelete.forEach(key => {
      const item = this.cache.get(key)!;
      this.cache.delete(key);
      this.metrics.evictions++;
      
      if (this.strategy.onEvict) {
        this.strategy.onEvict(key, item);
      }
    });
  }
  
  /**
   * 更新命中率
   */
  private updateHitRate(): void {
    this.metrics.hitRate = this.metrics.totalRequests > 0 
      ? this.metrics.hits / this.metrics.totalRequests 
      : 0;
  }
  
  /**
   * 更新指标
   */
  private updateMetrics(): void {
    if (!this.config.enableMetrics) return;
    
    let oldestTime = Date.now();
    let newestTime = 0;
    let memoryUsage = 0;
    
    for (const item of this.cache.values()) {
      if (item.timestamp < oldestTime) {
        oldestTime = item.timestamp;
      }
      
      if (item.timestamp > newestTime) {
        newestTime = item.timestamp;
      }
      
      // 简单估算内存使用（实际应用中可以使用更精确的方法）
      memoryUsage += JSON.stringify(item.data).length;
    }
    
    this.metrics.oldestItem = oldestTime;
    this.metrics.newestItem = newestTime;
    this.metrics.memoryUsage = memoryUsage;
  }
  
  /**
   * 重置指标
   */
  private resetMetrics(): void {
    this.metrics = {
      hits: 0,
      misses: 0,
      evictions: 0,
      totalRequests: 0,
      hitRate: 0,
      memoryUsage: 0,
      oldestItem: 0,
      newestItem: 0
    };
  }
  
  /**
   * 销毁缓存管理器
   */
  destroy(): void {
    if (this.cleanupTimer) {
      clearInterval(this.cleanupTimer);
      this.cleanupTimer = null;
    }
    
    this.clear();
  }
}

// 统一数据加载服务
export class UnifiedDataService {
  private static instance: UnifiedDataService;
  private cacheManager: CacheManager;
  private dataLoaders = new Map<string, DataLoader<any>>();
  private loadingPromises = new Map<string, Promise<any>>();
  
  private constructor() {
    // 默认缓存配置
    const cacheConfig: CacheConfig = {
      maxSize: 100,
      defaultTtl: 5 * 60 * 1000, // 5分钟
      cleanupInterval: 60 * 1000, // 1分钟
      enableMetrics: true
    };
    
    // 使用复合策略：先检查TTL，再使用LRU
    const strategy = new CompositeStrategy([new TTLStrategy(), new LRUStrategy()]);
    
    this.cacheManager = new CacheManager(cacheConfig, strategy);
  }
  
  static getInstance(): UnifiedDataService {
    if (!UnifiedDataService.instance) {
      UnifiedDataService.instance = new UnifiedDataService();
    }
    return UnifiedDataService.instance;
  }
  
  /**
   * 注册数据加载器
   */
  registerDataLoader<T>(loader: DataLoader<T>): void {
    this.dataLoaders.set(loader.identifier, loader);
  }
  
  /**
   * 获取数据（带缓存）
   */
  async getData<T>(key: string, loader?: DataLoader<T>): Promise<T> {
    // 尝试从缓存获取
    const cachedData = await this.cacheManager.get<T>(key);
    if (cachedData !== null) {
      return cachedData;
    }
    
    // 检查是否已在加载中
    if (this.loadingPromises.has(key)) {
      return this.loadingPromises.get(key);
    }
    
    // 确定使用哪个加载器
    const dataLoader = loader || this.dataLoaders.get(key);
    if (!dataLoader) {
      throw new Error(`No data loader found for key: ${key}`);
    }
    
    // 创建加载Promise
    const loadingPromise = this.loadDataWithCache(key, dataLoader);
    this.loadingPromises.set(key, loadingPromise);
    
    try {
      const data = await loadingPromise;
      return data;
    } finally {
      this.loadingPromises.delete(key);
    }
  }
  
  /**
   * 预加载数据
   */
  async preloadData(keys: string[]): Promise<void> {
    const promises = keys.map(key => {
      const loader = this.dataLoaders.get(key);
      if (!loader) return Promise.resolve();
      
      return this.getData(key, loader);
    });
    
    await Promise.all(promises);
  }
  
  /**
   * 刷新缓存
   */
  async refreshData<T>(key: string): Promise<T> {
    // 删除现有缓存
    this.cacheManager.delete(key);
    
    // 重新加载数据
    const loader = this.dataLoaders.get(key);
    if (!loader) {
      throw new Error(`No data loader found for key: ${key}`);
    }
    
    return this.getData(key, loader);
  }
  
  /**
   * 根据依赖刷新缓存
   */
  async refreshDataByDependency(dependency: string): Promise<void> {
    const keysToRefresh: string[] = [];
    
    for (const [key, loader] of this.dataLoaders.entries()) {
      if (loader.dependencies && loader.dependencies.includes(dependency)) {
        keysToRefresh.push(key);
      }
    }
    
    const refreshPromises = keysToRefresh.map(key => this.refreshData(key));
    await Promise.all(refreshPromises);
  }
  
  /**
   * 清空所有缓存
   */
  clearAllCache(): void {
    this.cacheManager.clear();
  }
  
  /**
   * 获取缓存指标
   */
  getCacheStats(): CacheMetrics {
    return this.cacheManager.getMetrics();
  }
  
  /**
   * 加载数据并缓存
   */
  private async loadDataWithCache<T>(key: string, loader: DataLoader<T>): Promise<T> {
    try {
      const data = await loader.load();
      
      // 根据数据类型设置不同的TTL
      let ttl: number;
      const dataType = CacheKeyStrategy.extractType(key);
      
      switch (dataType) {
        case DataType.BLOG_POSTS:
          ttl = 10 * 60 * 1000; // 10分钟
          break;
        case DataType.BLOG_POST:
          ttl = 30 * 60 * 1000; // 30分钟
          break;
        case DataType.MEDIA_FILES:
          ttl = 15 * 60 * 1000; // 15分钟
          break;
        case DataType.MEDIA_FILE:
          ttl = 60 * 60 * 1000; // 1小时
          break;
        case DataType.MEDIA_STATS:
          ttl = 5 * 60 * 1000; // 5分钟
          break;
        default:
          ttl = 5 * 60 * 1000; // 默认5分钟
      }
      
      this.cacheManager.set(key, data, ttl);
      return data;
    } catch (error) {
      console.error(`Failed to load data for key ${key}:`, error);
      throw error;
    }
  }
}

