import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { 
  Card, 
  CardContent, 
  CardActions, 
  Typography, 
  Chip, 
  Avatar, 
  Box, 
  Button,
  CardMedia,
  IconButton,
  Tooltip,
  Zoom,
  Grow,
  Skeleton,
  useTheme,
  alpha
} from '@mui/material';
import { 
  CalendarToday, 
  Visibility, 
  ThumbUp, 
  Comment,
  BookmarkBorder,
  Bookmark,
  Share,
  MoreVert
} from '@mui/icons-material';
import { BlogPostListItem } from '../../types/blog';
import LazyImage from './LazyImage';

interface ArticleCardProps {
  post: BlogPostListItem;
  featured?: boolean;
}

const ArticleCard: React.FC<ArticleCardProps> = ({ post, featured = false }) => {
  const [isBookmarked, setIsBookmarked] = useState(false);
  const [isHovered, setIsHovered] = useState(false);
  const [imageLoaded, setImageLoaded] = useState(false);
  const theme = useTheme();

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    return date.toLocaleDateString('zh-CN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric'
    });
  };

  // 收藏功能已禁用
  // const handleBookmarkToggle = (e: React.MouseEvent) => {
  //   e.preventDefault();
  //   e.stopPropagation();
  //   setIsBookmarked(!isBookmarked);
  // };

  const handleShare = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (navigator.share) {
      navigator.share({
        title: post.title,
        text: post.excerpt,
        url: window.location.origin + `/blog/${post.slug}`
      });
    } else {
      navigator.clipboard.writeText(window.location.origin + `/blog/${post.slug}`);
    }
  };

  return (
    <Zoom in timeout={500}>
      <Card 
        sx={{ 
          height: '100%', 
          display: 'flex', 
          flexDirection: 'column',
          position: 'relative',
          transition: 'all 0.7s cubic-bezier(0.4, 0, 0.2, 1)',
          transform: isHovered ? 'translateY(-28px)' : 'translateY(0)',
          boxShadow: isHovered 
            ? theme.palette.mode === 'dark'
              ? `0 32px 72px ${alpha(theme.palette.common.black, 0.7)}`
              : `0 32px 72px ${alpha(theme.palette.primary.main, 0.32)}`
            : theme.palette.mode === 'dark' 
              ? `0 10px 28px ${alpha(theme.palette.common.black, 0.5)}`
              : `0 10px 32px ${alpha(theme.palette.primary.main, 0.16)}`,
          borderRadius: '32px',
          overflow: 'hidden',
          cursor: 'pointer',
          border: theme.palette.mode === 'dark'
            ? `1.5px solid ${alpha(theme.palette.primary.main, 0.36)}`
            : `1.5px solid ${alpha(theme.palette.primary.main, 0.18)}`,
          backgroundColor: theme.palette.mode === 'dark' 
            ? alpha(theme.palette.grey[900], 0.7) 
            : '#ffffff',
        }}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        {post.coverImage && (
          <Box sx={{ height: featured ? 240 : 160, overflow: 'hidden', position: 'relative' }}>
            <Link to={`/blog/${post.slug}`} style={{ textDecoration: 'none' }}>
              <LazyImage 
                src={post.coverImage} 
                alt={post.title} 
                height="100%"
                width="100%"
                objectFit="cover"
                borderRadius={0}
                enableZoom={true}
                onLoad={() => setImageLoaded(true)}
                onError={() => console.error('ArticleCard - 图片加载失败:', post.coverImage)}
                placeholder="/assets/blog/placeholder.svg"
              />
            </Link>
            
            {/* 收藏功能已禁用
            <Box 
              sx={{ 
                position: 'absolute', 
                top: 8, 
                right: 8, 
                display: 'flex', 
                gap: 0.5,
                opacity: isHovered ? 1 : 0,
                transition: 'opacity 0.2s ease'
              }}
            >
              <Tooltip title={isBookmarked ? "取消收藏" : "收藏"}>
                <IconButton 
                  size="small" 
                  onClick={handleBookmarkToggle}
                  sx={{ 
                    backgroundColor: 'rgba(255, 255, 255, 0.8)',
                    backdropFilter: 'blur(4px)',
                    '&:hover': {
                      backgroundColor: 'rgba(255, 255, 255, 0.9)',
                    }
                  }}
                >
                  {isBookmarked ? <Bookmark color="primary" /> : <BookmarkBorder />}
                </IconButton>
              </Tooltip>
              
              <Tooltip title="分享">
                <IconButton 
                  size="small" 
                  onClick={handleShare}
                  sx={{ 
                    backgroundColor: 'rgba(255, 255, 255, 0.8)',
                    backdropFilter: 'blur(4px)',
                    '&:hover': {
                      backgroundColor: 'rgba(255, 255, 255, 0.9)',
                    }
                  }}
                >
                  <Share />
                </IconButton>
              </Tooltip>
            </Box>
            */}
          </Box>
        )}
        
        <CardContent sx={{ flexGrow: 1, pb: 2, pt: 4.5 }}>
          <Typography 
            variant={featured ? "h4" : "h5"} 
            component={Link}
            to={`/blog/${post.slug}`}
            gutterBottom
            sx={{ 
              fontWeight: 900,
              lineHeight: 1.35,
              fontSize: featured ? '2.15rem' : '1.6rem',
              color: theme.palette.mode === 'dark' ? '#ffffff' : '#2a2a2a',
              textDecoration: 'none',
              display: '-webkit-box',
              WebkitLineClamp: 2,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
              transition: 'all 0.55s cubic-bezier(0.4, 0, 0.2, 1)',
              mb: 3.5,
              '&:hover': {
                color: '#667eea',
                transform: 'translateX(10px)',
              }
            }}
          >
            {post.title}
          </Typography>
          
          <Typography 
            variant="body2" 
            color="text.secondary" 
            paragraph
            sx={{ 
              display: '-webkit-box',
              WebkitLineClamp: featured ? 3 : 2,
              WebkitBoxOrient: 'vertical',
              overflow: 'hidden',
              mb: 4,
              fontSize: '1.1rem',
              lineHeight: 1.8,
              color: theme.palette.mode === 'dark' ? '#c0c0c0' : '#707070',
              transition: 'all 0.45s ease',
              fontWeight: 400,
            }}
          >
            {post.excerpt}
          </Typography>
          
          {post.tags && post.tags.length > 0 && (
            <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1.75, mb: 4 }}>
              {post.tags.slice(0, featured ? 6 : 3).map((tag) => (
                <Chip 
                  key={tag} 
                  label={tag} 
                  size="small" 
                  variant="outlined" 
                  sx={{ 
                    fontSize: '0.925rem',
                    height: 38,
                    borderRadius: '20px',
                    px: 2,
                    borderColor: theme.palette.mode === 'dark'
                      ? alpha(theme.palette.primary.main, 0.6)
                      : alpha(theme.palette.primary.main, 0.5),
                    color: theme.palette.mode === 'dark' ? '#f0f0f0' : '#667eea',
                    backgroundColor: theme.palette.mode === 'dark' 
                      ? alpha(theme.palette.primary.main, 0.18)
                      : alpha(theme.palette.primary.main, 0.12),
                    transition: 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
                    fontWeight: 700,
                    '&:hover': {
                      backgroundColor: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                      color: '#ffffff',
                      borderColor: 'transparent',
                      transform: 'scale(1.22)',
                      boxShadow: `0 12px 28px ${alpha(theme.palette.primary.main, 0.5)}`
                    }
                  }}
                />
              ))}
              {post.tags.length > (featured ? 6 : 3) && (
                <Chip 
                  label={`+${post.tags.length - (featured ? 6 : 3)}`} 
                  size="small" 
                  variant="outlined" 
                  sx={{ 
                    fontSize: '0.925rem', 
                    height: 38,
                    borderRadius: '20px',
                    borderColor: theme.palette.mode === 'dark'
                      ? alpha(theme.palette.primary.main, 0.6)
                      : alpha(theme.palette.primary.main, 0.5),
                    color: theme.palette.mode === 'dark' ? '#f0f0f0' : '#667eea',
                    backgroundColor: theme.palette.mode === 'dark'
                      ? alpha(theme.palette.primary.main, 0.18)
                      : alpha(theme.palette.primary.main, 0.12),
                    fontWeight: 700,
                  }}
                />
              )}
            </Box>
          )}
          
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', pt: 3, borderTop: theme.palette.mode === 'dark'
            ? `1.5px solid ${alpha(theme.palette.primary.main, 0.24)}`
            : `1.5px solid ${alpha(theme.palette.primary.main, 0.14)}` }}>
            <Box sx={{ display: 'flex', alignItems: 'center' }}>
              <Avatar 
                sx={{ 
                  width: 60, 
                  height: 60,
                  mr: 2.75, 
                  transition: 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
                  border: theme.palette.mode === 'dark'
                    ? `3.5px solid ${alpha(theme.palette.primary.main, 0.55)}`
                    : `3.5px solid ${alpha(theme.palette.primary.main, 0.4)}`,
                  '&:hover': {
                    transform: 'scale(1.22) rotate(10deg)',
                    borderColor: theme.palette.primary.main,
                    boxShadow: `0 10px 24px ${alpha(theme.palette.primary.main, 0.5)}`
                  },
                }}
                src={post.author.picture}
                alt={post.author.name}
              >
                {post.author.name.charAt(0)}
              </Avatar>
              <Typography 
                variant="body2" 
                sx={{ 
                  fontSize: '1.1rem',
                  fontWeight: 800,
                  color: theme.palette.mode === 'dark' ? '#ffffff' : '#2a2a2a',
                  transition: 'all 0.45s ease',
                  '&:hover': {
                    color: '#667eea',
                    transform: 'translateX(5px)',
                  }
                }}
              >
                {post.author.name}
              </Typography>
            </Box>
            
            <Box sx={{ display: 'flex', alignItems: 'center', color: 'text.secondary' }}>
              <CalendarToday 
                sx={{ 
                  fontSize: 20, 
                  mr: 1, 
                  color: theme.palette.mode === 'dark' ? '#b8b8b8' : '#6a6a6a',
                  transition: 'all 0.4s ease'
                }} 
              />
              <Typography 
                variant="body2" 
                sx={{ 
                  fontSize: '0.95rem',
                  fontWeight: 700,
                  color: theme.palette.mode === 'dark' ? '#b8b8b8' : '#6a6a6a',
                }}
              >
                {post.date ? formatDate(post.date) : (post.createdAt ? formatDate(post.createdAt) : '')}
              </Typography>
            </Box>
          </Box>
        </CardContent>
        
        <CardActions sx={{ justifyContent: 'flex-end', px: 4, pb: 4, pt: 2 }}>
          <Button 
            component={Link}
            to={`/blog/${post.slug}`}
            size="medium"
            sx={{ 
              fontWeight: 800,
              fontSize: '1.1rem',
              color: '#667eea',
              px: 4.5,
              py: 2,
              borderRadius: '30px',
              textTransform: 'none',
              transition: 'all 0.5s cubic-bezier(0.4, 0, 0.2, 1)',
              border: '2.5px solid',
              borderColor: theme.palette.mode === 'dark'
                ? alpha('#667eea', 0.6)
                : alpha('#667eea', 0.5),
              backgroundColor: 'transparent',
              '&:hover': {
                backgroundColor: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                color: '#ffffff',
                borderColor: 'transparent',
                transform: 'translateY(-5px)',
                boxShadow: `0 14px 36px ${alpha('#667eea', 0.5)}`,
                px: 5,
              }
            }}
          >
            阅读更多 →
          </Button>
        </CardActions>
      </Card>
    </Zoom>
  );
};

export default ArticleCard;