import { createSlice, PayloadAction } from '@reduxjs/toolkit'

interface MediaLoadingState {
  isPreloading: boolean
  preloadProgress: number
  preloadMessage: string
  lastPreloadTime: string | null
  preloadError: string | null
}

const initialState: MediaLoadingState = {
  isPreloading: false,
  preloadProgress: 0,
  preloadMessage: '',
  lastPreloadTime: null,
  preloadError: null
}

const mediaLoadingSlice = createSlice({
  name: 'mediaLoading',
  initialState,
  reducers: {
    setPreloadingState: (state, action: PayloadAction<boolean>) => {
      state.isPreloading = action.payload
      if (action.payload) {
        state.preloadProgress = 0
        state.preloadMessage = '开始加载...'
        state.preloadError = null
      }
    },
    updatePreloadProgress: (state, action: PayloadAction<{ progress: number; message: string }>) => {
      state.preloadProgress = action.payload.progress
      state.preloadMessage = action.payload.message
    },
    setPreloadError: (state, action: PayloadAction<string>) => {
      state.preloadError = action.payload
      state.isPreloading = false
    },
    setPreloadComplete: (state) => {
      state.isPreloading = false
      state.preloadProgress = 100
      state.preloadMessage = '加载完成'
      state.lastPreloadTime = new Date().toISOString()
      state.preloadError = null
    },
    resetPreloadState: (state) => {
      state.isPreloading = false
      state.preloadProgress = 0
      state.preloadMessage = ''
      state.preloadError = null
    }
  }
})

export const {
  setPreloadingState,
  updatePreloadProgress,
  setPreloadError,
  setPreloadComplete,
  resetPreloadState
} = mediaLoadingSlice.actions

export default mediaLoadingSlice.reducer