import React from 'react'
import { useNavigate, useLocation } from 'react-router-dom'
import { Box, Tabs, Tab, Typography, Breadcrumbs, Link, IconButton } from '@mui/material'
import { styled } from '@mui/material/styles'
import {
  Home as HomeIcon,
  VideoLibrary as VideoLibraryIcon,
  PhotoLibrary as PhotoLibraryIcon,
  MusicNote as MusicNoteIcon,
  ArrowBack as ArrowBackIcon
} from '@mui/icons-material'

const StyledTabs = styled(Tabs)(({ theme }) => ({
  marginBottom: theme.spacing(3),
  '& .MuiTabs-indicator': {
    height: 3,
    borderRadius: 3,
  },
  '& .MuiTab-root': {
    textTransform: 'none',
    fontSize: '1rem',
    fontWeight: 500,
    minWidth: 120,
  }
}))

const NavigationContainer = styled(Box)(({ theme }) => ({
  marginBottom: theme.spacing(4),
}))

const TabPanel = ({ children, value, index }: { children: React.ReactNode, value: number, index: number }) => {
  return (
    <div
      role="tabpanel"
      style={{ display: value !== index ? 'none' : 'block' }}
      id={`entertainment-tabpanel-${index}`}
      aria-labelledby={`entertainment-tab-${index}`}
    >
      {value === index && <Box>{children}</Box>}
    </div>
  )
}

interface EntertainmentNavigationProps {
  children: React.ReactNode
  currentTab?: number
  onTabChange?: (tab: number) => void
  showBackButton?: boolean
  title?: string
  subtitle?: string
}

const EntertainmentNavigation: React.FC<EntertainmentNavigationProps> = ({
  children,
  currentTab = 0,
  onTabChange,
  showBackButton = false,
  title,
  subtitle
}) => {
  const navigate = useNavigate()
  const location = useLocation()

  const handleTabChange = (_: React.SyntheticEvent, newValue: number) => {
    if (onTabChange) {
      onTabChange(newValue)
      return
    }

    // 默认导航逻辑
    switch (newValue) {
      case 0:
        navigate('/entertainment/music')
        break
      case 1:
        navigate('/entertainment/PhotoWall')
        break
      case 2:
        navigate('/entertainment/MediaLibrary')
        break
      default:
        break
    }
  }

  const getCurrentTabFromPath = () => {
    const path = location.pathname
    if (path.includes('/music')) return 0
    if (path.includes('/PhotoWall')) return 1
    if (path.includes('/MediaLibrary')) return 2
    return 0
  }

  const tabValue = onTabChange ? currentTab : getCurrentTabFromPath()

  return (
    <NavigationContainer>
      {/* 面包屑导航 */}
      <Breadcrumbs sx={{ mb: 2 }}>
        <Link underline="hover" color="inherit" href="/" onClick={(e) => { e.preventDefault(); navigate('/') }}>
          <HomeIcon sx={{ mr: 0.5 }} fontSize="inherit" />
          首页
        </Link>
        <Typography color="text.primary">
          休闲娱乐
        </Typography>
      </Breadcrumbs>

      {/* 页面标题和返回按钮 */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box>
          {title && (
            <Typography variant="h3" component="h1" gutterBottom fontWeight="bold">
              {title}
            </Typography>
          )}
          {subtitle && (
            <Typography variant="h6" color="text.secondary">
              {subtitle}
            </Typography>
          )}
        </Box>
        {showBackButton && (
          <IconButton
            onClick={() => navigate('/entertainment')}
            sx={{ height: 'fit-content' }}
            title="返回休闲娱乐"
          >
            <ArrowBackIcon />
          </IconButton>
        )}
      </Box>

      {/* 选项卡导航 */}
      <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
        <StyledTabs
          value={tabValue}
          onChange={handleTabChange}
          aria-label="娱乐模块导航"
          variant="scrollable"
          scrollButtons="auto"
        >
          <Tab
            icon={<MusicNoteIcon sx={{ mr: 1 }} />}
            label="音乐"
            iconPosition="start"
          />
          <Tab
            icon={<PhotoLibraryIcon sx={{ mr: 1 }} />}
            label="照片墙"
            iconPosition="start"
          />
          <Tab
            icon={<VideoLibraryIcon sx={{ mr: 1 }} />}
            label="媒体库"
            iconPosition="start"
          />
        </StyledTabs>
      </Box>

      {/* 内容区域 */}
      {typeof children === 'function' ? children(tabValue) : children}
    </NavigationContainer>
  )
}

export default EntertainmentNavigation